('world-needs-sunday', 'col-basic-bitset-general', 'bitset 优化（通法与技巧）', $AKB355$## 算法原理

**一句话结论**：把「一堆彼此独立的布尔状态」按位打包进机器字，让原本逐个处理的循环变成一次整字并行的位运算，常数缩小约一个字长（通常 $64$）。

**判断能不能用**：同时满足下面三条才值得上 bitset——

1. 每个状态只有**两种取值**（可达/不可达、存在/不存在、奇/偶）；
2. 转移是**逐元素**的布尔运算（`|`、`&`、`^`），并且常常伴随一个**整体偏移**（对应「选了这个物品后状态整体移动」）；
3. 状态总量与位宽的乘积**足够大**（一般 $n \ge 10^3$ 量级），否则打包带来的开销比省下的还多。

把整体偏移写成移位、把逐元素合并写成按位或，就得到了 OI 里几乎所有 bitset 优化的统一形态：

$$dp \mathrel{|}= (dp \ll w)$$

左边是「原来的状态集合」，右边是「作出这次选择后到达的状态集合」。这一行就是下面所有 trick 的母版。

具体的 Floyd 传递闭包案例见 [bitset 优化](basic-bitset)，本篇负责讲通法与各种变体。

## 语法速查

### `std::bitset`：定长位集

`std::bitset<N>` 是**长度在编译期固定**的 0/1 序列，每个元素只占 1 bit，`&` `|` `^` `~` `<<` `>>` 以整字为单位并行执行。

```cpp
#include <bitset>
bitset<N> bs;                  // N 必须是编译期常量
bitset<N> bs(0);               // 全 0（默认）
bitset<N> bs(0x0f);            // 用 unsigned long 初始化
bitset<N> bs(string("1010"));  // 用 0/1 字符串初始化
```

| 类别 | 用法 | 说明 |
|---|---|---|
| 访问 | `bs[pos]` | 第 `pos` 位的引用，可读可写，**不检查越界** |
| 访问 | `bs.test(pos)` | 第 `pos` 位是否为 1，越界抛 `out_of_range` |
| 容量 | `bs.size()` | 返回 `N` |
| 统计 | `bs.count()` | 置位个数，$O(N/64)$ |
| 状态 | `bs.any()` / `bs.none()` / `bs.all()` | 是否存在 1 / 是否全 0 / 是否全 1 |
| 修改 | `bs.set()` / `bs.reset()` / `bs.flip()` | 全置 1 / 全置 0 / 全体取反 |
| 修改 | `bs.set(pos)` / `bs.set(pos, val)` | 单点置 1 / 单点置为 `val` |
| 修改 | `bs.reset(pos)` / `bs.flip(pos)` | 单点置 0 / 单点取反 |
| 运算 | 按位与、按位或、按位异或、按位取反 | 返回新的 bitset |
| 移位 | `bs << k` / `bs >> k` | 整体移位，空出的位补 0 |
| 转换 | `bs.to_string()` / `bs.to_ulong()` / `bs.to_ullong()` | 转字符串 / 无符号整数 |

位运算与复合赋值的完整写法：

```cpp
a & b;   a | b;   a ^ b;   ~a;
a << k;  a >> k;
a &= b;  a |= b;  a ^= b;  a <<= k;  a >>= k;
```

**竞赛要点**：一次位运算的实际耗时约为 $O(N/w)$（$w$ 为机器字长），$N$ 在 $10^4\sim10^5$ 时远快于手写循环。典型用法就是把布尔型 DP 数组压成 bitset 做整体转移。

### `std::list`：双向链表（OI 中基本不用）

```cpp
#include <list>
list<int> lt;

lt.front(); lt.back();          // 首/尾元素，没有 lt[pos]
lt.push_front(x); lt.push_back(x);
lt.pop_front();  lt.pop_back();
lt.insert(pos, x);  lt.erase(pos);
lt.clear(); lt.empty(); lt.size();

lt.sort();                      // 链表自带排序，不能用 std::sort
lt.merge(other);                // 合并两个有序链表
lt.splice(pos, other);          // 把 other 的节点剪到 pos 前，不拷贝
lt.remove(x);                   // 删除所有值为 x 的元素
lt.unique();                    // 删除相邻重复元素
```

语法是完整的，但竞赛里几乎不用，原因有三：

1. **缓存局部性极差**。节点在堆上逐个分配、地址不连续，遍历时每次都可能是缓存未命中；`vector` 能连续预取，实测通常全面更快。
2. **每个节点都有额外开销**。除了数据本身还要存前驱/后继指针和堆的管理信息，每次插入删除都是一次 `new`/`delete`，单次常数远大于数组下标移动。
3. **有更好的替代**。真需要链表结构时（邻接表、可持久化、需要精细控制节点关系），标准做法是**数组模拟静态链表**：开 `e[N]`、`ne[N]`（必要时加 `pre[N]`），用下标代替指针，没有动态分配、内存可控、行为可预测。

一句话：`list` 的 $O(1)$ 插入在纸面上成立，但在卡常语境下换不来实际收益；这和我们用数组模拟 `stack`、`queue` 是同一个道理。

## 一般处理方式

把一段朴素代码改造成 bitset 版本，固定走这三步：

1. **找到最内层的「逐元素布尔赋值」**。典型形态是 `a[j] |= b[j - k]`、`g[i][j] |= g[k][j]`、`ok[j] = ok[j] || ok[j - w]`。
2. **把它读成「整段与整段之间的位运算」**。`j` 这一维整体消失，变成 bitset 的下标；`b[j-k]` 变成 `b << k`；逐元素或变成整行 `|`。
3. **换算复杂度判断值不值**。原来是 $O(nm)$，现在约 $O(nm/64)$。当 $m<64$ 或总运算量本来就小，直接写朴素版更快；当 $n\cdot m$ 达到 $10^8$ 以上，bitset 的收益才明显。

改造时有两个细节容易被忽略：

- **偏移方向**。`dp |= dp << w` 表示「加上 $w$」；如果状态是「剩余容量」这类反向定义，就要用右移。
- **边界截断**。超出上限的位会自动溢出丢弃，这通常是好事（相当于自动过滤非法状态），但要确认题目没有「溢出后回到合法范围」的语义。

## 常见 trick

### 1. 布尔可达性 / 可行性背包

`dp[j]` 表示容量 `j` 是否可达，标量转移是 `dp[j] |= dp[j-w]`，bitset 版一行：

```cpp
dp |= (dp << w);
```

- **多重背包**：每种物品有数量上限，做二进制拆分后对每个 0/1 物品重复上面的式子。
- **恰好用 $k$ 个**：开 `dp[k]` 数组，转移是 `dp[t] |= dp[t-1] << w`，注意要从大到小更新避免重复使用。
- **需要输出方案**：bitset 只记可行性，回溯要另存「每个状态是否由当前物品转移而来」，通常退化成 `vector` + 记录前驱。

### 2. 图上的传递闭包与可达性

- **Floyd 传递闭包**：把邻接矩阵每行压成 bitset，`if (g[i][k]) g[i] |= g[k];`，复杂度 $O(n^3/64)$。
- **DAG 拓扑传播**：按拓扑序逆序处理，`reach[u]` 初值为只有自己，对每条出边 `reach[u] |= reach[v]`，总复杂度 $O(En/64)$；稀疏图上非常划算。
- **有环图**：先 Tarjan 缩点成 DAG 再传播，SCC 内部共享同一个可达集，避免在环上反复迭代。

### 3. 高维偏序

统计「每一维都不超过我」的元素个数：给每个元素 $i$ 开一个 `bitset ans[i]`，逐维处理时把元素按该维排序、维护一个「当前维不超过我」的 `cur`，执行 `ans[i] &= cur`。结束时 `ans[i].count()` 就是答案。

总复杂度约 $O(d n^2/64)$，空间 $O(n^2/8)$ 字节。$n>5000$ 时空间会爆，标准做法是**分块**：每次只处理 $B$ 个元素，把 `bitset` 的宽度压到 $B$，用时间换空间。

### 4. 布尔矩阵乘法

布尔半环下（乘法是 `&`、加法是 `|`），$C[i][j]$ 等于「$A$ 的第 $i$ 行与 $B$ 的第 $j$ 列按位与非零」。`std::bitset` 没有列访问，所以通常**先把 $B$ 转置**，让每一列也是连续的 bitset。复杂度 $O(n^3/64)$。

如果只关心「与之后是否非零」，可以用 `(a & b).any()`；如果要统计个数，用 `count()`，但注意它在循环里是 $O(n/64)$ 的。

### 5. 莫队维护权值存在性

把当前区间的权值集合压成 bitset，`add`/`remove` 就是单点置 1/置 0。想要统计「区间内有多少种权值」时，`count()` 是 $O(V/64)$，比树状数组的 $O(\log V)$ 单点更新慢，所以**只在需要整段位运算时才有优势**（例如配合异或、平移判断）。

若存在重复权值，常用做法是把「离散化权值 + 出现次数」编码进下标来区分同一个值的不同出现。

### 6. 加速 LCS

最长公共子序列的标量 DP 是 $O(nm)$，用 bitset 可以做到 $O(nm/64)$。记 `S` 中每个字符出现的位置集合 `ch[c]`，扫描 `T` 的每个字符做一次「进位加法」：

```cpp
bitset<N> x, y;
for (char c : T) {
    x = ch[c] | pre;
    pre = (pre << 1) | 1;
    y = x & ~(x - (pre << 1));
    pre = x ^ (x + y);
}
// 最终 pre.count() 就是 LCS 长度
```

这是「用位运算模拟加法进位」的经典操作，理解不了细节也没关系，记住**LCS 也能位并行**即可。

### 7. 位并行 BFS / 距离分层

邻接矩阵的每一行压成 bitset 后，「下一步能到达哪些点」就是 `nxt |= adj[v]`（$v$ 是当前层的所有点）。每一层对整行做一次或运算，复杂度从 $O(\sum \text{deg})$ 降到 $O(n^2/64)$；对**稠密图**（如 $n\le2000$ 且边很多）反而更快。

### 8. 子树 / 集合合并

把每个点的「子树内出现的值」压成 bitset，自底向上 `bs[u] |= bs[v]`，就可以 $O(n\cdot V/64)$ 回答「子树里有哪些值」「子树内有几种值」。值域大时先离散化，或者按块分段存多个 bitset。

### 9. 区间存在性与 mex

对「下标」或「权值」建 bitset，做区间查询时把对应段的位取出、用 `(seg & mask).any()` 判断存在性。`mex` 则从低位开始找第一个 0：可以按段取反后配合 `_Find_first`（libstdc++ 扩展）快速定位。

### 10. 埃氏筛

`bitset` 存「是否为合数」，筛的时候直接 `isp |= (isp << i)` 跳过整段，比分段标记更省内存：$10^8$ 的筛法只需 12.5 MB。注意 `bitset` 的模板参数必须是编译期常量，筛上界要写成宏。

### 11. 枚举置位位置

`for (i = 0; i < N; i++) if (bs[i])` 在稀疏时是纯浪费。libstdc++ 的 `std::bitset` 提供扩展接口 `bs._Find_first()` 与 `bs._Find_next(pos)`，可以 $O(N/64)$ 地遍历所有置位位置；可移植写法是把内部字当 `uint64_t` 取出来，再配合 `__builtin_ctzll` 逐字消去最低位。

## 逐行代码解析

本篇没有完整的 `.cpp`，下面把文中反复出现的几个关键片段逐行拆开。它们就是所有 bitset 优化的「零件」。

### 母版：`dp |= (dp << w)`

```cpp
dp |= (dp << w);
```

- `dp` 是一个 `bitset<W>`，第 `j` 位为 1 表示「容量 `j` 可达」。
- `dp << w` 把每个可达状态整体右移到 `j + w`，对应「装进一个重量为 `w` 的物品」。
- `|=` 把「不装这个物品」的旧状态与新状态合并，这正是 0/1 背包「选或不选」的布尔版本。
- 整个式子等价于对 `j` 从 `W` 到 `w` 倒序执行 `dp[j] |= dp[j - w]`，但一次位运算就处理完了所有 `j`。

### Floyd：`if (g[i][k]) g[i] |= g[k];`

```cpp
if (g[i][k]) g[i] |= g[k];
```

- `g[i]` 是第 `i` 行的可达集合，`g[i][k]` 判断「$i$ 能否到 $k$」。
- 只有 `g[i][k]` 为真时，才需要把「$k$ 能到的所有点」并入第 `i` 行；这一步等价于原来的 `for (j) g[i][j] |= g[k][j]`。
- 单次是 $O(n/64)$ 的字运算，三层循环合计 $O(n^3/64)$。

### LCS：用位运算模拟进位

```cpp
x = ch[c] | pre;
pre = (pre << 1) | 1;
y = x & ~(x - (pre << 1));
pre = x ^ (x + y);
```

- `ch[c]` 是字符 `c` 在第一个串中所有出现位置的位集合。
- `x` 把「当前位置可匹配的点」与上一轮的进位状态合并。
- `y = x & ~(x - (pre << 1))` 用减法制造借位，精确定位出这一轮真正新增的匹配位置。
- 最后一行的 `x + y` 恢复进位链，`pre` 重新变成「进行中的匹配状态」。
- 扫描完第二个串后 `pre.count()` 就是 LCS 长度，整体 $O(nm/64)$。

### 语法部分：`bs.set(pos, val)` 与 `bs.test(pos)`

```cpp
bs.set(pos);        // 单点置 1
bs.set(pos, val);   // 单点置为 val
bs.reset(pos);      // 单点置 0
bs.test(pos);       // 读取，越界抛异常
```

- `set` / `reset` 是写操作，`test` 是带边界检查的读操作。
- 热路径里读单点通常用 `bs[pos]`（不检查越界，更快），只在需要防御性检查时用 `test`。
- `bs.set(pos, val)` 在需要「按条件写入」时最方便，省掉一个 `if`。

## 适用场景

**适合用**：

- 布尔可行性 DP：子集和、0/1 背包、多重背包（二进制拆分后）、「恰好用 $k$ 个」的分层背包；
- 图上的可达性：Floyd 传递闭包、DAG 拓扑传播、稠密图的逐层 BFS；
- 高维偏序统计（$n$ 在几千量级，必要时分块）；
- 布尔半环下的矩阵乘法；
- 字符串的位并行算法（LCS 一类）。

**不适合用**：

- 状态量本身很小（几百以内），打包收益抵不过开销；
- 需要输出具体方案或路径（bitset 只保留可行性）；
- 需要频繁单点查询、频繁 `count()`；
- 内存吃紧：$n$ 个长度 $n$ 的 bitset 是 $n^2/8$ 字节，$n$ 上万就要分块或换思路；
- 长度只能在运行时确定，且远超预留上限。

## 复杂度分析

单次位运算是 $O(N/64)$，这是所有分析的出发点。常见换算：

| 原始做法 | bitset 做法 |
|---|---|
| 布尔背包 $O(nW)$ | $O(nW/64)$ |
| Floyd 闭包 $O(n^3)$ | $O(n^3/64)$ |
| DAG 可达性 $O(En)$ | $O(En/64)$ |
| $d$ 维偏序 $O(dn^2)$ | $O(dn^2/64)$ |
| 布尔矩阵乘法 $O(n^3)$ | $O(n^3/64)$ |

空间上，$n$ 个长度 $n$ 的 bitset 是 $n^2/8$ 字节；$n=5000$ 时约 3 MB，$n=20000$ 时约 50 MB，再大就要考虑分块或改写。

## 常见陷阱与注意事项

- **尺寸必须是编译期常量**。`int n; cin >> n; bitset<n> b;` 编译不过。运行时长度只能用 `boost::dynamic_bitset` 或手写 `vector<uint64_t>`。
- **别在热路径反复 `count()`**。它是 $O(N/64)$，循环里调用会把收益吃光，能增量维护计数就增量维护。
- **注意栈空间**。局部 `bitset<10^8>` 约 12.5 MB，直接爆栈；改成全局或 `static`。
- **移位量不要超过位数**。`bs << k` 的 `k` 大于等于 `N` 时结果全 0，逻辑上往往等价于「非法状态」，但如果你本想回绕就必须自己处理。
- **`to_ulong()` 会溢出**。超过 `unsigned long` 宽度会抛异常，大 bitset 别用。
- **`operator[]` 不检查越界**，负下标是未定义行为。
- **`list` 不是 `bitset` 的替代品**：两者解决的是完全不同的问题，这里放在一起只是为了把 STL 语法集中交代。

## 对比与扩展

- **与 bool 数组对比**：`bool` 数组每个元素占 1 字节，bitset 占 1 bit，空间差 8 倍；时间上 bitset 还能把 $64$ 个元素的布尔运算合并成一次，差距更大。
- **与手写 `vector<uint64_t>` 对比**：思路完全一致，只是要自己算 `word = j >> 6`、`bit = j & 63`。手写的优势是**长度可以运行时决定**，劣势是要自己实现 `|=`、`count()`、移位这些操作。
- **与 bitmask DP 的区别**：状压 DP 用二进制位**编码集合状态**，改的是状态定义；bitset 优化只改变**运算方式**，状态本身仍是普通布尔数组。
- **什么时候不该用**：状态量小（$<1000$）、需要频繁单点查询、需要输出具体方案、内存不允许 $n^2/8$ 时，老老实实写标量 DP 更稳。$AKB355$, '实用工具', array['bitset', '位运算', '卡常', '可行性DP', '传递闭包', '布尔矩阵', '莫队', '偏序'], 'col-hub-utility-stl', null, 'knowledge'),
('world-needs-sunday', 'col-basic-bitset', 'bitset 优化', $AKB356$## 算法原理

**一句话结论**：bitset 把「一行布尔值」打包成若干个 64 位整数，把「一行对一行逐元素做布尔或」变成一次按机器字并行的整块或运算，常数缩小约 64 倍。用在 Floyd 传递闭包上，就是 $O(n^3)$ 的常数层面降到 $O(n^3/64)$。

**解决的问题**：传递闭包。以洛谷 P2881 [USACO07MAR] Ranking the Cows G 为例：有 $n$ 头奶牛、$m$ 条已知大小关系 $x < y$，关系具有传递性（$a<b,\ b<c \Rightarrow a<c$）。把牛看成点、$x<y$ 看成有向边 $x \to y$，则点对 $(i,j)$ 的关系已知，当且仅当 $i$ 能到达 $j$ 或 $j$ 能到达 $i$；答案 = 总点对数 $\dfrac{n(n-1)}{2}$ 减去关系已知的点对数。这就是传递闭包问题。

**朴素做法的瓶颈**：用 `bool reach[n][n]` 表示可达性，Floyd 三层循环：

```text
for k: for i: for j: if (reach[i][k] && reach[k][j]) reach[i][j] = true;
```

复杂度 $O(n^3)$，$n=1000$ 时约 $10^9$ 次判断，很容易超时。

**核心思想怎么来的**：固定 $k$ 和 $i$，若 `reach[i][k]` 为真，内层 $j$ 循环做的其实是：对每个 $j$，`reach[i][j] |= reach[k][j]`——等价于「第 $i$ 行整体或上第 $k$ 行」。逐元素的布尔或，可以改写成整行的按位或；而一行 0/1 如果打包成整数串，一次操作就能并行处理很多个 $j$。这正是 bitset 的切入点。

**bitset 是什么**：`std::bitset<N>` 是 C++ 标准库的定长二进制串，两个关键特点：每个元素只占 1 位（不是 1 字节）；`&` `|` `^` `~` `<<` `>>`、`count()` 等对整排位一次性运算，底层按 64 位机器字并行。本题把每个 `vis[i]`（点 $i$ 能到达哪些点）压成一整个 bitset：第 $j$ 位为 1 表示 $i$ 能到达 $j$。

**为什么这样做是对的**：对每个 $k$，当第 $k$ 轮处理完所有 $i$ 后，「只允许以编号 $\le k$ 的点作中间点」的可达关系全部算对（归纳：$k-1$ 轮成立，第 $k$ 轮把所有经过 $k$ 的路径补上）。`vis[i] |= vis[k]` 与朴素的内层 $j$ 循环在全部 $j$ 上的计算结果完全相同，只改变了计算方式，所以正确性与朴素 Floyd 传递闭包一致。

## 核心公式 / 状态定义与转移方程

**状态定义**：`vis[i]` 是长度为 `nmax` 的 bitset，`vis[i][j] = 1` 表示点 $i$ 能到达点 $j$（含 $j = i$）。下标从 0 开始，`vis[i][0]` 是最低位。

**初始化**：

- 对每条已知边 $x < y$：`vis[x][y] = 1`。
- 自反：`vis[i][i] = 1`，让转移形式统一（`vis[i][k]` 为真时整行并入不会漏掉 $k$ 自身）；代价是统计时多出 $n$ 个自环。

**转移方程**：

```text
if (vis[i][k]) vis[i] |= vis[k];
```

含义：若 $i$ 能到达 $k$，则 $k$ 能到达的所有点 $i$ 也都能到达，把 $k$ 的可达集合整行并入 $i$。$k$ 必须放最外层（与朴素 Floyd 相同），保证每一步用的都是已更新过的中间点信息。

**答案公式**：令 $sum = \sum_{i=1}^{n} vis[i].count()$（可达对数，含 $n$ 个自环），已知关系数（不含自反）为 $sum - n$，答案：

$$ans = \dfrac{n(n-1)}{2} - (sum - n) = \dfrac{n(n-1)}{2} - sum + n$$

**底层字映射**：bitset 内部用 64 位字数组存位：第 $j$ 位落在 `word = j >> 6`（即 $j/64$）号字、`bit = j & 63`（即 $j \bmod 64$）位。长度为 $N$ 的整行或只需约 $N/64$ 次字运算。

**手算示例**：$n=5$，已知关系 $1<2$、$2<3$、$4<5$。

初始（只列出用到的位，第 $j$ 列对应 vis 的第 $j$ 位）：

```text
vis[1]: 0 1 0 0 0     （1 能到 2）
vis[2]: 0 0 1 0 0     （2 能到 3）
vis[3]: 0 0 0 0 0
vis[4]: 0 0 0 0 1     （4 能到 5）
vis[5]: 0 0 0 0 0
```

自反后每个 `vis[i][i]` 置 1。$k=1$ 轮无变化；$k=2$ 轮：`vis[1][2]` 为真，`vis[1] |= vis[2]`，第 3 位变 1；$k=3$ 轮：`vis[1][3]` 为真，并入 `vis[3]` 无新增；$k=4$、$k=5$ 轮同理无新增。最终：

```text
vis[1]: 1 1 1 0 0     （count = 3）
vis[2]: 0 1 1 0 0     （count = 2）
vis[3]: 0 0 1 0 0     （count = 1）
vis[4]: 0 0 0 1 1     （count = 2）
vis[5]: 0 0 0 0 1     （count = 1）
```

$sum = 9$，答案 $= \dfrac{5 \times 4}{2} - 9 + 5 = 6$。已知关系 4 对（(1,2)、(1,3)、(2,3)、(4,5)），确实还差 6 对。

## 逐行代码解析

代码拆成 5 个模块，按顺序拼接即完整程序。

### 模块 1 头文件与全局数组

```cpp
#include<bits/stdc++.h>
using namespace std;
const int nmax = 1005;
bitset<nmax> vis[nmax];
```

- `vis[i]` 是第 $i$ 行，即点 $i$ 的可达集合，第 $j$ 位为 1 表示 $i$ 能到达 $j$。
- `nmax` 取 1005 覆盖 $n \le 1000$；bitset 的模板参数必须是编译期常量，否则编译不过。
- 全局数组默认全 0，不需要手动清零。

### 模块 2 main 与读入

```cpp
int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr); cout.tie(nullptr);
	int n, m;
	cin >> n >> m;
	for (int i = 1; i <= m; i++)
	{
		int x, y;
		cin >> x >> y;
		vis[x][y] = true;
	}

```

- 关闭同步加速输入输出，$m$ 较大时读入也要快。
- 每条已知关系只置 `vis[x][y] = 1`（一条有向边）；反向位不能预先置，留给传递闭包自己推出来。

### 模块 3 自反初始化

```cpp
	for (int i = 1; i <= n; i++) vis[i][i] = true;

```

- 每个点自己可达自己，保证 `vis[i][k]` 为真时把 `vis[k]` 整行并入不会漏掉 $k$ 自身。
- 不初始化自反位会漏转移：部分可达对只能靠「终点自身」这一跳补齐。
- 代价是统计时多了 $n$ 个自环，答案公式里要相应补偿。

### 模块 4 Floyd 传递闭包

```cpp
	for (int k = 1; k <= n; k++)
	{
		for (int i = 1; i <= n; i++)
		{
			if (vis[i][k]) vis[i] |= vis[k];
		}
	}

```

- `k` 必须最外层：传递闭包要用已经更新过的中间点继续向外扩展；顺序颠倒会漏掉经多个中间点串联的可达对。
- `if (vis[i][k])` 是守卫：只有 $i$ 能到 $k$ 时才并入 $k$ 的行，省掉会错误继承无关可达关系。
- `vis[i] |= vis[k]` 一次处理整行约 1005 位（约 16 个 64 位字），替代朴素的内层 $j$ 循环。

### 模块 5 统计与输出

```cpp
	long long sum = 0;
	for (int i = 1; i <= n; i++) sum += vis[i].count();
	cout << (long long)n * (n - 1) / 2 - sum + n;
	return 0;
}
```

- `count()` 用 popcount 指令数每行的 1，$sum$ 是可达对数（含 $n$ 个自环）。
- `(long long)n * (n - 1) / 2`：先转 `long long` 再乘，防止 $n$ 较大时 int 溢出。
- 答案 = 总点对数 − 已知关系数（不含自反），即 $\dfrac{n(n-1)}{2} - sum + n$。

## 复杂度分析

- **时间**：Floyd 部分有 $n \times n$ 个 (k, i) 组合，每次整行或需约 $n/64$ 次字运算（bitset 长度按 $n$ 计），合计 $O(n^3/64)$；统计部分 $n$ 次 `count()` 共 $O(n^2/64)$。渐近意义下与朴素做法同阶（64 是常数），但实际快约 64 倍，$n=1000$ 时从约 $10^9$ 次判断降到约 $1.6 \times 10^7$ 次字运算。
- **空间**：$n$ 个长度为 $n$ 的 bitset 共 $n^2/8$ 字节，$n=1000$ 时约 128 KB；同样规模 `bool` 二维数组约 1 MB。按 64 位字计为 $O(n^2/64)$。

## 适用场景

- **传递闭包 / 可达性**：$n$ 在 500~2000 量级、朴素 $O(n^3)$ 常数吃紧时，把行压成 bitset 直接提速（P2881 就是典型）。
- **DAG 可达性统计**：按拓扑序逆序做 `bit[u] |= bit[v]`（$u \to v$），配合 `count()` 统计每个点能到达的点数（AcWing 164 可达性统计）。
- **0-1 可行性 DP**：子集和 / 0-1 背包可行性可用 `dp |= dp << w` 表示加入重量 $w$。
- **不要用**：长度必须由运行时输入决定且远超预留上限时——`bitset<N>` 的 $N$ 是编译期常量，应改手写 `vector<uint64_t>`；只做少量单点读写、不涉及整行运算时，`bool` 数组即可，bitset 没有收益。

## 常见陷阱与注意事项

1. **忘记 `vis[i][i] = 1`**：自反位缺失会让依赖「终点自身」的可达对漏推；但加上自反后统计必须减 $n$，两处要配套改。
2. **`if (vis[i][k])` 守卫省掉**：会把所有行无条件并入，多算大量不存在的可达关系，答案偏小。
3. **`k` 不在最外层**：颠倒成 $i$ 外层会漏掉经多个中间点串联的可达对；小随机样例往往测不出来，要用链状数据验证。
4. **答案公式符号**：是 $\dfrac{n(n-1)}{2} - sum + n$（等价于减去 $sum - n$），错写成 $- sum - n$ 会多减。
5. **int 溢出**：$n(n-1)$ 先乘再除可能溢出，写 `1LL * n * (n - 1) / 2`。
6. **bitset 长度用了变量**：`int n; cin >> n; bitset<n> ...` 编译不过；动态长度要手写 `vector<uint64_t>` 位集。
7. **`operator[]` 不检查越界**：`vis[i][j]` 的 $j$ 超过模板长度是未定义行为，开数组时长度必须 ≥ 数据上限。
8. **`count()` 返回 `size_t`**：是无符号类型，与负数、减法混合运算时小心无符号转换。
9. **下标从 0 开始**：`vis[i][0]` 是最低位，位下标与从 1 开始的图论点编号是两套下标，混用容易错位（本题 `vis[0]` 整行闲置）。

## 对比与扩展

**bool 二维数组 vs bitset 行压缩**：

| 操作 | bool 二维数组 | bitset 行压缩 |
|---|---|---|
| 单点读写 | O(1) | O(1)（多几次位运算） |
| 整行或 / count | O(N) | O(N/64)（按机器字并行） |
| 空间 | 1 字节/元素 | 1 bit/元素 |
| 越界检查 | 无 | 无 |

严格说 64 是常数，渐近复杂度不变；差距体现在常数的几十倍，对卡时限的传递闭包题就是「过」与「不过」的区别。

**与手写动态位集对比**：长度必须运行时决定时，手写 `vector<uint64_t>` 存位并封装 `|=` 和 `count()`（内部 popcount），思想与 `std::bitset` 完全一致，只是位定位要自己算 `word = j >> 6`、`bit = j & 63`。

**与 bitmask DP 的区别**：bitmask DP（如状压哈密顿路）以「二进制位编码集合状态」为核心，改变的是状态定义；bitset 优化以「整行布尔运算并行化」为核心，只改变运算方式，状态仍是普通布尔矩阵。

**延伸练习**（同一套路的迁移）：

- 洛谷 P4306 [JSOI2010] 连通数：传递闭包后求所有点能到达点数之和，代码结构几乎相同。
- AcWing 164 可达性统计：DAG 上按拓扑逆序做整行或。
- 子集和 / 0-1 背包可行性：`dp |= dp << w`，体会移位用法。$AKB356$, '实用工具', array['bitset', '传递闭包', 'Floyd', '位运算', '卡常'], 'col-hub-utility-stl', null, 'knowledge'),
('Xesir', 'col-basic-discretization--xesir', '离散化 · Xesir', $AKB357$## 算法原理

OI 里很多算法都拿「值」当**下标**——树状数组、权值线段树、计数数组……但值域往往大得离谱，常见 $10^9$。这种情况下数组还没开就已经爆空间了。

**离散化**就是来解决这个的：把值域压扁。

它的本质是**压缩值域**。当值域很大、而实际用到的数很少时，把所有出现过的值收集起来，**排序去重**后用一个小编号代替原值，值域就从 $O(V)$ 降到 $O(n)$。一般题面是 $n \le 10^5$、$V \le 10^9$ 甚至更大，这个优化的收益非常可观：既不开不下大数组，又**保留元素之间的大小关系**。

举个栗子，原数组：

```text
a = [1, 100, 10000, 100, 1]
```

直接开值域 $10000$ 的数组纯属浪费。离散化之后：

```text
排序去重: [1, 100, 10000]
映射编号: 1->1, 100->2, 10000->3
离散化后: [1, 2, 3, 2, 1]
```

和「不离散化、直接用原值当下标」相比，离散化后代码更省空间，也更容易套用那些需要值域作下标的数据结构。

但要注意代价：离散化会**丢掉原值的绝对信息**（比如「两数之差」「两数之积」没法直接从编号还原），所以它只适合**只需要相对大小关系、不需要绝对权值**的场合，否则得额外维护原值。

## 逐行代码解析

下面三块是几种常用写法，都是片段，不要求拼成完整程序。

### 保序离散化

把原值排序去重，再用 `lower_bound` 查每个值对应的排名。这样离散化后的编号**保留了原值的大小关系**，可以直接比较、二分。

```cpp
sort(b + 1, b + n + 1);
int len = unique(b + 1, b + n + 1) - b - 1;
for (int i = 1; i <= n; i++)
    a[i] = lower_bound(b + 1, b + len + 1, a[i]) - b;
```

- `b` 是原数组的副本，`sort` + `unique` 得到去重后的有序序列，长度记为 `len`。
- `lower_bound` 返回迭代器，减去起点 `b` 得到的就是 $1$ 起的排名。
- 效果：

```text
原值:   1, 100, 10000, 100, 1
编号:   1,  2,    3,   2,  1
```

### 哈希替代

如果只需要判断两个值**是否相等**、不关心大小关系，可以直接用哈希表建立「原值 → 编号」的映射，不必排序，适合值域极大且顺序无关的场景。

```cpp
unordered_map<int, int> mp;
int tot = 0;
for (int i = 1; i <= n; i++) {
    if (!mp.count(a[i])) mp[a[i]] = ++tot;
    a[i] = mp[a[i]];
}
```

- 编号按**首次出现顺序**分配，不保序，但 $O(n)$ 期望时间，不用排序。

### 逆映射还原

离散化后如果还要输出原值，额外存一个 `rev` 数组，记下「编号 → 原值」：

```cpp
for (int i = 1; i <= len; i++) rev[i] = b[i];
```

这样查到编号后直接 `rev[id]` 就还原成原值了。

## 复杂度分析

- 时间复杂度：主体是排序，$O(n \log n)$；`unique` 和逐元素 `lower_bound` 都是 $O(n \log n)$。用哈希表替代时，期望 $O(n)$。
- 空间复杂度：$O(n)$，需要一份原值副本和映射数组，和值域 $V$ 无关。

## 适用场景

- **树状数组 / 线段树的下标**：值域大但数据量小时，必须先离散化才能开数组。
- **权值线段树 / 主席树**：维护值域频次，必须先离散化。
- **逆序对统计**：值域大时离散化后再用树状数组求逆序对。
- **扫描线**：矩形面积并、周长并，端点坐标需要离散化。
- **二维数点**：把坐标压到 $O(n)$ 后再套数据结构。

## 常见陷阱与注意事项

1. **区间离散化要补端点**：维护区间 $[l, r]$ 时，只离散化端点会丢掉两个端点之间的「空隙」，需要额外插入 $l-1$ 或 $r+1$（或改用左闭右开）来保证连续性，否则「一段区间是否被完全覆盖」就判断错了。
2. **编号别弄错下标起点**：数组从 $1$ 开始时，`lower_bound(...) - b` 得到的正好是 $1$ 起的排名；从 $0$ 开始则要相应调整，混用极易差 1。
3. **不保序的编号不能比大小**：哈希映射出来的编号只表示「相等 / 不等」，拿它做大小比较或二分是错的。
4. **离散化后要还原原值**：输出答案如果要求原值，记得用 `rev` 数组映射回去。
5. **重复元素**：`unique` 只去相邻重复，所以**必须先 `sort`**；漏了排序会去重失败。

## 对比与扩展

| 方式 | 是否保序 | 适用场景 |
| :--- | :--- | :--- |
| `sort + unique + lower_bound` | 是 | 需要比较大小、二分 |
| 哈希表映射 | 否 | 只需判断相等 |
| 区间离散化 | 是 | 线段覆盖、区间问题 |
| 二维坐标压缩 | 是 | 平面点集、扫描线 |

扩展方向：

- **区间离散化**：在端点集合里补上相邻端点之间的中间点（或 $l-1$ / $r+1$），保住区间的连续性。
- **坐标压缩**：二维点集分别对 $x$、$y$ 离散化，处理完后每个点坐标都压到 $O(n)$，就能用二维数组或二维数据结构维护，典型场景是扫描线求矩形面积并、二维数点。
- 相关知识点见 `ds-segtree-discretize`（离散化 + 线段树）。$AKB357$, '实用工具', array['离散化', '值域压缩', '排序去重', 'lower_bound', '坐标压缩'], 'col-hub-utility-other', null, 'knowledge'),
