('Fohen', 'col-basic-offline--fenfeng', '离线操作（思想） · Fohen', $AKB359$## 算法原理

离线操作是 OI 中一种常见的思想，而非某个具体算法：当「按输入顺序逐个处理」比较困难时，把全部操作（询问、修改等）一次性读入，再按某种合适的顺序统一处理，最后按原始编号还原并输出答案。

其本质是**用「重排操作顺序」换取「更低的单次处理代价」**。很多问题的难点在于按原顺序处理时状态难以维护，或者需要大量重复计算；离线后可以先做预处理、按关键字排序、增量维护答案，从而把重复运算合并、把单次代价摊薄。

与「在线」相对：在线要求对每个询问实时给出答案，且不能预知后续输入；离线则允许看到全部输入后再决定处理顺序。典型流程可概括为三步：**读入全部操作 → 按规则排序或预处理 → 还原输出**。

示例：询问序列原本是 $q_1,q_2,q_3$，若题目允许离线，可按左端点、右端点或时间等关键字排序，变成 $q_2,q_1,q_3$ 处理，处理结束后再按每个询问的原始编号还原输出顺序。

一般情况下，离线算法实现更简单，有时复杂度也更低；但离线也可能被「卡」：若每个询问的真实输入依赖上一次的答案（强制在线），询问就变得不确定，无法离线，这也在变相提示正确解法必须在线。

## 核心公式 / 状态定义与转移方程

离线操作本身没有统一的公式，但可以把「重排后的状态维护」抽象成一个通用模型。

设共有 $m$ 个询问 $q_1,\dots,q_m$，离线允许选择一个重排 $\pi$，依次处理 $q_{\pi(1)},\dots,q_{\pi(m)}$，得到 $ans_{\pi(k)}$，最后按原始编号还原出 $ans_1,\dots,ans_m$。

状态定义：处理到第 $k$ 个询问时，维护一个「当前状态」$S_k$（例如前缀 $[1,r]$ 的统计信息、当前区间 $[l,r]$ 的答案、当前并查集的连通状态等），以及指向当前询问的指针。

转移：从上一个询问的状态 $S_{k-1}$ 移动到当前询问的状态 $S_k$。以莫队维护区间为例，设当前区间为 $[l,r]$，目标区间为 $[l',r']$，指针总移动量为：

$$
\lvert l-l' \rvert + \lvert r-r' \rvert
$$

排序（即选择重排 $\pi$）的目标就是让所有询问之间指针移动的总量尽可能小，从而摊薄单次更新的代价。不同离线算法只在这个「重排规则」和「状态增量维护」上有所区别。

## 逐行代码解析

以下为离线操作的三步思想框架（伪代码，非可运行程序）：

```cpp
// 第 1 步：一次性读入全部询问，并记录原始编号
for (int i = 1; i <= m; i++) {
    read(q[i]);            // 读入第 i 个询问
    q[i].id = i;           // 记录原始编号，供最后还原输出
}
// 第 2 步：按关键字排序（左端点 / 右端点 / 时间 / 权值 / 分块）
sort(q + 1, q + m + 1, cmp);
// 第 3 步：按新顺序增量维护答案
for (int i = 1; i <= m; i++) {
    move(state, q[i]);     // 把当前状态"移动"到 q[i]（增删元素 / 合并 / 撤销）
    ans[q[i].id] = answer(state);
}
// 最后按原始编号 1..m 统一输出 ans[]
```

几个关键点：

- 每个询问都要额外记录原始编号 `id`，否则处理完后无法还原输出顺序。
- 排序规则 `cmp` 由具体算法决定：按右端点排序配合树状数组处理区间统计、按权值排序配合并查集处理连通性、按时间排序处理带时间限制的询问、按分块规则排序（莫队）。
- 第 3 步的「移动」必须支持增量维护：能新增一个元素、删除一个元素（或撤销一步修改），否则无法在相邻询问之间高效转移。

## 复杂度分析

离线操作是思想而非固定算法，复杂度取决于所选的排序规则与状态增量维护方式，故**视具体实现**。

- **时间复杂度**：一般是「排序代价 + 增量维护代价」，例如莫队为 $O(n\sqrt n)$ 级别，扫描线为 $O(n\log n)$ 级别。
- **空间复杂度**：通常只需存下全部操作（$O(m)$）以及当前状态所需的空间，**视具体实现**。

## 适用场景

- 区间查询：多个区间询问可以按右端点或左端点排序后增量处理（扫描线、莫队）。
- 带时间或权值维度的询问：按时间或权值排序后配合并查集、树状数组等维护。
- 需要大量重复预处理的题目：离线后先做一次预处理，避免对每个询问重复计算。
- 多版本、可撤销的问题：把操作组织成树，用 DFS 进入或离开节点时分别执行或撤销操作（撤销与可持久化）。

## 常见陷阱与注意事项

1. **忘记记录原始编号**：离线排序后会打乱顺序，不存 `id` 就无法按原顺序输出答案。
2. **被「强制在线」卡掉**：若每个询问的输入依赖上一次的答案，询问不确定，无法离线，此时必须换在线做法。
3. **相邻状态转移必须可撤销**：莫队删除端点、撤销合并等要求操作可逆；不可逆时不能直接套用离线框架。
4. **排序代价别忽略**：离线省了单次代价，但排序本身有 $O(m\log m)$ 开销，$m$ 很小时离线未必划算。
5. **题目未允许离线时不能擅自重排**：只有保证输出只依赖最终答案、不依赖处理过程顺序时才可离线。

## 对比与扩展

| 方法 | 思想 | 常见复杂度 | 典型用途 |
|---|---|---|---|
| 在线处理 | 逐个询问实时回答 | 视具体实现 | 强制在线、询问依赖上次答案 |
| 离线排序 | 读入全部后按关键字排序 | 排序 $O(m\log m)$ + 增量维护 | 区间统计、连通性、时间维 |
| 扫描线 | 按右端点排序，从左到右扫描 | $O(n\log n)$ | 区间或二维几何问题 |
| 莫队 | 按分块规则排序，移动区间端点 | $O(n\sqrt n)$ | 无修改的区间询问 |
| 撤销与可持久化 | 操作组织成树，DFS 进出时执行或撤销 | 视具体实现 | 多版本、可撤销修改 |

扩展方向：离线操作常与树状数组、线段树、并查集（按秩合并支持撤销）、莫队、可持久化数据结构等结合使用；理解离线思想也是学习莫队、扫描线、整体二分、CDQ 分治等进阶技巧的基础。$AKB359$, '实用工具', array['离线操作', '排序', '扫描线', '莫队', '可持久化'], 'col-hub-utility-other', null, 'knowledge'),
('Xesir', 'col-basic-offline--xesir', '离线操作 · Xesir', $AKB360$## 算法原理

在 OI 里，很多算法都用到**离线思想**。它的本质是：当「按顺序处理操作」比较难搞时，干脆把所有操作先一次性读进来，再按某种合适的顺序处理，最后按原来的编号还原、统一输出答案。

离线还有一个附带好处：方便做**预处理**，把大量重复运算合并掉，顺带就把复杂度降下来了。

举个栗子，询问序列本来是：

```text
q1,q2,q3
```

如果题目允许离线处理，我们可以先按左端点、右端点或时间等关键字排序：

```text
q2,q1,q3
```

处理结束之后，再根据每个询问**原本的编号**还原输出顺序。

跟离线相对的是**在线**，也就是对每个询问都实时处理。一般情况下，离线算法比在线实现更简单，有时复杂度也更低。

但离线不是万能的——它可以被卡。比如题目把每个询问的真实输入和上一次的答案挂钩，这时询问就不确定了，压根没法离线。~~这其实是在变相提醒你：正确解法得是在线的 awa~~

一些常见的离线算法：

- **排序后处理**：把询问按某个关键字排序，然后依次维护答案。
- **扫描线**：把二维或区间问题转成从左到右扫描。
- **莫队**：把所有区间询问按分块规则排序，靠移动当前区间的左右端点来动态维护答案。
- **撤销与可持久化**：操作都提前知道时，把不同版本组织起来，DFS 进入 / 离开节点时分别执行、撤销操作。

## 核心公式 / 状态定义与转移方程

离线本身没有统一公式，但可以把「重排后维护状态」抽象成一个通用模型。

设共有 $m$ 个询问 $q_1,\dots,q_m$，离线允许挑一个重排 $\pi$，依次处理 $q_{\pi(1)},\dots,q_{\pi(m)}$，得到 $ans_{\pi(k)}$，最后按原始编号还原成 $ans_1,\dots,ans_m$。

状态定义：处理到第 $k$ 个询问时，维护一个「当前状态」$S_k$（例如前缀 $[1,r]$ 的统计信息、当前区间 $[l,r]$ 的答案、当前并查集的连通状态等），以及指向当前询问的指针。

以莫队维护区间为例，设当前区间为 $[l,r]$、目标区间为 $[l',r']$，指针总移动量为：

$$
\lvert l-l' \rvert + \lvert r-r' \rvert
$$

排序（即选择重排 $\pi$）的目标，就是让所有询问之间指针移动的总量尽可能小，从而摊薄单次更新的代价。

## 逐行代码解析

离线是「思想」而不是某个固定算法，源笔记里也没有配套的 C++ 实现，这里用文字串一遍它的三步骨架。

### 第一步：一次性读入全部操作

不管后面怎么重排，先把所有询问读进来，并且**给每个询问记下它的原始编号**——不然排序打乱顺序后，就没人知道哪条答案该还给谁了。

### 第二步：按关键字排序 / 预处理

按题目需要挑一个关键字，把询问重排成方便维护的顺序。不同离线算法只在这个「重排规则」上有所区别：

- 按右端点排序，配合树状数组处理**区间统计**；
- 按权值排序，配合并查集处理**连通性**；
- 按时间排序，处理**带时间限制**的询问；
- 按分块规则排序，就是**莫队**。

### 第三步：依次增量维护答案，再还原输出

沿着新顺序扫一遍，让「当前状态」从上一个询问增量转移到当前询问，算出答案存回它自己的编号位置，最后按 $1 \dots m$ 统一输出。

```text
读入全部询问（并记录原始编号）
        ↓
按关键字排序 / 预处理
        ↓
依次增量维护答案
        ↓
按原始编号还原输出
```

### 撤销与可持久化

如果所有操作都提前知道，还可以把不同版本的操作组织起来，通过 DFS 进入和离开节点时分别执行、撤销操作，从而一次性处理多个版本的问题。这种玩法要求修改**可撤销**，例如：

```text
加上 x  <=>  减去 x
合并集合 <=> 撤销合并
```

## 复杂度分析

离线操作是思想而非固定算法，复杂度取决于所选的排序规则与状态增量维护方式，故**视具体实现**。

- **时间复杂度**：一般是「排序代价 + 增量维护代价」。排序本身是 $O(m \log m)$，莫队的增量维护是 $O(n\sqrt n)$ 级别，扫描线是 $O(n \log n)$ 级别。
- **空间复杂度**：通常只需存下全部操作（$O(m)$）以及当前状态所需的空间，同样**视具体实现**。

## 适用场景

- **区间查询**：多个区间询问可以按右端点或左端点排序后增量处理（扫描线、莫队）。
- **带时间 / 权值维度的询问**：按时间或权值排序后配合并查集、树状数组等维护。
- **需要大量重复预处理的题目**：离线后先做一次预处理，避免对每个询问重复计算。
- **多版本、可撤销的问题**：把操作组织成树，DFS 进出节点时执行或撤销（撤销与可持久化）。

## 常见陷阱与注意事项

1. **忘记记录原始编号**：离线排序后会打乱顺序，不存 `id` 就没法按原顺序输出答案。
2. **被「强制在线」卡掉**：若每个询问的输入依赖上一次的答案，询问不确定，无法离线，此时只能换在线做法。
3. **相邻状态转移必须可撤销**：莫队删除端点、撤销并查集合并等都要求操作可逆；不可逆时不能直接套用离线框架。
4. **排序代价别忽略**：离线省了单次代价，但排序本身有 $O(m \log m)$ 开销，$m$ 很小时离线未必划算。
5. **题目未允许离线时不能擅自重排**：只有保证输出只依赖最终答案、不依赖处理过程顺序时才可离线。

## 对比与扩展

| 方法 | 思想 | 常见复杂度 | 典型用途 |
|---|---|---|---|
| 在线处理 | 逐个询问实时回答 | 视具体实现 | 强制在线、询问依赖上次答案 |
| 离线排序 | 读入全部后按关键字排序 | 排序 $O(m\log m)$ + 增量维护 | 区间统计、连通性、时间维 |
| 扫描线 | 按右端点排序，从左到右扫描 | $O(n\log n)$ | 区间或二维几何问题 |
| 莫队 | 按分块规则排序，移动区间端点 | $O(n\sqrt n)$ | 无修改的区间询问 |
| 撤销与可持久化 | 操作组织成树，DFS 进出时执行或撤销 | 视具体实现 | 多版本、可撤销修改 |

扩展方向：离线操作常与树状数组、线段树、并查集（按秩合并支持撤销）、莫队、可持久化数据结构等结合使用；理解离线思想也是学习莫队、扫描线、整体二分、CDQ 分治等进阶技巧的基础。同主题的站内版本可对照 `basic-offline`（Fohen 版）。$AKB360$, '实用工具', array['离线操作', '排序', '扫描线', '莫队', '可撤销'], 'col-hub-utility-other', null, 'knowledge'),
('world-needs-sunday', 'col-basic-random-mt19937', 'C++ 随机数生成（mt19937 与分布对象）', $AKB361$## 算法原理

解决的问题：在 C++ 里生成**高质量、可控**的随机数，用于造数据、对拍、随机化算法（如随机化快速选择）。

核心思想：C++11 的 `<random>` 库把随机数的生成拆成**引擎**和**分布**两个正交的部分：

- **引擎**（如 `std::mt19937`）负责产生伪随机序列。它是确定性的——给定同一个种子，产生的序列完全一样。种子决定序列的起点。
- **分布**（如 `std::uniform_int_distribution`）负责把引擎输出的均匀原始值映射为目标分布（指定类型与范围）。

标准流程只有三步：**种子初始化引擎 → 定义分布对象 → 用 `分布对象(引擎)` 生成随机数**。引擎只创建一次，分布对象可反复调用。

选择 `<random>` 而不是传统 `rand()` 的原因：`rand()` 质量差、周期短，且 `rand() % n` 会因模数不整除周期而引入**取模偏差**；`<random>` 的引擎与分布都更现代、更可控。

## 核心公式 / 状态定义与转移方程

三个常用分布的定义与取值区间：

- **整数均匀分布**：$X\sim U[a,b]$，闭区间，含两端点 $a,b$

$$
P(X=x)=\frac{1}{b-a+1},\quad x\in\{a,a+1,\dots,b\}
$$

- **实数均匀分布**：$X\sim U[a,b)$，左闭右开区间

$$
f(x)=\frac{1}{b-a},\quad x\in[a,b)
$$

- **正态分布**：$X\sim N(\mu,\sigma)$，参数为均值 $\mu$ 与标准差 $\sigma$

$$
f(x)=\frac{1}{\sigma\sqrt{2\pi}}e^{-\frac{(x-\mu)^2}{2\sigma^2}}
$$

引擎侧的递推（了解即可）：`mt19937` 是梅森旋转算法，内部维护 624 个 32 位字的状态向量，每次生成按固定线性规则批量更新。种子只影响初始状态，所以「相同种子 → 相同序列」。

记忆口诀：**种子决定起点，分布决定形状，`dist(gen)` 生成最终随机数。**

## 逐行代码解析

整段程序按「头文件 → 获取种子 → 定义分布对象 → 生成随机数」四步组织，下面拆成 4 个模块逐块讲解。

### 头文件

```cpp
#include<iostream>
#include<ctime>//获取时间头文件
#include <random>//随机数头文件
using namespace std;
```

- `<ctime>` 提供 `std::time(nullptr)`，返回 Unix 时间戳（秒级）。
- `<random>` 提供引擎（`std::mt19937`）与各类分布对象。
- `using namespace std;` 用于省略 `std::` 前缀（本程序仍显式写了 `std::`，二者不冲突）。

### main 与第一步——获取种子

```cpp
int main()
{
	//第一步,获取种子
	//std::mt19937 是随机数种子，有3种常见的获取方法

	//1,固定种子,每次生成的序列相同
	std::mt19937 reg_gen(13331);

	//2,简单时间种子,精确到秒
	std::mt19937 time_gen(static_cast<unsigned int>(std::time(nullptr)));

	//3,操作系统获取熵种子,从操作系统获取熵后处理出来的种子(最常用)
	std::random_device rd;
	std::mt19937 gen(rd());
```

- 固定种子 `reg_gen(13331)`：每次运行序列完全相同，适合调试、复现 bug 数据。
- 时间种子 `time_gen(time(nullptr))`：以当前秒数作种子，缺陷是同一秒内启动的多个进程会得到相同序列。
- 熵种子 `random_device rd; gen(rd())`：从操作系统取熵，随机性最好，是最常用的写法；`rd` 只在初始化时用一次。
- 引擎只创建一次、放循环外反复用，不要在循环里反复播种。

### 第二步——定义分布对象

```cpp
	/*----------------------------------------------------------------------*/

	//第2步,定义分布对象(默认熵种子)

	//1,整形,均匀分布   范围; [0,100]
	std::uniform_int_distribution<int> number_dist(0, 100);
	
	//2,浮点型,均匀分布   范围: [0.0,1.0)
	std::uniform_real_distribution<double> float_dist(0.0, 1.0);

	//3,浮点型,正态分布   均值:10.0 , 标准差:2.0
	std::normal_distribution<double> nd_dist(10.0, 2.0);
```

- `number_dist(0, 100)`：生成 `int` 的**闭区间** `[0,100]`（含两端点）。
- `float_dist(0.0, 1.0)`：生成 `double` 的**左闭右开** `[0.0,1.0)`，右端点取不到。
- `nd_dist(10.0, 2.0)`：均值 $10.0$、标准差 $2.0$ 的正态分布 `double`；正态分布模板参数只能用浮点类型，不能写 `int`。

### 第三步——生成随机数

```cpp
	/*----------------------------------------------------------------------*/

	//第三步,生成随机数
	//格式: 分布对象(随机种子);
	
	//例子:   生成10个 整形,均匀分布   范围; [0,100] 的随机数
	for (int i = 0; i < 10; ++i) cout << number_dist(gen) << ' ';

	return 0;
}
```

- `number_dist(gen)`：把引擎 `gen` 传给分布对象，得到最终随机数；每次调用引擎内部状态前进一步。
- `for (int i = 0; i < 10; ++i)` 循环生成 10 个 `[0,100]` 的整数，用空格分隔输出。
- `return 0;` 表示程序正常结束。

## 复杂度分析

- **时间复杂度**：每生成一个随机数 $O(1)$（引擎递推是常数次位运算，分布映射是常数次缩放/查表）。
- **空间复杂度**：$O(1)$。`mt19937` 内部状态固定为 624 个 32 位字（约 2.5 KB），与生成数量无关。

## 适用场景

- **造数据 / 对拍**：按数据范围生成随机输入，配合暴力程序对拍验正确性；需要复现某个 bug 数据时换固定种子。
- **随机化算法**：需要随机 pivot、随机初始点、随机扰动打破坏数据时（如本库「快速选择」里的随机化选主元）。
- **随机打乱**：`std::shuffle(v.begin(), v.end(), gen)` 生成随机排列。
- 不适用：密码学相关需求（应使用 CSPRNG，如操作系统提供的安全随机源）、要求「真随机」的场景——`mt19937` 本质是**伪随机**，种子可被预测整个序列。

## 常见陷阱与注意事项

1. **在循环里反复播种**：每次循环都 `std::mt19937 gen(rd())` 是错误的——若循环执行得比熵源更新快，会反复拿到相同种子，产生相同序列。引擎放循环外，只创建一次。
2. **开闭区间记混**：`uniform_int_distribution` 是闭区间 `[a,b]`；`uniform_real_distribution` 是左闭右开 `[a,b)`。造数据时右端点差 1 会导致边界值缺失。
3. **正态分布不能用 `int` 模板参数**：`std::normal_distribution<int>` 不能编译。只能生成 `double`，需要整数时用 `std::lround` 四舍五入后再转。
4. **时间种子的精度只有秒**：同一秒内多次运行 `time(nullptr)` 种子相同，序列相同（对拍的重启间隔小于 1 秒时尤其明显）；要区分进程就用 `random_device` 或混合进程 ID。
5. **旧接口的取模偏差**：`rand() % n` 在 `RAND_MAX+1` 不整除 `n` 时分布不均；且 `rand()` 周期短、质量差。新代码统一用 `<random>`。
6. **需要固定小数位数**：不要生成 `double` 再硬截断。先生成整数再除 $10^k$，如 `uniform_int_distribution<int> dist(0, 99); double x = dist(gen) / 100.0;`。
7. **多线程共享引擎**：多个线程共用同一个引擎既有数据竞争问题，又会因为调度顺序不定而难以复现。每个线程应创建独立引擎（可用线程 ID 参与种子混合）。

## 对比与扩展

| 项目 | 旧式 `rand()` | 本知识点 `<random>` |
|---|---|---|
| 引擎 | 全局 `rand()`，实现定义 | 可显式选 `mt19937`、`mt19937_64` 等 |
| 种子 | `srand()`，全局生效 | 每个引擎独立持有种子 |
| 分布 | 只有均匀，靠取模变造 | 均匀/正态/伯努利/泊松等全家桶 |
| 取模偏差 | `rand()%n` 引入偏差 | 分布对象内部做无偏映射 |
| 随机打乱 | `random_shuffle`（C++17 已移除） | `std::shuffle` + 引擎对象 |

- **相关知识点**：随机化快速选择（`basic-quickselect-kth`）用随机 pivot 把最坏情况概率化，正是本库随机数的一个典型应用。
- **延伸**：`std::shuffle` 洗牌、`std::bernoulli_distribution` 伯努利分布（随机 01）、`mt19937_64` 64 位引擎、`std::seed_seq` 组合多来源种子（多个 `random_device` 值、线程 ID、时间戳混合）。$AKB361$, '实用工具', array['随机数', 'mt19937', '随机种子', '分布对象', '造数据'], 'col-hub-utility-random', null, 'knowledge'),
('world-needs-sunday', 'col-basic-random-sa-permutation', '模拟退火 · 区间退火（排列退火）', $AKB362$## 算法原理

解决的问题：**排列 / 顺序的最优化**。典型应用是洛谷 P2210「Haywire」：$n$ 头奶牛，每头恰好有 3 个好友，把它们排成一列（位置 $1\sim n$），两头好友之间的电线长度等于它们**位置差的绝对值**，求总电线长度的最小值：

$$
f(p)=\sum_{(i,j)\in E}\left|\mathrm{pos}(i)-\mathrm{pos}(j)\right|
$$

决策对象是一个 $1\sim n$ 的排列 $p$。上一篇「点退火」直接在连续坐标上挪 $(x,y)$，在这类问题里用不上；要在**排列空间**里做邻域搜索，也就是区间退火（排列退火）。

与点退火的核心区别，记三句话：

1. 点退火里，温度 $t$ 既管**扰动步长**、又管**接受劣解的概率**，两件事耦合，参数很敏感。
2. 区间退火里，扰动是**独立性的事件**——随机交换两个元素（或翻转一段），与 $t$ 完全无关。
3. 温度 $t$ 只出现在接受概率 $\exp(-\Delta E/t)$ 里，**只管「要不要接受一个更差的解」**。

于是「选哪个新状态」与「接不接受」解耦：$t$ 初值取大一点也没关系，降温系数粗一点（0.99）也能收敛，参数远不如点退火那么挑。这正是区间退火好用、好调的原因。

抽象模板：

```
初始化排列 cur（例如 恒等排列）与全局最优 best
for (t = t0; t >= t_min; t *= k):
    x, y = 随机选两个不同位置
    Δ = 交换 x、y 后的能量 - cur 的能量（增量计算）
    if Δ < 0 或 exp(-Δ/t) > random(): 真正执行交换
    若 cur 更优则更新 best
输出 best
```

## 核心公式 / 状态定义与转移方程

**状态**：排列 `cur_arr`，其中 `cur_arr[i]` 表示**奶牛 $i$ 所在的位置**（下标是奶牛、值是位置，天然是 $1\sim n$ 的排列）；当前能量 `curE`。另有全局最优 `best_arr / bestE`，退火途中接受劣解也不会丢掉已找到的最优解。

**目标函数**（P2210）：

$$
f(p)=\sum_{(i,j)\in E}\left|\mathrm{pos}(i)-\mathrm{pos}(j)\right|
$$

**扰动（转移）**：随机取两个不同下标 $x,y$，交换 `cur_arr[x]` 与 `cur_arr[y]`。两种常见扰动：

- **交换元素（swap）**：实现简单、增量计算方便、邻域粒度适中，排列退火的默认选择，本代码用的就是它。
- **区间翻转（reverse，2-opt 式）**：随机选 $[l,r]$ 整体反转，改动幅度大，适合 TSP 这类需要大范围重排的问题，但增量计算麻烦、跳变可能过大。

**增量计算（关键优化）**：交换 $a,b$ 后，只有与 $a$、$b$ 相连的边受影响。设交换前 $a$ 在位置 $pos_a$、$b$ 在位置 $pos_b$，则交换后的能量

$$
E' = E - \sum_{i\in adj(a),\,i\ne b}\Big(\left|pos_a-pos_i\right|-\left|pos_b-pos_i\right|\Big)
- \sum_{i\in adj(b),\,i\ne a}\Big(\left|pos_b-pos_i\right|-\left|pos_a-pos_i\right|\Big)
$$

$i\ne b$、$i\ne a$ 是为了跳过公共边 $a\!-\!b$：交换后 $|pos_a-pos_b|$ 不变，无需改动，也避免重复计算。单次评估复杂度从 $O(n)$ 降到 $O(\deg(a)+\deg(b))$。

**Metropolis 接受准则**：$\Delta E=E'-E$，接受概率

$$
P(\text{接受})=\begin{cases}1, & \Delta E\le 0\\[2pt] e^{-\Delta E/t}, & \Delta E>0\end{cases}
$$

**降温策略**：$t_0=20000$，每步 $t\gets t\cdot 0.99$，直到 $t<10^{-8}$；外层由 `clock()` 卡 $TL=0.9$ 秒反复整轮退火。

## 逐行代码解析

### 模块一：全局变量与 `init`（数据结构 + 初始化）

```cpp
#include<bits/stdc++.h>
using namespace std;
const double TL = 0.9;
vector<int> cur_arr, best_arr;//cur_arr[i]表示 奶牛i所在的位置
vector<vector<int>> edges;
long long curE = 0, bestE = 0;
mt19937 gen;
void init(int n)
{
	cur_arr.assign(n + 1, 0);
	best_arr.assign(n + 1, 0);
	for (int i = 1; i <= n; i++) best_arr[i] = i;
	edges.assign(n + 1, vector<int>());
	curE = 0, bestE = 0;
	gen.seed(time(nullptr));
}
```

- `cur_arr[i]` 存「奶牛 $i$ 的位置」，下标是奶牛、值是位置，天然就是一个排列；交换两个奶牛的位置就是 `swap(cur_arr[x], cur_arr[y])`。
- 初始排列取恒等排列（奶牛 $i$ 在位置 $i$）：模拟退火理论上与初值无关，随便一个合法排列即可，恒等排列最好写。
- `gen.seed(time(nullptr))` 只在 `init` 里播一次种；引擎是全局的，后续所有随机数都从它生成。

### 模块二：`cala` 增量计算交换后的能量

```cpp
long long cala(int a, int b, vector<int>& idx)
{
	long long ans = curE;
	for (int i : edges[a])
	{
		if (i != b)
		{
			ans -= abs(idx[a] - idx[i]);
			ans += abs(idx[b] - idx[i]);
		}
	}
	for (int i : edges[b])
	{
		if (i != a)
		{
			ans -= abs(idx[b] - idx[i]);
			ans += abs(idx[a] - idx[i]);
		}
	}
	return ans;
}
```

- 函数用**全局的 `curE` 作底**做增量：先减掉 $a$、$b$ 在旧位置对自己各条边的贡献，再加上换到对方位置后的新贡献，其余边不动，所以不用 $O(n)$ 全量重算。
- `if (i != b)` / `if (i != a)` 跳过公共边 $a\!-\!b$：交换前后 $|pos_a-pos_b|$ 不变，不需要也不能重复计算。
- 本题每头奶牛度数恰为 3，所以单次调用是 $O(1)$；若每次全量重算则是 $O(n)$，$n$ 大时差很多。

### 模块三：`sa` 退火主体

```cpp
void sa(int n)
{
	cur_arr = best_arr;
	curE = bestE;
	static uniform_int_distribution<int> dist(1, n);
	static uniform_real_distribution<long double> prob(0.0, 1.0);
	for (long double t = 20000; t >= 1e-8; t *= 0.99)
	{
		int x = dist(gen);
		int y = dist(gen);
		while(x == y) y = dist(gen);
		long long tmpE = cala(x, y, cur_arr);
		long long delta = tmpE - curE;
		if (delta < 0 || exp((long double)-delta / t) > prob(gen))
		{
			curE = tmpE;
			swap(cur_arr[x], cur_arr[y]);
		}
		if ((double)clock() / CLOCKS_PER_SEC > TL) break;
	}
	if (curE < bestE)
	{
		bestE = curE;
		best_arr = cur_arr;
	}
}
```

- `cur_arr = best_arr; curE = bestE;`：每轮从历史最优重新出发，不在劣解区域浪费迭代。
- `while(x == y) y = dist(gen);`：保证交换的是两个不同元素，否则这一步扰动无效。
- `if (delta < 0 || exp((long double)-delta / t) > prob(gen))`：Metropolis 准则。注意温度 $t$ **只出现在这里**，与「怎么选新状态」无关——这正是区间退火与点退火的本质区别。
- 接受才会真正 `swap(cur_arr[x], cur_arr[y])`；`curE` 同步更新为 `tmpE`，保证「能量」和「排列」始终一致。
- 每轮末尾只把**更优**的结果写进 `bestE/best_arr`，中途接受劣解不影响全局最优。

### 模块四：`main` 读入与主循环

```cpp
int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr); cout.tie(nullptr);

	int n;
	cin >> n;
	init(n);
	for (int i = 1; i <= n; i++)
	{
		for (int j = 1; j <= 3; j++)
		{
			int x;
			cin >> x;
			if (i < x) bestE += abs(i - x);
			edges[i].emplace_back(x);
		}
	}
	while ((double)clock() / CLOCKS_PER_SEC <= TL) sa(n);
	cout << bestE;

	return 0;

}
```

- 每条好友边在输入里会出现两次（好友关系是对称的），用 `if (i < x)` 保证每条边只累加一次，初始能量是恒等排列下的目标函数值。
- `while ((double)clock() / CLOCKS_PER_SEC <= TL) sa(n);`：在 `TL=0.9` 秒内反复整轮退火，多轮冗余稀释「单轮没转准」的风险。
- 最终输出 `bestE`（全局最优能量），而不是 `curE`（当前能量可能因接受劣解而变差）。

## 复杂度分析

- **时间复杂度**：单次扰动的增量评估为 $O(\deg(a)+\deg(b))$，本题度数恒为 3，即 $O(1)$；一**轮**退火的降温次数为 $\ln(T_0/T_{min})/\ln(1/0.99)\approx 2.8\times 10^3$。总轮数与总迭代由 `TL = 0.9` 秒的 `clock()` 卡点硬性封顶。
- **空间复杂度**：排列两个 `vector` 共 $O(n)$，邻接表 $O(m)$（$m$ 为边数），合计 $O(n+m)$。

## 适用场景

- **排列 / 顺序类最优化**：P2210 Haywire 这类「安排顺序、最小化与顺序相关的代价」，以及 TSP 等旅行商型问题。
- **解空间离散、无法用坐标退火**：状态是一个排列或序列，点退火的连续扰动失效时，改用「交换 / 翻转」等离散邻域。
- 注意：退火给出的是**近似最优**；对必须拿满分的精确解问题（$n$ 很大且时限紧张），优先考虑 DP 等精确算法，退火适合「够好就行」或数据有随机性的场合。

## 常见陷阱与注意事项

1. **忘了排除 `x == y`**：随机到的两个下标相同时交换无效，这一步会白白浪费迭代。务必用 `while(x == y)` 重新抽。
2. **增量计算漏掉公共边**：$a\!-\!b$ 这条边交换后长度不变，若不加 `i != a / i != b` 过滤，会把同一条边的贡献算两次，`delta` 直接算错。
3. **只输出 `curE` 不输出 `bestE`**：随机游走会接受劣解，最终停在的状态可能不是最优；`bestE/best_arr` 的独立维护和最终输出不能省。
4. **边的去重**：好友关系在输入中出现两次，`i < x` 只累加一次；漏了它 `bestE` 会变成真实值的 2 倍，输出直接错。
5. **初温与 $\Delta E$ 量级匹配**：$t_0$ 只需覆盖 $\Delta E$ 的量级（本题 20000）；$t_0$ 过小会让接受劣解概率趋近于 0，退化成爬山法卡在局部最优。
6. **排列的表示约定**：本代码是「下标 = 奶牛、值 = 位置」。若换成「下标 = 位置、值 = 奶牛」，`swap` 对象和 `cala` 里的 `abs(idx[a]-idx[i])` 都要跟着改，两种表示混用必然出错。
7. **时间卡点**：`TL=0.9` 按秒计的墙钟近似；`clock()` 在 Windows 与 Linux 的 `CLOCKS_PER_SEC` 不同，提交不同平台前先本地试跑一次确认不超时。

## 对比与扩展

| 维度 | 点退火（连续坐标） | 区间退火（排列） |
|---|---|---|
| 状态 | 坐标点，连续空间 | 排列，离散空间 |
| 扰动 | 高斯/均匀偏移，步长正比于温度 | 交换两元素或区间翻转，与温度无关 |
| 温度的作用 | 同时控制步长与接受概率，耦合 | 只控制接受概率，解耦 |
| 参数敏感度 | 高，需仔细调 | 低，初温取大点、降温粗略也能收敛 |
| 典型问题 | 费马点、平衡点（P1337） | Haywire（P2210）、TSP |

- **前置/相关**：随机引擎与分布对象见「C++ 随机数生成（mt19937 与分布对象）」；点退火细节与「为什么两者参数敏感度不同」见「模拟退火 · 点退火」。
- **扰动方式选择经验**：排列退火默认用「交换元素」；遇到回路、环等特殊结构（如 TSP 的 2-opt 邻域）再考虑区间翻转。
- **延伸**：增量计算是排列退火的常规优化（只重算受影响部分）；同一思想在「禁忌搜索 / 遗传算法」等启发式里同样适用。$AKB362$, '实用工具', array['模拟退火', '随机化', '排列退火', '增量计算', '邻域搜索'], 'col-hub-utility-random', null, 'knowledge'),
('world-needs-sunday', 'col-basic-random-sa-point', '模拟退火 · 点退火（求加权费马点）', $AKB363$## 算法原理

解决的问题：在**连续空间中求多峰函数的近似全局最优**。典型应用是洛谷 P1337「平衡点」（带权费马点 / 费马-韦伯点）：给定平面上的 $n$ 个点和权重，求

$$
f(x,y)=\sum_{i=1}^{n}w_i\cdot\sqrt{(x-x_i)^2+(y-y_i)^2}
$$

的最小值点。该函数是凸函数，但一般没有闭式解，用模拟退火求数值解非常合适。

核心思想来自金属退火的物理过程：高温时原子剧烈运动，随温度缓慢下降，能量逐渐降到最低。对应到算法上：

- **当前解**：一个状态（本代码里是坐标 $(x,y)$），伴随当前能量值（目标函数值）。
- **随机扰动**：每步在当前解附近随机跳一步，扰动幅度与当前温度 $T$ 成正比——温度越高跳得越远。
- **Metropolis 准则**：新解更优（$\Delta E<0$）就接受；更劣则以概率 $\exp(-\Delta E/T)$ 接受——这是模拟退火与「爬山法」的唯一本质区别。
- **缓慢降温**：$T\gets T\cdot k$（$k$ 略小于 1）。温度越低，扰动越小、接受劣解的概率也越小。

为什么这样设计：爬山法只接受更优解，会卡在局部最优；Metropolis 准则让算法在高温时能「翻墙」逃出局部最优去探索全局，低温时趋于稳定收敛。温降得足够慢时，算法以概率收敛到全局最优。

抽象成模板：

```
初始化当前解 cur 与全局最优 best
for (T = T0; T > T_min; T *= k):
    new = cur + 随机扰动(幅度 ~ T)
    Δ = f(new) - f(cur)
    if Δ < 0 或 exp(-Δ/T) > random(): cur = new
    若 f(cur) 更优则更新 best
输出 best
```

## 核心公式 / 状态定义与转移方程

**状态**：当前坐标 $(curx, cury)$ 与当前能量 $curE$；全局最优 $(bestx, besty)$ 与 $bestE$。每次扰动都从当前解出发，但**历史最优单独记录**——中途接受过劣解不会丢掉已经找到的最优值。

**目标函数**（本代码的带权费马点）：

$$
f(x,y)=\sum_{i=1}^{n}w_i\sqrt{(x-x_i)^2+(y-y_i)^2}
$$

**扰动（转移）**：

$$
nx = curx + U(-1,1)\cdot T,\qquad ny = cury + S\cdot T
$$

其中 $U$ 是均匀分布，$S$ 为与 $U$ 同分布的新抽样；随机数**归一化到 $[-1,1]$**，使扰动幅度恰好等于当前温度 $T$，随降温自然收缩。

**Metropolis 接受准则**：设 $\Delta E = E_{new}-E_{cur}$，接受概率

$$
P(\text{接受})=\begin{cases}1, & \Delta E\le 0\\[2pt] e^{-\Delta E/T}, & \Delta E>0\end{cases}
$$

**降温策略（多轮粗搜 → 精修）**：每轮内部 $T\gets T\cdot a$，直到 $T<10^{-8}$；每轮结束后缩小初温、放慢降温：

$$
T_0\gets T_0\cdot 0.8,\qquad a\gets 1-0.5(1-a)
$$

即初温 $10000$ 起步不断乘 $0.8$，降温系数从 $a=0.99$ 逐渐逼近 $1$（每轮余量 $1-a$ 减半）。首轮内部迭代次数约为

$$
\frac{\ln(T_0/T_{min})}{\ln(1/a)}\approx\frac{\ln(10^{12})}{0.01005}\approx 2.7\times 10^3
$$

次；后续轮的温度区间越来越小、降温越来越慢，在最优解附近越来越精细。外层 `while` 由 `clock()` 卡 `TL = 0.9` 秒，时限内尽量多跑几轮。

## 逐行代码解析

### 全局变量与目标函数 `cala`

```cpp
#include<bits/stdc++.h>
using namespace std;
mt19937 rd;
vector<long double> x, y, w;
const long double TL = 0.9;
long double curx, cury, curE, bestE, bestx, besty;
long double cala(long double mx, long double my, int n)
{
	long double res = 0;
	for (int i = 1; i <= n; i++)
	{
		long double dx = mx - x[i];
		long double dy = my - y[i];
		long double len = sqrt(dx * dx + dy * dy);

		res += len * w[i];
	}
	return res;
}
```

`cala` 计算的是「点 $(mx,my)$ 到所有洞的加权距离和」，也就是物理系统的势能。它被每一轮、每一步扰动反复调用，是**全程序的性能核心**：

- 一次调用是 $O(n)$：把 $n$ 个点各算一遍距离再按权重累加，没有任何可以省掉的项。
- 全程用 `long double`：坐标范围大、权重和可达 $10^{14}$ 量级，`double` 的有效数字在累加大量项后末位会漂出评测容差，实测 `double` 就是 WA 的直接原因之一；换上 `long double` 后 `sqrt`、`exp` 都有对应重载，精度差异自然消失。
- 距离用 `sqrt(dx*dx + dy*dy)` 手写：没有用 `hypot`，因为平方和在小数场景下更直观可控；写成 `dx*dx` 而不是 `pow(dx, 2)`，既快又避免 `pow` 的浮点误差。

### 初始化 `init`

```cpp
void init(int n)
{
	x.assign(n + 1, 0);
	y.assign(n + 1, 0);
	w.assign(n + 1, 0);
	rd.seed(static_cast<unsigned int>(std::time(nullptr)));
}
```

- 下标习惯从 $1$ 到 $n$：`x/y/w` 都 `assign(n+1, 0)` 开 $n+1$ 个位置，主循环从 $1$ 读入，与数学推导里的下标保持一致，不容易在边界上写错。
- `rd.seed(static_cast<unsigned int>(std::time(nullptr)))`：用当前秒数初始化 `mt19937`。同一个程序里引擎**只播种这一次**（`init` 只调用一次）；如果放在退火循环里反复播种，短时间内的种子完全相同，每一轮随机序列都一模一样。
- 全局变量 `curx/cury/curE/bestx/besty/bestE`：退火状态跨函数共享，`sa` 多轮调用之间靠它们传递「当前解」与「历史最优」，不用把六七个参数传来传去。

### 核心 `sa`：一轮退火

```cpp
void sa(int n, long double t, long double a)
{
	curx = bestx;
	cury = besty;
	curE = bestE;
	static uniform_real_distribution<long double> dist(-1.0, 1.0);
	static uniform_real_distribution<long double> prob(0.0, 1.0);
	for (; t > 1e-8; t *= a)
	{
		long double nx = curx + dist(rd) * t;
		long double ny = cury + dist(rd) * t;
		long double newE = cala(nx, ny, n);
		long double delta = newE - curE;
		if (delta < 0 || exp(-delta / t) > prob(rd))
		{
			curx = nx;
			cury = ny;
			curE = newE;
		}
		if (curE < bestE)
		{
			bestE = curE;
			bestx = curx;
			besty = cury;
		}
		if ((long double)clock() / CLOCKS_PER_SEC >= TL) break;

	}
}
```

- `curx = bestx; cury = besty; curE = bestE;`：**每轮都从历史最优重新出发**，而不是接着上一轮结束的位置走。这样即使上一轮末尾因为接受劣解而停在一个很差的位置，新一轮也不会在差区域的浪费迭代。
- `static uniform_real_distribution<long double> dist(-1.0, 1.0);`：分布对象声明成 `static`，整个程序只构造一次，避免每轮退火重建分布对象（重建会重置内部状态，且无谓地消耗时间）。
- `long double nx = curx + dist(rd) * t;`：扰动。`dist` 已经**归一化到 $[-1,1]$**，所以步长幅度恰好等于当前温度 $t$——温度高时大步跳跃、探索全局；温度降低后步长自动收缩、精细微调。这正是「扰动幅度 $\sim T$」的标准写法。
- `if (delta < 0 || exp(-delta / t) > prob(rd))`：**Metropolis 准则**，整个模拟退火的灵魂。`delta = newE - curE` 是新旧能量差：更优（`delta<0`）无条件接受；更劣时，接受概率是 $e^{-\Delta E/T}$，温度 $t$ 越高、劣解越容易被接受。`prob(rd)` 是 $[0,1)$ 的均匀随机数，用「概率大于随机数」的办法掷出这一步是否接受。
- `if (curE < bestE) { ... }`：**独立维护历史最优**。随机游走会接受劣解，`curE` 可能短暂变差，但不影响 `bestE` 一直记录全场最优——最终输出用的就是 `bestx/besty`，而不是当前解。
- `if ((long double)clock() / CLOCKS_PER_SEC >= TL) break;`：时钟超限立即跳出本轮的降温循环。没有这行，降温链会老老实实跑满 $T_{min}$ 才停；有了它，时间预算由主循环统一管理。

### 主函数 `main`：起点、多轮策略与输出

```cpp
int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr); cout.tie(nullptr);

	int n;
	cin >> n;
	init(n);
	long double mx = 0, my = 0, mw = 0;
	for (int i = 1; i <= n; i++)
	{
		cin >> x[i] >> y[i] >> w[i];
		mx += x[i] * w[i];
		my += y[i] * w[i];
		mw += w[i];
	}
	mx /= mw;
	my /= mw;

	curx = mx, cury = my, curE = cala(mx, my, n);
	bestE = curE, bestx = mx, besty = my;

	long double t = 10000, a = 0.99;
	while ((long double)clock() / CLOCKS_PER_SEC < TL)
	{
		sa(n, t, a);
		t *= 0.8;
		a = 1 - 0.5 * (1 - a);
	}

	cout << fixed << setprecision(3) << bestx << ' ' << besty;

}
```

- **起点取加权质心**：先累加 $\sum x_i w_i$、$\sum y_i w_i$、$\sum w_i$ 再相除，得到

$$
\left(\frac{\sum x_i w_i}{\sum w_i},\ \frac{\sum y_i w_i}{\sum w_i}\right)
$$

它比算术平均更贴近最优解，$n=1$ 时甚至就是精确解。起点好，退火「热机」阶段可以省掉大量浪费的搜索。

- **多轮粗搜 → 精修**：`t *= 0.8; a = 1 - 0.5 * (1 - a);`。第一轮 `t=10000`、`a=0.99`，降温快、覆盖广，先粗略定位最优区域；之后每轮初温变成原来的 $0.8$ 倍，降温系数 $a$ 的余量 $1-a$ 每轮减半、越发趋近 $1$，降温变慢、精度提高。层层递进：**范围逐轮缩小，精度逐轮提升**。这套调度是本代码能做到稳定 100% AC 的关键，而不是靠某一轮「运气好」。
- `while ((long double)clock() / CLOCKS_PER_SEC < TL)`：时间卡点。`TL=0.9` 秒预算内能跑几轮跑几轮，每轮都在缩范围、提精度；多轮冗余也把「单轮没转准」的概率稀释掉了。
- `cout << fixed << setprecision(3) << bestx << ' ' << besty;`：固定 3 位小数输出最小值点。题目要求 3 位精度，而 `long double` + $10^{-8}$ 的终止温度已经远高于这个要求，末位不会漂。

## 复杂度分析

- **时间复杂度**：单轮内部降温次数为 $\ln(T_0/T_{min})/\ln(1/a)$，首轮（$T_0=10000$、$a=0.99$、$T_{min}=10^{-8}$）约 $2.7\times 10^3$ 次；后续轮 $1-a$ 每轮减半，降温链越来越长，但初温也在乘 $0.8$ 收缩，两者此消彼长。每次扰动的评估 `cala` 是 $O(n)$。总轮数与总迭代由 `TL = 0.9` 秒的 `clock()` 卡点硬性封顶，实际运行远低于时限（零点几秒即可 AC）。
- **空间复杂度**：只存坐标与权重的三个 `vector`，$O(n)$。

## 适用场景

- **连续空间的多峰最优化**：带权费马点 / 平衡点（P1337）、覆盖圆、旅行商这类没有多项式精确解的近似最优化问题。
- **需要「够好就行」的数值解**：答案只要求若干位小数、允许误差的题（如几何平衡、连续函数求极值），模拟退火以极低实现成本换取稳定分数。
- **非精确解不可的场景不适用**：要求输出精确整数解、或解空间离散且约束强的题，退火可能永远踩不到可行解；这类题优先考虑 DP / 精确算法。
- 参数完全相同的两次运行结果可能不同（随机算法本质），对「必须复现」的评测要谨慎。

## 常见陷阱与注意事项

1. **`double` 精度不够会 WA**：本题把坐标、权重、能量全部换成 `long double` 是稳定 AC 的直接原因之一。`sqrt`、`exp` 对 `long double` 有对应重载；若回退到 `double`，末位精度可能差出评测容差。
2. **扰动幅度必须归一化**：`dist(-1.0, 1.0)` 乘 $t$ 才能让「步长幅度 = 温度」；若用 `dist(-32767, 32767)` 这类大区间且不除范围，高温期步长会远超坐标范围，大量迭代浪费在坐标域之外。
3. **只用当前解、丢掉历史最优**：随机游走会接受劣解，若最后输出「当前解」而不输出 `best`，可能丢掉了中途找到的最优值。务必单独维护 `bestE/bestx/besty`。
4. **单轮收敛不可靠，多轮粗精结合才稳**：单靠一轮快降温容易停在局部最优附近；本代码「第一轮粗搜 + 后续轮缩小初温（$\times 0.8$）并放慢降温（$a\to 1$）」逐步逼近，比固定一套参数的单调降温更稳。
5. **种子取秒级时间且只播一次**：同一个程序内 `time(nullptr)` 播一次没问题；但两个进程若在同一秒启动会得到相同序列，对拍多开进程时要注意（可混入进程 ID）。
6. **退化情形**：$n=1$ 时答案就是那一个点，算法应自然收敛于此（无需特判，但要知道会退化）；多个最优解（如两个等质量点）时答案不唯一，评测按误差判分，无需纠结。
7. **计时函数**：`clock()` 计量 CPU 时间，Windows 与 Linux 的 `CLOCKS_PER_SEC` 不同，阈值 `TL=0.9` 是按秒计的墙钟近似；`TL` 别贴满评测时限，留余量给输入输出。

## 对比与扩展

| 方法 | 接受劣解 | 局部最优 | 适用 |
|---|---|---|---|
| 爬山法 | 从不 | 容易卡住 | 凸函数、单峰 |
| 模拟退火 | 按 $e^{-\Delta E/T}$ 概率 | 慢降温下可逃离 | 多峰、需要近似全局最优 |
| 随机重启爬山 | 从不，但多次随机起点 | 靠重启覆盖 | 解空间小、重启成本低 |

- **前置/相关**：随机数引擎 `mt19937` 与分布对象见「C++ 随机数生成（mt19937 与分布对象）」（`basic-random-mt19937`），本代码的 `rd`、`dist`、`prob` 都是它的直接应用。
- **参数经验**：本代码采用「多轮粗搜 → 精修」策略——首轮 $T_0=10000$、$a=0.99$ 快速粗搜，之后每轮 $T_0\gets T_0\times0.8$、$a\gets 1-0.5(1-a)$ 缩小搜索范围并放慢降温，配合 $0.9$ 秒时间卡点，实际零点几秒即可稳定 AC。相比「单一慢降温系数（如 $0.9992$）跑一轮」，多轮缩放对精度和鲁棒性都更友好；其中的 $0.8$、$0.5$ 属于经验参数，可按题目的坐标范围与精度要求微调。
- **延伸**：遗传算法、粒子群、禁忌搜索同属随机优化；退火思想还可用于离散问题（如旅行商的 2-opt 邻域 + Metropolis）。$AKB363$, '实用工具', array['模拟退火', '随机化', '爬山法', 'Metropolis准则', '费马点'], 'col-hub-utility-random', null, 'knowledge'),
('world-needs-sunday', 'col-basic-space-test', '空间测试', $AKB364$## 算法原理

空间测试是在本地估算或测量程序占用了多少内存，用来判断会不会 MLE（Memory Limit Exceeded）。它和时间测试是一对：时间测试回答“跑得够不够快”，空间测试回答“占得够不够小”。

竞赛程序的内存通常来自四块：

- **静态/全局区**：全局数组、全局 `vector` 的元信息等，编译后大小基本固定。
- **栈区**：局部变量、递归调用帧；深递归是常见的 MLE 来源。
- **堆区**：`new`、`malloc`、`vector`/`string`/`map` 等容器动态申请的内存。
- **运行时开销**：程序本身、标准库、OJ 的评测进程等，通常有几 MB 到几十 MB。

常用手段分两类：

1. **估算**：按“元素个数 × 单元素大小”逐项相加，适合赛前设计数据范围。
2. **实测**：用 `sizeof`、容器 `capacity()`、`getrusage()` 或读取 `/proc/self/status` 得到实际占用。

估算能提前发现“数组开不下”，实测能发现“容器扩容、递归栈、运行时开销”这些容易漏掉的部分。

## 核心公式 / 状态定义与转移方程

**数组/静态内存**：

$$
\text{bytes} = n \times \texttt{sizeof}(T)
$$

**`vector`**：

$$
\text{bytes} \approx \texttt{capacity}() \times \texttt{sizeof}(T)
$$

注意是 `capacity()` 而不是 `size()`：扩容后容量可能远大于实际元素个数。

**邻接表**：

$$
\text{bytes} \approx n \times \texttt{sizeof(vector)} + 2m \times \texttt{sizeof(edge)}
$$

**递归栈**：

$$
\text{bytes} \approx \text{递归深度} \times \text{每层栈帧大小}
$$

**实测 RSS**：Linux 下 `getrusage(RUSAGE_SELF, &ru)` 的 `ru_maxrss` 表示峰值常驻内存，单位通常是 KB；macOS 上单位是字节，需要按平台区分。

## 逐行代码解析

本篇不附完整程序，只给关键测量片段；完整的时间测试写法见 [时间测试](#basic-timing)。

### 静态类型大小

```cpp
sizeof(int);
sizeof(long long);
sizeof(vector<int>);
```

- `sizeof` 是编译期运算符，返回类型或对象的字节数。
- `sizeof(vector<int>)` 只是一个空 vector 对象的大小，不包含它将来申请的元素内存。
- 对指针使用 `sizeof` 得到的是指针大小，不是它指向的数组大小。

### 容器容量

```cpp
vector<int> v;
v.capacity();
v.size();
```

- `capacity()` 是当前已分配的元素槽位数，`size()` 是实际元素个数。
- 估算 `vector` 内存时用 `capacity() * sizeof(int)`，不要用 `size()`。
- `string`、`deque`、`map` 等容器的实际占用还与实现细节有关，粗略估算时按容量与节点开销相加。

### 进程峰值内存

```cpp
#include <sys/resource.h>
rusage ru;
getrusage(RUSAGE_SELF, &ru);
ru.ru_maxrss;
```

- `ru_maxrss` 是进程运行到当前的峰值常驻内存。
- Linux 下通常以 KB 为单位，macOS 下以字节为单位；跨平台使用时要先确认单位。
- 这是“进程级”数据，包含运行时与标准库开销，不只是你的数组。

### 读取 `/proc/self/status`

```text
VmRSS:  当前常驻内存
VmHWM:  峰值常驻内存
```

- Linux 下可以直接读取 `/proc/self/status`，解析 `VmRSS` 与 `VmHWM`。
- 单位通常是 KB；不同内核版本可能有差异。
- 这种方法只适用于 Linux 本地测试，不能依赖它在 OJ 上运行。

## 复杂度分析

- **估算**：遍历数据结构的定义逐项相加，通常是 $O(1)$ 或 $O(n)$（需要遍历容器容量时）。
- **实测**：`sizeof` 是编译期 $O(1)$；`getrusage` 是系统调用，近似 $O(1)$。
- **空间测试本身**：不改变被测试程序的渐进空间复杂度；它只是观测手段。

## 适用场景

- 赛前按数据范围估算数组、邻接表、DP 表、线段树是否开得下。
- 本地复现 MLE，判断是静态数组、容器扩容还是递归栈导致。
- 对比不同实现的内存占用，例如 `vector` 与手写数组、`map` 与离散化+数组。
- 不适合：OJ 不提供系统调用或 `/proc` 时，只能靠估算；不要依赖实测代码提交。

## 常见陷阱与注意事项

- **只看 `sizeof`**：`sizeof(vector)` 不包含堆上的元素内存。
- **用 `size()` 代替 `capacity()`**：扩容后的容量可能远大于元素个数。
- **忽略递归栈**：深递归可能比全局数组更早触发 MLE。
- **忽略运行时开销**：OJ 的进程本身、标准库和评测环境会占几 MB 到几十 MB。
- **单位混淆**：`ru_maxrss` 在 Linux 是 KB、macOS 是字节；`/proc/self/status` 通常是 KB。
- **虚拟内存不等于常驻内存**：`VSZ` 可能很大，但实际占用看 `RSS`。
- **页对齐与分配器开销**：小块内存分配有额外元数据，估算值通常偏小。
- **32/64 位差异**：指针、`size_t`、结构体对齐都会改变大小。

## 对比与扩展

- **与时间测试**：时间测试用 `clock()` 测 CPU 时间；空间测试用 `sizeof`/`getrusage`/`/proc` 测内存。两者都不改变算法复杂度，只用于验证。
- **与离散化**：离散化把值域从 $O(V)$ 压到 $O(n)$，是最常用的“降空间”手段之一。
- **与 bitset**：bitset 用 $O(n/8)$ 字节表示布尔数组，比 `bool` 数组省 8 倍空间，同时把运算压到 $O(n/64)$。
- **与内存分析工具**：本地可以用 Valgrind、AddressSanitizer 或 IDE 的内存分析器；竞赛中更常用估算与 `getrusage`。

相关条目：[时间测试](#basic-timing)$AKB364$, '实用工具', array['空间测试', '内存', 'sizeof', '调试'], 'col-hub-utility-debug', null, 'knowledge'),
('lker', 'col-basic-stress-basic--lker', '对拍（四件套与执行流程） · lker', $AKB365$## 算法原理

对拍是 OI 赛制中常用的一种验证自己程序是否正确的工具，尤其是在样例强度不足的情况下。对拍可以帮助我们找到绝大多数边界条件，并辅助程序调试。

一份对拍程序通常包括下面四个部分：

- 一份我们自己编写的代码 `mine.cpp`；
- 一份我们保证正确的暴力程序 `bf.cpp` 作为参考，和我们编写的正解使用同一份数据进行测试，以判断正解是否正确工作。因此，这里的暴力程序不需要保证复杂度，但一定要保证正确；
- 一份随机数据生成器 `data.cpp`，用来生成大量数据，满足对拍的需要（因为赛事下发的大样例可能比较弱）；
- 一份代码 `control.cpp`，用来自动执行这些代码，并比较它们的输出文件是否一致。

除了 `control.cpp` 之外的另外三个 `.cpp` 文件都采用文件读写。我们先把四个代码文件全部编译一遍，再运行 `control.cpp`。`control.cpp` 会先执行 `data.cpp`，生成一份输入文件 `data.out`；再自动执行 `bf.cpp` 和 `mine.cpp`，生成 `bf.out` 和 `mine.out` 两份输出，并比较它们是否一致。

如果一致，我们就继续对拍；如果不一致，程序会自动退出。此时，我们直接查看 `data.out` 这份输入，看看是哪里写挂了即可。

这里我们主要介绍一下 `control.cpp` 会用到的命令：

```cpp
system(" ")
```

它可以执行引号中的命令。我们会用到下面几种形式：

```cpp
system("./name") 
```

运行一个叫作 `name` 的可执行文件。

```cpp
system("cmp -s bf.out mine.out")
```

在 NOI Linux 环境下，对比 `bf.out` 和 `mine.out` 文件是否一致。一致时返回 `0`，不一致时返回 `1`。

如果在 Windows 环境下，我们会使用 `fc` 命令进行对比：

```cpp
system("fc bf.out mine.out")
```

在 Windows 环境下运行某个文件时，可以使用下面的形式：

```cpp
system("name")
```

直接填入可执行文件的文件名即可。

~~不过考试正式环境下根本不会用到这句吧。~~

### 四件套的执行顺序

1. `data` 写出 `data.out`；
2. `bf` 读 `data.out`，写 `bf.out`；
3. `mine` 读 `data.out`，写 `mine.out`；
4. `control` 比较两份输出：一致就继续下一轮，不一致就停下。

这里以 [P3396 哈希冲突](https://www.luogu.com.cn/problem/P3396) 为例，给出四份代码。

## 逐行代码解析

下面把 `control.cpp` 拆成三块讲，三块按顺序拼起来就是完整程序。

### 头文件与主循环骨架

```cpp
#include<bits/stdc++.h>
using namespace std;
int main()
{
    int ti=0;
    while(1){
        system("./data");
        system("./bf");
        system("./mine");
```

- `ti` 记已经跑过的数据组数，同时也用来控制什么时候收工。
- `while(1)` 是死循环——对拍本来就要一直跑到出错为止，退出条件写在循环体内部。
- 三行 `system` 严格按「造数据 → 跑暴力 → 跑正解」的顺序执行；顺序不能反，否则 `mine` 会读到上一轮的 `data.out`。

### 比较与退出

```cpp
        if(system("cmp -s bf.out mine.out"))
        {
            cout<<"WA/RE/MLE on test "<<++ti<<"\n";
            break;
        }
        else cout<<"AC on test"<<++ti<<"\n";
        if(ti==10)//这里的ti是数据组数,你希望拍多少组由你决定
            break;
    }
    return 0;
}
```

- `system("cmp -s ...")` 返回的是命令的**退出码**：文件一致时为 `0`，不一致时为非 `0`。所以写进 `if` 里，「非 0 即出错」正好对应 `if` 为真的分支。
- 出错时先 `++ti` 再打印，编号从 1 开始；随后 `break` 跳出死循环。
- 出错就 `break` 还有一个隐藏好处：`data.out` 不会再被下一轮覆盖，我们可以直接打开它，用这组数据复现问题。
- `ti==10` 是人为设定的轮数上限，想拍多少组改这个数即可。

### 另外三份文件

`mine.cpp`（这里是一份分块预处理的正解）：

```cpp
#include<bits/stdc++.h>
using namespace std;
const int N=2e5+5;
const int M=505;
int f[M][M];
int a[N];
int main()
{
    freopen("data.out","r",stdin);
    freopen("mine.out","w",stdout);
    int n,m;
    cin>>n>>m;
    for(int i=1;i<=n;i++)
        cin>>a[i];
    int lim=(int)sqrt(n);
    for(int i=1;i<=n;i++)
        for(int j=1;j<=lim;j++)
            f[i%j][j]+=a[i];
    while(m--)
    {
        char cmd;
        cin>>cmd;
        int x,y;
        cin>>x>>y;
        if(cmd=='A')
        {
            if(x<=lim) cout<<f[y][x]<<"\n";
            else{
                int sum=0;
                for(int i=y;i<=n;i+=x)
                    sum+=a[i];
                cout<<sum<<"\n";
            }
        }else{
            for(int j=1;j<=lim;j++)
                f[x%j][j]+=(y-a[x]);
            a[x]=y;
        }
    }
    return 0;
}
```

`bf.cpp`（保证正确、不保证复杂度的暴力）：

```cpp
#include<bits/stdc++.h>
using namespace std;
const int N=2e5+5;
int a[N];
int main()
{
    freopen("data.out","r",stdin);
    freopen("bf.out","w",stdout);
    int n,m;
    cin>>n>>m;
    for(int i=1;i<=n;i++)
        cin>>a[i];
    while(m--)
    {
        char cmd;int x,y;
        cin>>cmd>>x>>y;
        if(cmd=='A')
        {
            int sum=0;
            for(int i=1;i<=n;i++)
                if(i%x==y) sum+=a[i];
            cout<<sum<<"\n";
        }
        else a[x]=y;
    }
    return 0;
}
```

`data.cpp`（随机数据生成器，生成方法见「随机数据生成」几条）：

```cpp
#include<bits/stdc++.h>
#include<unistd.h>
using namespace std;
int main()
{
    freopen("data.out","w",stdout);
    mt19937 rd(getpid());
    int n=rd()%(150000)+1;
    int m=rd()%(150000)+1;
    cout<<n<<" "<<m<<"\n";
    for(int i=1;i<=n;i++)
        cout<<rd()%(1000)+1<<" ";
    cout<<"\n";
    for(int i=1;i<=m;i++)
    {
        char opt=rd()%2?'A':'C';
        if(n==1) opt='C';
        cout<<opt<<" ";
        if(opt=='A')
        {
            int x=rd()%(n-1)+1;//p上界是开区间
            int y=rd()%x;//y下届取0(闭),上界取x(开)
            cout<<x<<" "<<y;
        }
        else{
            int x=rd()%(n)+1;
            int y=rd()%(1000)+1;
            cout<<x<<" "<<y;
        }
        cout<<"\n";
    }
    return 0;
}
```

- 四份程序里只有 `control.cpp` 用标准输入输出，其余三份都用 `freopen` 把读写重定向到文件——这是四个进程互相传递数据的唯一通道。
- `data.cpp` 的 `data.out` 是**输入**文件名，`bf`/`mine` 的 `bf.out`、`mine.out` 是**输出**文件名，三者别写混。

## 复杂度分析

对拍本身没有固定复杂度，开销由「跑了多少组 × 每组三份程序的运行时间」决定，其中暴力程序通常是瓶颈。所以对拍时要把暴力写简单、把数据规模压小，宁可多拍几组小的，也不要一组大到跑不完。

## 适用场景

- 样例太弱、手搓边界又想不到的时候，用对拍批量试探。
- 正解跑得对但心里没底：写一份朴素暴力做参照，让机器替你验证。
- 赛前自测：把常错题型（区间、取模、多测、图论边界）都挂上对拍。
- 不适合：题目本身有 SPJ / 交互 / 多解（见「精度误差与 SPJ 对拍」「交互题对拍」两条），以及暴力都无法在可接受时间内跑完的题。

## 常见陷阱

- **Windows 与 Linux 的命令不一样**：Linux 下是 `system("./data")`、`cmp -s`，Windows 下要写 `system("data")`、`system("fc bf.out mine.out")`。交题环境是 NOI Linux，本地是 Windows 的话两边要分开写。
- **`cmp` 的返回值**：一致返回 `0`，非 0 才是出错。写成 `if(!system(...))` 就正好反了。
- **忘记 `freopen` 或文件名写错**：四个进程会读到空文件，于是「永远 AC」，对拍完全失效。
- **暴力程序本身写错**：暴力和正解一起错，对拍永远发现不了。暴力要尽量直白，宁可慢。
- **数据范围造错**：比如本题的 `p` 上界是开区间、`y` 的取值是 `[0,x)`，`data.cpp` 里若造出越界数据，两边都可能 UB，比出来的结果没有意义。
- **出错后不要继续跑**：一旦 `break` 才保住出错的 `data.out`；如果循环不退出，现场就被下一轮覆盖了。
- `#include<unistd.h>` 与 `getpid()` 是 Linux 专有；在 Windows 下编译会直接报错，需要换种子。

## 对比与扩展

- 四件套的另一种组织方式是用 shell 脚本 / `bat` 脚本串起来，省掉写 `control.cpp` 的功夫，本质和本文一样。
- 如果想对拍「多测 + 大数据」，可以给 `data.cpp` 加一个从命令行读规模参数的功能，先拍小数据找错，再放大数据卡常。
- 对拍只能告诉你「这组数据答案不一样」，不能告诉你「谁错了」。定位仍然要靠单步调试或把 `data.out` 手动喂给两份程序。$AKB365$, '实用工具', array['对拍', 'stress test', '随机数据', '暴力程序', '调试'], 'col-hub-utility-debug', null, 'knowledge'),
('lker', 'col-basic-stress-checker--lker', '对拍（SPJ 与构造题 checker） · lker', $AKB366$## 算法原理

有 SPJ 的题目在对拍时不能使用 `system` 语句直接比较，而需要手动编写一个 checker。对于只要求输出满足某些约束的情况，我们不再需要 `bf.cpp` 文件，只需要对输出进行一次合法性检查即可。

对于构造类型的题目，检验分两层：

- **合法性检验**：判断输出是否满足题目对输出方案的约束；
- **最优性检验**：判断得到的方案是否为最优解。最优性可以通过深搜完成，也可以通过理论分析得到答案的上界。

~~不过题目是不是一般会给你一个写好的 checker 来着。~~

以 [P8468 文文的构造游戏](https://www.luogu.com.cn/problem/P8468) 为例。核心思路是：如果程序判断存在方案，就按照题意检查一遍它给出的构造；如果程序判断不存在方案（输出 `-1`），就用深搜枚举，确认是不是真的不存在。

需要注意的是，深搜可能会超时，所以 `data.cpp` 不要生成过大的数据。

### 检验流程

1. 跑 `data` 生成数据，跑 `mine` 得到输出；
2. 先把 `data.out` 读回来，记下每个询问的 $(s,m)$；
3. 再把 `mine.out` 读回来，逐组核对；
4. 输出 `-1` 的组用 `ex(s,m)` 深搜验证确实无解；输出方案 `a` 的组用 `ck(s,m,n,a)` 验证「个数在范围内、每个数不超过 $s$、和为 $s$、异或和为 $0$」。

## 逐行代码解析

### 深搜判定：到底存不存在合法方案

```cpp
#include<bits/stdc++.h>
using namespace std;
#define int long long
bool dfs(int s,int d,int n,int sm,int xr)
{
    if(d==n)return sm==s&&xr==0;
    for(int x=1;x<=s;x++)
        if(dfs(s,d+1,n,sm+x,xr^x))
            return true;
    return false;
}
bool ex(int s,int m)
{
    for(int n=1;n<=m;n++)
        if(dfs(s,0,n,0,0))
            return true;
    return false;
}
```

- `dfs(s,d,n,sm,xr)` 表示「已经选了 $d$ 个数、当前和为 `sm`、异或和为 `xr`，还要再选到 $n$ 个」，返回是否能补完。
- 递归出口 `d==n` 时同时检查**和等于 $s$** 与**异或和为 $0$**，这正是题目要求的两个条件。
- `for(int x=1;x<=s;x++)` 枚举下一个数的取值：每个数必须在 $[1,s]$ 内，否则不合法。
- `ex(s,m)` 枚举可能的个数 $n\in[1,m]$，任意一个能构造出来就说明存在方案。

### 合法性检验：检查程序给出的构造

```cpp
bool ck(int s,int m,int n,vector<int>&a)
{
    if(n<1||n>m)return false;
    int sm=0,xr=0;
    for(int x:a){
        if(x<1||x>s)return false;
        sm+=x;
        xr^=x;
    }
    return sm==s&&xr==0;
}
```

- 先卡个数 $n\in[1,m]$，再逐个卡每个数 $x\in[1,s]$，越界直接判错。
- 边累加边异或，最后统一比较，等价于前面深搜的两个终止条件。
- 注意这里只验**合法性**，不验最优性——本题是构造题，只要方案合法即可。

### 主循环：读回两份文件并逐组核对

```cpp
signed main()
{
    int ti=0;
    while(1){
        system("./data");
        system("./mine");
        freopen("data.out","r",stdin);
        int T;cin>>T;
        vector<pair<int,int>> qs(T);
        for(int i=0;i<T;i++)cin>>qs[i].first>>qs[i].second;
        cin.clear();
        freopen("mine.out","r",stdin);
        bool ok=true;
        for(int i=0;i<T;i++){
            int s=qs[i].first,m=qs[i].second;
            int n;cin>>n;cin.clear();
            if(n==-1){
                if(ex(s,m)){ok=false;break;}
            }else{
                vector<int>a(n);
                for(int j=0;j<n;j++)cin>>a[j],cin.clear();
                if(!ck(s,m,n,a)){ok=false;break;}
            }
        }
        if(!ok){cout<<"WA/RE/MLE on test "<<++ti<<"\n";break;}
        cout<<"AC on test "<<++ti<<"\n";
        if(ti==10)break;
    }
    return 0;
}
```

- 这里**只需要 `data` 和 `mine`**：SPJ 题的正确性由 checker 自己判定，不需要 `bf.cpp`。
- 先读 `data.out` 存下所有询问，再读 `mine.out` 对照——顺序不能反，读完一边要 `cin.clear()` 才能切到另一边。
- 输出 `-1` 时调 `ex(s,m)`：如果深搜发现其实存在方案，说明程序答错了；否则这组算过。
- 输出方案时调 `ck`：任何一个数越界、和不对、异或和不为 0 都判错。
- `signed main` 配合前面的 `#define int long long`，避免深搜里的和溢出。
- 出错即 `break`，保住当轮的 `data.out` 与 `mine.out` 供复现。

## 复杂度分析

checker 本身的开销取决于检验方式：`ck` 是 $O(n)$；`ex` 的深搜最坏要枚举 $s^n$ 种方案，是指数级的，所以 `data.cpp` 必须把 $s$ 和 $m$ 压小，否则还没等 checker 判完就先超时了。

## 适用场景

- 输出任意合法方案的构造题、多解题。
- 带 SPJ 的题目（题目给 checker 时直接用，不给时自己写一份）。
- 需要验证「输出格式本身是否合规」的场景，例如个数、取值范围、是否重复。

## 常见陷阱

- **深搜爆炸**：`ex` 是指数级，数据造大了必然 TLE，表现为「控制器一直不结束」。要把 `data.cpp` 的规模限制在深搜能跑完的量级。
- **只验合法、忘了验最优**：如果题目要求最优解，`ck` 里必须再比较一次答案大小，或者用理论上界判断；否则「输出一个合法但很差的方案」也会被判 AC。
- **`cin.clear()` 漏写**：切换 `freopen` 后读入失败，后面的判定全建立在垃圾值上。
- **`-1` 的语义没对齐**：要确认题目规定的「无解输出」到底是 `-1` 还是 `No solution`，写错会把正确答案判成 WA。
- **多测题忘记清空**：`ok`、临时 `vector` 每轮都要重新初始化，不能跨组复用。

## 对比与扩展

- 与「浮点误差对拍」的区别：那边比数值接近程度，这边比方案是否合法。
- 如果题目附带官方 checker，优先用官方的；自己重写容易漏掉题面里的隐藏约束。
- 构造题还可以反过来用：写一个随机构造程序，让 checker 帮你筛掉不合法的生成策略。$AKB366$, '实用工具', array['对拍', 'SPJ', 'checker', '构造题', '合法性检验'], 'col-hub-utility-debug', null, 'knowledge'),
('lker', 'col-basic-stress-graph-gen--lker', '随机数据生成（一般图） · lker', $AKB367$## 算法原理

一般图的随机生成，核心套路只有一句：**先生成一棵树保证连通，再随机补边到 $m$ 条**。

树的部分和「树与特殊结构」那条完全一样——枚举 $i\in[2,n]$，让 $i$ 连向 $[1,i-1]$。这样图一定连通、边数一定至少是 $n-1$。

补边时要按题目要求逐条加上限制：

| 要求 | 处理方式 |
|---|---|
| 不许自环 | 判 `u==v` 就重抽 |
| 不许重边 | 用 `set<pair<int,int>>` 记已存在的边 |
| 无向边方向 | 统一存成 `{min(u,v),max(u,v)}` |
| 有向边方向 | 直接存 `{u,v}`，不排序 |
| 无环（DAG） | 只允许从小编号连向大编号 |
| 二分图 | 先给树染色，之后只在异色点之间连边 |
| 平面图 | 直接造网格图作为代表 |

## 逐行代码解析

### 连通无向图

先生成一棵树，再在树上随机添加边，以保证图一定连通：

```cpp
for(int i=2;i<=n;i++) 
    cout<<(rd()%(i-1)+1)<<" "<<i<<"\n";
for(int i=n;i<=m;i++)
    cout<<(rd()%n+1)<<" "<<(rd()%n+1)<<"\n";
```

- 第一段是树，用掉 $n-1$ 条边；第二段从第 $n$ 条补到第 $m$ 条，共补 $m-n+1$ 条。
- 补的边**可能是自环、也可能是重边**，多数题不允许，需要换成下面带 `set` 的写法。
- 若 $m$ 小于 $n-1$，这个循环根本不会执行，输出退化成树——要和题目的 $m$ 下界对齐。

### 有向图

```cpp
for(int i=2;i<=n;i++)
{
    int p=1+rnd()%(i-1);
    cout<<p<<" "<<i<<"\n";
}
for(int i=n;i<m;i++)
{
    int u=1+rd()%n;
    int v=1+rd()%n;
    cout<<u<<" "<<v<<"\n";
}
```

- 树的边方向统一为「小 $\to$ 大」，天然无环；补边时方向随机，可能造出环。
- 这里第二段的上界写的是 `i<m`，比无向图那版少跑一次，抄的时候按实际需要的边数调整。
- 注意变量名 `rnd` 与 `rd` 混用了，实际使用时统一成一个。

### 不允许自环和重边的无向图

使用 `set` 判断边是否已经存在即可：

```cpp
for(int i=2;i<=n;i++) 
    cout<<(rd()%(i-1)+1)<<" "<<i<<"\n";
set<pair<int,int>> e;
while(e.size()<m)
{
    int u=1+rd()%n;
    int v=1+rd()%n;
    if(u==v||e.count({min(u,v),max(u,v)})) continue;
    e.insert({min(u,v),max(u,v)});
    cout<<min(u,v)<<" "<<max(u,v)<<"\n";
}
```

- 关键是把边统一存成 `{min,max}`：无向图里 $(u,v)$ 和 $(v,u)$ 是同一条边，不排序就会漏判重。
- `e.size()` 只统计补出来的边，树上那 $n-1$ 条没有放进 `set`，所以循环条件写 `e.size()<m` 时要自己补上偏移。
- 如果 $m$ 接近完全图（$\frac{n(n-1)}{2}$），随机重抽会越来越慢，接近饱和时要改成枚举剩余点对。

### 不允许自环和重边的有向图

基本方法与无向图类似，但需要注意边的方向：

```cpp
set<pair<int,int>> e;
for(int i=2;i<=n;i++)
{
    int p=1+rnd()%(i-1);
    e.insert({p,i});
    cout<<p<<" "<<i<<"\n";
}
while(e.size()<m)
{
    int u=1+rd()%n;
    int v=1+rd()%n;
    if(u==v||e.count({u,v})) continue;
    e.insert({u,v});
    cout<<u<<" "<<v<<"\n";
}
```

- 有向边不排序：$(u,v)$ 与 $(v,u)$ 是两条不同的边，都算合法。
- 这里把树边也放进了 `set`，所以 `while(e.size()<m)` 的语义是对的——总共 $m$ 条边。
- 同上，边数接近 $n(n-1)$ 时重抽会变慢。

### 完全图

```cpp
for(int i=1;i<=n;i++)
    for(int j=i+1;j<=n;j++)
        cout<<i<<" "<<j<<"\n";
```

- 双重循环只取 $j>i$，正好枚举所有无序点对，不重不漏。
- 完全图的边数是 $O(n^2)$，$n$ 稍大输出就会爆掉，注意题目上界。

### DAG

先生成一棵树以保证图连通，再规定只能从编号较小的点指向编号较大的点，从而保证图中无环：

```cpp
set<pair<int,int>> e;
for(int i=2;i<=n;i++)
{
    int p=1+rd()%(i-1);
    e.insert({p,i});
    cout<<p<<" "<<i<<"\n";
}
while(e.size()<m)
{
    int u=1+rd()%(n-1);
    int v=u+1+rd()%(n-u);
    if(e.count({u,v})) continue;
    e.insert({u,v});
    cout<<u<<" "<<v<<"\n";
}
```

- `u` 取 $[1,n-1]$，`v` 取 $[u+1,n]$，所以每条边都从小指向大。既然编号严格递增，就**不可能有环**。
- `rd()%(n-u)` 的取值范围是 $[0,n-u-1]$，加上 $u+1$ 后正好落到 $[u+1,n]$。
- 这个技巧叫做「按拓扑序编号」，比随机删边判环简单得多。

### 二分图

先生成一棵树，并根据树上的连接关系为节点染色，保证相邻节点颜色不同；然后在不同颜色的节点之间随机添加边：

```cpp
for(int i=2;i<=n;i++)
{
    int p=1+rd()%(i-1);
    c[i]=1-c[p];
    e.insert({min(p,i),max(p,i)});
    cout<<p<<" "<<i<<"\n";
}
while(e.size()<m)
{
    int u=1+rd()%n;
    int v=1+rd()%n;
    if(u==v||c[u]==c[v]) continue;
    int a=min(u,v),b=max(u,v);
    if(e.count({a,b})) continue;
    e.insert({a,b});
    cout<<a<<" "<<b<<"\n";
}
```

- 建树时顺便染色：`c[i]=1-c[p]`，保证树边一定连接异色点。
- 补边时 `if(u==v||c[u]==c[v]) continue;` 直接跳过同色点对，于是所有边都在异色之间，图必然是二分图。
- 这个写法同时保证了「连通」「无自环」「无重边」「二分」，是二分图题的万能数据。

### 平面图

这里以生成网格图为例：

```cpp
for(int i=1;i<a;i++)
    for(int j=1;j<=b;j++)
        cout<<id(i,j)<<" "<<id(i,j+1)<<"\n";
for(int i=1;i<=a;i++)
    for(int j=1;j<=b;j++)
        cout<<id(i,j)<<" "<<id(i+1,j)<<"\n";
```

- `id(i,j)` 把二维坐标压成一维编号，通常是 `(i-1)*b+j`。
- 第一段连横向边、第二段连纵向边，画出来就是一张 $a\times b$ 的网格，是平面图最典型的代表。
- 注意两段的边界：横向只该连到 $b-1$，纵向只该连到 $a-1$，否则会连出格子外的点。

## 复杂度分析

建树是 $O(n)$；补边时若用 `set` 判重，每条边是 $O(\log m)$，总计 $O(m\log m)$；完全图和网格图则是按点数直接 $O(n^2)$ 或 $O(ab)$ 输出。空间上 `set` 需要 $O(m)$。

## 适用场景

- 最短路、最小生成树、连通性、拓扑排序、二分图匹配等图论题的随机数据。
- 想卡「重边 / 自环」处理时，专门造带重边、带自环的数据（把上面的判重去掉即可）。
- 想卡「不连通」时，去掉建树那一段，只在随机点对之间连边。

## 常见陷阱

- **$m$ 与 $n-1$ 的关系**：补边循环的起点写成 `i=n` 还是 `i=m`，直接决定总边数对不对。先想清楚「树边已占多少条」再写。
- **无向图忘记 `min/max`**：不排序就会把 $(u,v)$ 和 $(v,u)$ 当成两条边，输出重边。
- **`set` 里没放树边**：`e.size()<m` 的语义就错了，实际边数会偏多。
- **$m$ 接近完全图时重抽变慢**：随机重抽在边快满时会大量空转，$n$ 稍大就可能卡死，需要改成枚举。
- **DAG 的编号规则被破坏**：一旦允许「大编号指向小编号」，环就出现了，拓扑排序题会直接判错。
- **二分图忘了染色**：只靠随机连边是不可能保证二分性的，必须显式染色。
- **平面图边界越界**：横向/纵向循环的上界差一，就会连出不存在的点。

## 对比与扩展

- 与「树与特殊结构」的关系：那一条是这一条的子过程，把建树部分单独抽出来就是树生成器。
- 想造「稀疏随机图」，可以让 $m$ 取 $2n\sim5n$；想造「稠密图」，让 $m$ 取 $n^2/10$ 量级。
- 卡 Tarjan / 网络流时，基环树、菊花、网格、完全图各来一组，比纯随机有效得多。$AKB367$, '实用工具', array['对拍', '随机数据', '无向图', '有向图', 'DAG', '二分图'], 'col-hub-utility-debug', null, 'knowledge'),
('lker', 'col-basic-stress-interactive--lker', '对拍（交互题） · lker', $AKB368$## 算法原理

许多交互题虽然有 grader，但是不会自动生成数据。对于交互题，对拍思路是：

1. 按照一般交互题的方式，将 `grader.cpp` 和 `mine.cpp` 一起编译，生成一个可执行文件；注意，`grader.cpp` 中需要添加 `freopen`（或直接打开文件流），这样才能读取随机数据；
2. 再运行这个可执行文件和随机数据生成器；
3. 最后读取输出并编写 checker。

如果下发的 grader 已经包括自动判题的功能，那么我们可以从题目中复制一份下来，然后做简单修改（**不要直接在原来的 grader 中魔改**）。你可以使用原来的 grader 进行判题，也可以自己另外编写一个 checker，并将它和这个 grader 链接在一起。

下面以 [P15652 排列游戏](https://www.luogu.com.cn/problem/P15652) 为例。

首先一定要先执行下面的命令：

```cpp
g++ perm.cpp grader.cpp -o perm -std=c++14
```

将二者一起编译。因为现在的 grader 已经给出了判题功能，所以我们稍微修改一下就可以了。同样地，按照题目要求，我们在文件夹中放置一个 `perm.h` 文件。

这里的主要逻辑是：grader 调用 `data`，然后读取 `data.out` 中的数据，再调用 `perm` 函数（实际执行 `perm.cpp`），最后检查 `perm` 返回的结果。

### 三个文件各管什么

- `perm.h`：声明交互接口，`perm.cpp` 与 `grader.cpp` 都包含它；
- `perm.cpp`：只实现题目要求的 `init` 和 `perm`，通过 `query` 询问；
- `grader.cpp`：负责造数据（调 `data`）、读数据、提供 `query` 的实现、并在最后校验答案。

## 逐行代码解析

下面把 `grader.cpp` 拆成三块，三块按顺序拼起来就是完整程序。

### 接口与询问实现

```cpp
#include <bits/stdc++.h>
#include "perm.h"
using namespace std;

namespace grader {
    int n;
    vector<int> p;

    int ask(const vector<int> &a) {
        vector<int> vis(n);
        for (int x : a) {
            if (x < 0 || x >= n) return -1;
            vis[x] = 1;
        }
        for (int i = 0; i < n; i++)
            if (!vis[i]) return i;
        return n;
    }

    int query(int l, int r) {
        if (l < 0 || l > r || r >= n) return -1;
        return ask(vector<int>(p.begin() + l, p.begin() + r + 1));
    }
}

int query(int l, int r) {
    return grader::query(l, r);
}
```

- `grader::n`、`grader::p` 保存当前这组数据，`check()` 每验一组就重新赋值。
- `ask(a)` 求「集合 `a` 里没有出现的最小非负整数」：先标记出现过哪些数，再从 0 往上找第一个没被标记的；全部出现则返回 `n`。下标越界直接返回 `-1`，这是一种防御式写法。
- `query(l,r)` 先做区间合法性检查，再把 `p[l..r]` 交给 `ask`——这就是题面里选手能调用的询问。
- 最外层再包一个 `query`，把 `grader` 命名空间里的实现暴露给 `perm.cpp`，对应 `perm.h` 中的函数声明。

### 校验：先看是不是排列，再看所有询问是否一致

```cpp
bool check(const vector<int> &p) {
    int n = p.size();
    grader::n = n, grader::p = p;
    vector<int> q = perm(n), vis(n);
    if ((int)q.size() != n) return false;

    for (int x : q) {
        if (x < 0 || x >= n || vis[x]) return false;
        vis[x] = 1;
    }
    for (int l = 0; l < n; l++)
        for (int r = l + 1; r < n; r++) {
            vector<int> a(p.begin() + l, p.begin() + r + 1);
            vector<int> b(q.begin() + l, q.begin() + r + 1);
            if (grader::ask(a) != grader::ask(b)) return false;
        }
    return true;
}
```

- 先把本组数据塞进 `grader`，再调用选手的 `perm(n)` 拿答案。
- 第一层校验：长度必须是 $n$，且每个数在 $[0,n)$ 内、互不重复——也就是必须是一个排列。
- 第二层校验：对所有 $l<r$，原排列和答案排列在同一段区间上的 `mex` 必须相同。这正是题目「询问结果完全一致」的定义。
- 这里是 $O(n^3)$ 的暴力比较（$O(n^2)$ 个区间 × $O(n)$ 求 mex），只适合对拍用的小数据。

### 主程序：反复造数据、逐组判题

```cpp
int main(int argc, char **argv) {
    int rounds = argc > 1 ? atoi(argv[1]) : 10000;
    bool ok = rounds > 0;

    for (int T = 1; T <= rounds && ok; T++) {
        if (system("./data > data.out")) {
            ok = false;
            break;
        }

        ifstream fin("data.out");
        int c, t;
        if (!(fin >> c >> t)) {
            ok = false;
            break;
        }
        init(c, t);

        while (t-- && ok) {
            int n;
            if (!(fin >> n) || n < 2) {
                ok = false;
                break;
            }

            vector<int> p(n), vis(n);
            for (int &x : p) fin >> x;
            if (!fin) {
                ok = false;
                break;
            }

            for (int x : p) {
                if (x < 0 || x >= n || vis[x]) {
                    ok = false;
                    break;
                }
                vis[x] = 1;
            }
            if (ok) ok = check(p);
        }
    }

    cout << (ok ? "Passed\n" : "Failed\n");
    return !ok;
}
```

- `rounds` 从命令行参数读，默认 10000 轮；`main` 的返回值用 `!ok`，这样失败时进程退出码非 0，方便脚本判断。
- `system("./data > data.out")` 直接让生成器把数据写进 `data.out`，省掉在 `data.cpp` 里写 `freopen`。返回值非 0 说明生成器本身崩了。
- 读进来的 `c`、`t` 交给选手的 `init(c,t)`，对应题面的初始化参数。
- 每组数据先校验读入的 `p` 本身是不是合法排列——**数据生成器也要被验**，否则生成器出错会把选手的正确程序误判成 WA。
- 全部通过打印 `Passed`，否则 `Failed`；没有做「第几组挂了」的定位，需要定位可以自己加计数输出。

### 选手侧与数据生成器

`perm.h` 只放接口声明：

```cpp
#ifndef PERM_H
#define PERM_H

#include <vector>

void init(int c, int t);
std::vector<int> perm(int n);
int query(int l, int r);

#endif
```

`perm.cpp` 只实现 `init` 和 `perm`，通过 `query` 询问：

```cpp
void init(int c, int t) {}

vector<int> perm(int n) {
    vector<int> pre(n), suf(n);
    int pos = n - 1;
    for (int i = 0; i < n - 1; i++) {
        pre[i] = query(i + 1, n - 1);
        if (!pre[i]) {
            pos = i;
            for (int j = n - 1; j > i; j--) suf[j] = query(0, j - 1);
            break;
        }
    }

    vector<int> ans(n, -1), vis(n);
    ans[0] = pre[0], ans[n - 1] = suf[n - 1];
    vis[ans[0]] = vis[ans[n - 1]] = 1;
    for (int i = 1; i < n - 1; i++) {
        if (pre[i] != pre[i - 1]) ans[i] = pre[i], vis[ans[i]] = 1;
        if (suf[i] != suf[i + 1]) ans[i] = suf[i], vis[ans[i]] = 1;
    }

    for (int l = 0, r = n - 1, i = n - 1;; i--) {
        while (i >= 0 && vis[i]) i--;
        if (i < 0) break;
        while (l < pos && ans[l] != -1) l++;
        while (r > pos && ans[r] != -1) r--;
        if (pre[l] > suf[r]) ans[l] = i;
        else ans[r] = i;
        vis[i] = 1;
    }
    return ans;
}
```

`data.cpp` 负责生成若干组排列：

```cpp
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
    int c = 0, t = 20;
    cout << c << ' ' << t << '\n';

    for (int T = 1; T <= t; T++) {
        int n = T <= 3 ? T + 1 : rng() % 79 + 2;
        vector<int> p(n);
        iota(p.begin(), p.end(), 0);
        if (T == 2) reverse(p.begin(), p.end());
        else shuffle(p.begin(), p.end(), rng);

        cout << n << '\n';
        for (int i = 0; i < n; i++)
            cout << p[i] << " \n"[i == n - 1];
    }
```

- `perm.h` 的头文件保护不能省，`perm.cpp` 与 `grader.cpp` 都会包含它。
- `data.cpp` 把 $c$、$t$ 写在第一行，后面依次是每组数据，和 `grader` 的读取顺序严格对应。
- 前 3 组固定用很小的 $n$（并且第 2 组是逆序），先把边界情况覆盖掉，再随机放大。

## 复杂度分析

对拍的总开销是「轮数 × 每组数据规模下 grader 的判题时间」。这里的 `check` 是 $O(n^3)$，所以 `data.cpp` 把 $n$ 限制在 80 以内。真正交题的 grader 通常有更高效的判题方式，不要照搬这里的暴力校验。

## 适用场景

- 交互题本地验证：题目只给 grader、不给数据生成器时，自己补一个 `data.cpp` 和驱动逻辑。
- 需要「多次询问、询问结果必须一致」这类一致性校验的题。
- 想批量测试选手函数在不同数据下的表现，而不只是跑官方几个样例。

## 常见陷阱

- **编译顺序**：必须 `g++ perm.cpp grader.cpp -o perm` 一起编译，单独编 `perm.cpp` 会缺 `query` 的实现，链接失败。
- **直接修改原 grader**：题目下发的 grader 是判题基准，改了就没法保证和官方一致。一定复制一份再改。
- **数据生成器不合法**：`grader` 里那段「检查 `p` 是不是排列」就是防这个的；自己的生成器一定要满足题面约束。
- **交互次数超限**：真实题目对 `query` 的次数有上限，本地对拍时也要顺手统计一下，别只验答案对不对。
- **`data.cpp` 与 `data.out` 的通道**：本例用 `system("./data > data.out")` 重定向，若改成 `freopen`，`grader` 里的读取方式要同步改。
- **Windows 环境**：`system("./data")` 在 Windows 下要写成 `system("data")`。

## 对比与扩展

- 与「SPJ 与构造题对拍」的区别：交互题的 checker 必须和 grader 链接在一起，因为它要复用 `query` 的实现去模拟交互过程。
- 若题目自带完整的自动判题 grader，最省事的做法是只补 `data.cpp` + 外层循环，不重写 checker。
- 想定位是第几组挂的，可以在 `check` 失败时打印当前 $T$ 和 $n$，比只打印 `Failed` 有用得多。$AKB368$, '实用工具', array['对拍', '交互题', 'grader', 'checker', '随机数据'], 'col-hub-utility-debug', null, 'knowledge'),
('lker', 'col-basic-stress-precision--lker', '对拍（浮点误差与精度比较） · lker', $AKB369$## 算法原理

`system` 语句是逐字比较。在面对允许精度误差或者带有 SPJ 的题目时，我们不能再让 `cmp` / `fc` 去比文件，而要在 `control.cpp` 里自己把两个答案读进来，按误差阈值判断。

关键是从两份输出里分别读入数据：先 `freopen` 重定向到 `bf.out`，读入并记录答案；再重定向到 `mine.out`，读入并记录答案，最后比较。

但是，重定向后 `cin` 中可能会残留一些状态，因此每次读入后都要清空，防止出现错误读取：

```cpp
cin.clear()
```

这里以 [P1429 平面最近点对（加强版）](https://www.luogu.com.cn/problem/P1429) 为例。答案是实数，输出允许一定误差，所以把控制器的比较从「文件逐字相等」换成「差值不超过 `eps`」。

### 控制器怎么改成数值比较

1. 前三条 `system` 和普通对拍完全一样，照旧造数据、跑暴力、跑正解；
2. 用 `freopen("bf.out","r",stdin)` 把标准输入指向暴力输出，`cin>>bf` 读回答案，读完后 `cin.clear()`；
3. 再把标准输入指向 `mine.out`，同样读回 `mn` 并 `cin.clear()`；
4. 判断 `fabs(mn-bf)>eps`：超差就当出错，否则继续。

## 逐行代码解析

### 阈值与主循环

```cpp
#include<bits/stdc++.h>
using namespace std;
#define eps 1e-3
int main()
{
    int ti=0;
    while(1){
        system("./data");
        system("./bf");
        system("./mine");
```

- `eps` 是「我们能接受的精度阈值」，本例取 $1\times10^{-3}$。题目若要求保留 4 位小数，通常取 `1e-3` ~ `1e-6` 都合理；取得太小会把浮点误差当错误，取得太大又会放过真错。
- 前三条 `system` 与普通对拍一致，顺序仍是「造数据 → 暴力 → 正解」。

### 从两份输出里读答案

```cpp
        double bf,mn;
        freopen("bf.out","r",stdin);
        cin>>bf;
        cin.clear();
        freopen("mine.out","r",stdin);
        cin>>mn;
        cin.clear();
```

- `freopen` 可以反复调用，把 `stdin` 重新指向另一个文件，这样就不用开 `ifstream`，直接 `cin` 即可。
- 第一次读完后如果不清状态，`cin` 可能还带着读到文件尾的 `eofbit` / `failbit`，第二次读就会直接失败、`mn` 保持初值。所以 `cin.clear()` 是**必需**的，不是可选项。
- 两份答案分别存在 `bf`、`mn` 里，变量名故意和文件名呼应，读代码时不容易串。

### 比较与退出

```cpp
        if(fabs(mn-bf)>eps)
        {
            cout<<"WA/RE/MLE on test "<<++ti<<"\n";
            break;
        }
        else cout<<"AC on test"<<++ti<<"\n";
        if(ti==10)
            break;
    }
    return 0;
}
```

- 用 `fabs(mn-bf)>eps` 而不是 `mn!=bf`：浮点数几乎不可能逐位相等，直接比会 100% 误报。
- 出错即 `break`，保住这一轮的 `data.out`；`ti==10` 是轮数上限，按需修改。
- 如果答案有多个数（比如输出 $k$ 个实数），就循环读 $k$ 次、逐个比，或者把整行读成字符串再自己解析。

### 配套的暴力与数据

`bf.cpp` 的核心就是把所有点对两两枚举（保证正确，不保证复杂度）：

```cpp
    db mn=(db)1e20;
    for(int i=1;i<=n;i++)
        for(int j=1;j<=n;j++)
            if(i!=j&&sgn(dis(i,j)-mn)<0)
                mn=dis(i,j);
    mn=sqrt(mn);
    printf("%.4lf",mn);
```

`data.cpp` 生成 $n$ 个坐标在 $[0,10^9]$ 内的点：

```cpp
    mt19937 rd(getpid());
    int n=rd()%(200000-1)+2;
    cout<<n<<"\n";
    for(int i=1;i<=n;i++)
    {
        int x=rd()%(N+1);
        int y=rd()%(N+1);
        cout<<x<<" "<<y<<"\n";
    }
```

- 暴力和正解都用 `freopen` 固定读写 `data.out` / `bf.out` / `mine.out`，与控制器约定一致。
- `sgn` 判号是为了避免浮点误差导致的「差一点点却判成更小」，两边的 `sgn` 写法要一致。

## 复杂度分析

对拍开销由「组数 × 每组三份程序的运行时间」决定。本例暴力是 $O(n^2)$，所以 `data.cpp` 把 $n$ 控制在 $2\times10^5$ 以内仍然偏大——真正跑对拍时可以把上界调小到几千，换取更多组数。

## 适用场景

- 答案是实数、题目允许相对/绝对误差的题（几何、概率、数值计算）。
- 多解题只要求输出任意一组合法方案的题（此时不能比数值，要写 checker，见「SPJ 与构造题对拍」）。
- 输出带行末空格、换行差异导致 `cmp` 误报的题。

## 常见陷阱

- **忘记 `cin.clear()`**：第二次读入直接失败，`mn` 保持未初始化值，于是「每次都 WA」或「每次都 AC」，对拍完全失真。
- **`eps` 取错**：取 $10^{-8}$ 时浮点误差会频繁误报；取 $10^{-1}$ 时真错误会被放过。一般取「题目要求精度」的 1~10 倍。
- **相对误差题写成绝对误差**：答案本身很大时（如 $10^9$ 量级），绝对误差阈值几乎必然误报，应按题目要求写成 $\dfrac{|a-b|}{\max(1,|b|)}$ 形式的相对误差。
- **两份程序输出格式不同**：一个输出 `1.2345`、另一个输出 `1.234500`，用 `cin` 读成 `double` 后再比才不会误伤。
- **`freopen` 后还在用 `cout`**：控制器自己的输出会被写进被重定向的文件里，注意别把调试输出混进 `bf.out`。

## 对比与扩展

- 普通整数题直接用 `cmp` / `fc` 比文件更省事，只有在「答案不唯一 / 允许误差」时才需要把比较搬进 `control.cpp`。
- 如果输出是一整张矩阵，可以逐元素读入比较，并在出错时把第一处不同的下标打印出来，定位会快很多。
- 与「SPJ 与构造题对拍」的区别：那里比的是**方案合法性**，这里比的是**数值接近程度**。$AKB369$, '实用工具', array['对拍', '浮点误差', 'eps', 'cin.clear', 'SPJ'], 'col-hub-utility-debug', null, 'knowledge'),
('lker', 'col-basic-stress-random-basic--lker', '随机数据生成（种子与基础套路） · lker', $AKB370$## 算法原理

随机数据的生成方法有很多，这里介绍一种比较好记、也是我平时经常使用的写法。

常用的随机数种子是 `rand()`，但是它在一秒内生成的种子通常是一样的，导致一秒内运行的程序生成的随机数也可能一致。不过，绝大多数情况下暴力程序在一秒内运行不了几次，所以直接使用 `rand()` 也可以，但还是不太建议这样做。

而 `getpid()` 这个种子和系统进程有关，也就是说，每次调用时使用的种子都不一样。使用 `getpid()` 需要包含 `unistd.h` 头文件。随机数生成器使用 `mt19937`，随机数质量较高：

```cpp
mt19937 rd(getpid());
```

这样每次调用 `rd()` 就可以获得一个随机数。如果需要生成负数，进行适当的偏移即可。

如果要在区间 $[a,b]$ 内生成一个随机数，只需要使用：

```cpp
rd()%(b-a+1)+a
```

取模是为了将随机数映射到一个长度为 $b-a+1$ 的区间内，再统一加上偏移量 $a$，使其移动到合法区间。

如果要生成 $[a,b]$ 内的 $k$ 位小数，只需要先生成一个 $[a\times10^k,\,b\times10^k]$ 内的整数，再除以 $10^k$ 即可。

### 三种最常用的基础形态

| 形态 | 写法要点 |
|---|---|
| 序列 | 先定长度 $n$，再循环 $n$ 次生成每个元素 |
| 区间操作 | 随机两个端点后交换，保证左右顺序 |
| 0/1 数 | 对 $2$ 取模，按奇偶判断 |

## 逐行代码解析

下面把上面几种形态的写法逐个拆开看。

### 序列

先生成序列长度，再循环 $n$ 次生成 $n$ 个数字：

```cpp
int n=rd()%(y-x+1)+x;
for(int i=1;i<=n;i++)
    a[i]=rd()%(b-a+1)+a;
```

- 长度的范围是 $[x,y]$，元素的范围是 $[a,b]$——两组变量名别混用。
- 如果题目要求「值域很大但 $n$ 很小」，可以让元素取到 $10^9$，专门用来卡离散化、卡溢出。

### 区间操作

先随机生成两个数字，再将它们的大小交换。与先固定生成一个端点相比，这样可以使询问分布更加均匀：

```cpp
int l=rd()%(n-1+1)+1;
int r=rd()%(n-1+1)+1;
if(l>r) swap(l,r);
```

- 两个端点都独立随机，再 `swap` 归一化，比「先定 $l$、再在 $[l,n]$ 里取 $r$」分布更均匀。
- 写成 `rd()%(n-1+1)+1` 就是把上下界直接代入公式，不容易算错。

### 0/1 数

对 $2$ 取模，并根据奇偶性判断：

```cpp
int a=rd()%2?1:0;
```

- 这种写法适合生成「选或不选」的决策序列、黑白染色、布尔矩阵。
- 如果 0 和 1 的比例需要控制，可以改成 `rd()%10<3` 这种阈值写法。

### 字符串

生成一个随机数字，并将其映射到 $[0,25]$，再转化为小写字母：

```cpp
for(int i=1;i<=n;i++)
    cout<<abs(rd()%26)+'a';
```

- `rd()%26` 落在 $[0,25]$，加上 `'a'` 就得到 `a`～`z`。
- 想只从几个字符里选（比如括号序列题只允许 `(`、`)`、`*`），就改成在字符表里按随机下标取。
- 想造「大量相同字符」的极端数据，就让取值集中到少数几个字母上。

### $k$ 位小数

先放大成整数，再除回去：

```cpp
int v=rd()%(b*pow10-a*pow10+1)+a*pow10;
printf("%.3f\n", v/1000.0);
```

- 先生成 $[a\times10^k, b\times10^k]$ 的整数，再除以 $10^k$，这样小数位是「精确」的 $k$ 位。
- 直接 `rd()%b + (double)rd()/RAND_MAX` 容易踩到精度坑，不如整数化。

## 复杂度分析

生成 $n$ 个数据是 $O(n)$，空间取决于是否先存下来——边算边输出可以做到 $O(1)$。`mt19937` 单次调用是常数时间，不会成为瓶颈。

## 适用场景

- 写 `data.cpp` 时的通用底座：先有「随机整数 / 随机区间 / 随机 0-1」这三件，再往上拼具体结构。
- 需要「每次运行种子都不同」的对拍场景。
- 生成小数、坐标、权值等数值型数据。

## 常见陷阱

- **`getpid()` 是 Linux 专有**：Windows 下要 `#include <windows.h>` 用 `GetCurrentProcessId()`，或者退回 `chrono::steady_clock::now().time_since_epoch().count()`。交题环境是 NOI Linux，本地对拍要注意区分。
- **`rd()%n` 的取模偏差**：`mt19937` 的值域是 $[0,2^{32})$，对不是 $2$ 的幂的 $n$ 取模会有极微小的偏差。对拍场景完全无所谓，但写正式随机化算法时要知道这一点。
- **区间写反**：`rd()%(b-a+1)+a` 里若 $b<a$，`b-a+1` 可能为负，结果是未定义行为。
- **忘记加偏移**：只写 `rd()%(b-a+1)` 得到的是 $[0,b-a]$，不是 $[a,b]$。
- **元素范围与题目约束不一致**：比如题目保证 $a_i\ge1$，生成器却造出 $0$，两边程序都可能 UB，拍出来的结果没有意义。
- **一次生成太多**：数据量超过被测程序的处理能力时会 TLE，看起来像「死循环」，其实是数据造太大。

## 对比与扩展

- 与「树 / 图的随机生成」配合：先用这里的整数与区间套路定好参数，再套具体结构的生成模板。
- 想要更强的随机性可以用 `mt19937_64`；想要可复现的随机，就固定一个常量种子。
- 对拍时建议把「小数据 + 边界数据 + 大数据」分开生成，边界往往比随机更能打出错。$AKB370$, '实用工具', array['对拍', '随机数据', 'mt19937', 'getpid', '数据生成器'], 'col-hub-utility-debug', null, 'knowledge'),
('lker', 'col-basic-stress-tree-gen--lker', '随机数据生成（树与特殊结构） · lker', $AKB371$## 算法原理

树是随机数据里最常被考的结构，而「随机树」有个非常好用的事实：**枚举 $i\in[2,n]$，让 $i$ 随机连向 $[1,i-1]$ 中的某个点，得到的必然是一棵以 $1$ 为根的树**。

原因有三条：

- $i=2$ 时只能连 $1$，所以图一定连通；
- 每个点只向编号更小的点连边，所以不会产生环；
- 每次恰好加一条边，边数正好是 $n-1$。

由此还能顺手改出几个变体：

| 结构 | 怎么改 |
|---|---|
| 链 | 把「随机连 $[1,i-1]$」改成「只连 $i-1$」 |
| 菊花图 | 把所有点都连到 $1$ |
| 基环树 | 先单独造一个环，再往环上挂树 |
| 森林 | 把 $n$ 个点切成若干段，每段内部按树的方式连 |
| 二叉树 | 随机选父亲，但限制每个点最多两个孩子 |

## 逐行代码解析

### 随机树

给出 $u,v$，表示 $u,v$ 之间有一条边。枚举 $i\in[2,n]$，让每个 $i$ 随机连接到 $[1,i-1]$ 中的一个点：

```cpp
int n=rd()%(MAXN-1+1)+1;
cout<<n<<"\n";
for(int i=2;i<=n;i++)
    cout<<rd()%(i-1-1+1)+1<<" "<<i<<"\n";
```

- `rd()%(i-1-1+1)+1` 化简就是 `rd()%(i-1)+1`，取值范围 $[1,i-1]$；照着公式写不容易错。
- 这样生成的树「偏向于小编号当父亲」，深度通常不大。想造深链、造卡递归的数据，得用下面的「链」或加权策略。
- 如果题目以 $1$ 为根，这里生成的天然就是以 $1$ 为根的有根树，不用再找根。

### 基环树

生成一个环长为 $k$、总点数为 $n$ 的基环树：先建立环，再在环上挂树。

```cpp
for(int i=1;i<k;i++) cout<<i<<" "<<i+1<<"\n";
cout<<k<<" "<<1<<"\n";
for(int i=k+1;i<=n;i++)
    cout<<rd()%(i-1-1+1)+1<<" "<<i<<"\n";
```

- 前两行把 $1\to2\to\cdots\to k\to1$ 连成一个长度 $k$ 的环，正好用掉 $k$ 条边。
- 后面把 $k+1\dots n$ 依次挂到 $[1,i-1]$ 上，因为挂的点编号都大于 $k$，所以不会影响环本身。
- 总边数是 $k+(n-k)=n$，符合基环树「$n$ 点 $n$ 边」的定义。
- 注意 $k$ 至少为 $3$（$k=2$ 会变成两条重边），造数据时要单独卡一下。

### 菊花图

将所有点连接到根节点上：

```cpp
for(int i=2;i<=n;i++)
    cout<<1<<" "<<i<<"\n";
```

- 专门用来卡「单次递归深度大」「从根出发的遍历很慢」这类实现。
- 与链配合使用：链卡深度，菊花卡度数。

### 链

依次连接相邻节点即可：

```cpp
for(int i=2;i<=n;i++)
    cout<<i-1<<" "<<i<<"\n";
```

- 链是最容易把递归 DFS 爆栈的结构，也是深度相关算法（LCA、树剖）的极端数据。
- 想造「长链 + 少量分叉」，可以在链上随机挑几个点再挂叶子。

### 森林

生成多棵树即可：

```cpp
int sum=0;
while(k)
{
    int n=rd()%(k-1+1)+1;
    for(int i=sum+2;i<=sum+n;i++)
    cout<<sum+1+rd()%(i-sum-2+1)<<" "<<i<<"\n"; 
    k-=n;
    sum+=n;
}
```

- `sum` 是已经造过的点数，相当于把全局编号切成若干段，每段内部独立成树。
- 内层 `sum+1+rd()%(i-sum-2+1)` 的含义是「连到本段内编号更小的点」，和随机树的原理完全一样。
- `while(k)` 里 `n` 有可能取到 $0$，如果 $n=0$ 就会死循环，实际使用时建议写成 `rd()%(k)+1`。

### 二叉树

让每个节点随机连接到一个父节点，并限制每个节点的孩子数不超过 $2$：

```cpp
int cnt[N];
for(int i=2;i<=n;i++)
{
    int p;
    do{
        p=1+rd()%(i-1-1+1);
    }while(cnt[p]>=2)
    cnt[p]++;
    cout<<p<<" "<<i<<"\n";
}
```

- `cnt[p]` 记父亲 $p$ 当前已有的孩子数，`do...while` 反复重抽，直到抽到一个还没满两个孩子的父亲。
- 这种「重抽」写法的期望次数很小（树里空位足够多），但最坏情况会退化成一直重抽，数据规模别开太大。
- 注意 `while(cnt[p]>=2)` 后面少了一个分号，实际编译会报错，抄的时候记得补上。

## 复杂度分析

每种结构都是一次 $O(n)$ 的循环，空间上除了二叉树要开一个 `cnt` 数组（$O(n)$）之外都是 $O(1)$。

## 适用场景

- 树形 DP、LCA、树链剖分、树上差分等题的随机数据。
- 想专门卡「递归深度」时用链；想卡「度数」时用菊花图；想卡「环上处理」时用基环树。
- 二叉树模板题（如线段树、堆）可以用二叉树生成器配合验证。

## 常见陷阱

- **随机树深度太小**：默认生成法长出来的树接近「随机递归树」，深度约为 $O(\log n)$，几乎卡不到递归栈。要卡深度必须显式造链。
- **基环树 $k$ 取太小**：$k=2$ 时 $(1,2)$ 与 $(2,1)$ 是两条重边，不是合法的简单环。
- **森林里出现空树**：`n` 取到 $0$ 会死循环，也会破坏「$n$ 个点」的约定。
- **二叉树重抽死锁**：如果 $n$ 很小而限制又很紧（比如每个点最多 1 个孩子），`do...while` 可能永远抽不到，需要兜底。
- **题目要求无标号 / 有标号**：上面生成的都是有标号树；如果题目要的是无标号计数，随机数据没有意义。
- **边权与点权**：不少题还要给边权，记得在每条边后面再输出一个随机权值。

## 对比与扩展

- 与「一般图生成」的关系：树是最小连通结构，先在树上加边就得到连通图；先造森林再加边可以得到不连通图。
- 想造「随机形态更均匀」的树，可以用 Prüfer 序列，但写起来比上面这套麻烦得多，对拍一般用不上。
- 卡常/卡栈时，把链、菊花、二叉树、随机树各造一组，覆盖面就很足了。$AKB371$, '实用工具', array['对拍', '随机数据', '树', '基环树', '菊花图', '二叉树'], 'col-hub-utility-debug', null, 'knowledge'),
('Fohen', 'col-basic-template-header--fenfeng', '自用头文件 · Fohen', $AKB372$## 算法原理

自用头文件是竞赛选手长期积累、固定复用的代码模板：把高频出现的宏定义、类型别名和快读快写函数集中放在一起，每道题开头直接套用，省去重复编写、统一代码风格。它的核心价值是「约定优于配置」——用一套固定的宏与函数名，把注意力留给算法本身，而不是输入输出细节。

本模板主要包含四块内容：

- **万能头文件与命名空间**：`#include<bits/stdc++.h>` 加 `using namespace std`，一次包含绝大多数标准库并省略 `std::` 前缀。
- **宏定义**：`endl`、`fi`、`se`、`lowbit`、`int`、`pb`、`vi`，用于缩短高频写法。
- **类型别名**：`PII`（二元组）、`ll`（`long long`）。
- **快读快写**：`read()` / `write()`，以及 `main` 里的同步关闭与文件重定向占位。

其中最核心的两点约定是：用 `#define int long long` 统一把 `int` 提升为 `long long`、配合 `signed main()` 规避溢出；用「字符逐位转数字 + 位运算加速」的快读思路把输入输出常数压到最低。

## 核心公式 / 状态定义与转移方程

模板本身没有递推状态，这里给出几个宏与函数背后的等价变换，便于理解「为什么这样写」。

- **取最低位的 1**（`lowbit`）：

$$
\mathrm{lowbit}(x) = x \mathbin{\&} (-x)
$$

其中 $-x$ 在补码下等于按位取反再加 1，即 $\sim x + 1$，二者按位与后只保留 $x$ 最低位的 1。

- **字符转数字**：设字符 $c$ 为数字字符 `'0'`～`'9'`，其 ASCII 值为 $48$～$57$，则

$$
d = c - 48 = c \mathbin{\oplus} 48
$$

数字字符的高位固定，低 4 位恰好为 $0$～$9$，与 $48$（二进制 `110000`）按位异或即等价于减 $48$。

- **快读累加**：读到数字位 $d$ 时，把已读入的值 $x$ 左移合并：

$$
x \leftarrow 10x + d = (x \ll 1) + (x \ll 3) + d
$$

其中 $(x \ll 1) + (x \ll 3) = 2x + 8x = 10x$，用位运算代替乘法。

- **快写递归**：设 $x$ 为非负整数，先递归输出 $\lfloor x/10 \rfloor$，再输出个位字符 $(x \bmod 10) + 48$；当 $x < 10$ 时不再递归，直接输出最高位。

## 逐行代码解析

模板按「宏定义 → 类型别名与 main → 快读 → 快写」四块组织，下面逐块讲解。

### 头文件与宏定义

```cpp
#include<bits/stdc++.h>
#define endl '\n'//交互题去掉
#define fi first
#define se second
#define lowbit(x) (x&(-x))
#define int long long
#define pb push_back
#define vi vector<int>
//#define v2 vector<vector<int>>
using namespace std;
```

- `#include<bits/stdc++.h>` 是万能头文件，一次包含几乎全部标准库；它是 GCC 扩展，正式竞赛环境（GCC）可用，但 MSVC 没有此头文件。
- `#define endl '\n'`：把 `endl` 替换为换行符 `'\n'`，避免 `std::endl` 每次 flush 带来的性能损失；交互题需要及时刷新输出，必须去掉这行。
- `#define fi first` / `#define se second`：把 `pair` 的 `first` / `second` 缩写为 `fi` / `se`。
- `#define lowbit(x) (x&(-x))`：取最低位的 1，常用于树状数组，见「核心公式」。
- `#define int long long`：把 `int` 全部替换为 `long long`，规避中间结果溢出；代价是 `main` 必须写成 `signed main()`。
- `#define pb push_back`：容器 `push_back` 缩写。
- `#define vi vector<int>`：`vector<int>` 缩写；注意宏会二次展开，`int` 会被替换，见「常见陷阱」。
- `//#define v2 vector<vector<int>>` 是注释掉的二维 vector 缩写，按需放开。

### 类型别名与 main 框架

```cpp
typedef pair<int,int> PII;
typedef long long ll;
//const int N=1e5+10;
//int cnt=0;
//int a[N];

signed main(){
//    freopen(".in","r",stdin);
//    freopen(".out","w",stdout);
    ios::sync_with_stdio(false);
    cin.tie(nullptr);cout.tie(nullptr);
	//int n;cin>>n;
    return 0;
}
```

- `typedef pair<int,int> PII;`：常用二元组别名；由于 `#define int long long`，它实际等价于 `pair<long long, long long>`。
- `typedef long long ll;`：这行不含 `int` 记号，不受宏影响，`ll` 仍为 `long long`。
- 注释掉的 `const int N`、`cnt`、`a[N]` 是预留的数组空间，按题目需求放开并填大小。
- `signed main()`：因为 `#define int long long`，写 `int main()` 会被展开成 `long long main()`，违反 main 必须返回 `int` 的规定而编译失败；`signed` 等价于 `signed int`，不受宏影响。
- `freopen` 两行是注释占位：本地或评测需要文件输入输出时放开并填入文件名。
- `ios::sync_with_stdio(false);` 关闭 C 与 C++ 流同步，`cin.tie(nullptr); cout.tie(nullptr);` 解绑输入输出流，二者配合加速流式读写。

### 快读 read()

```cpp
inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch< '0'||ch>'9'){
        if(ch=='-') f=-1;
        ch=getchar();
    }
    while(ch>='0'&&ch<='9'){
        x=(x<<1)+(x<<3)+(ch^48);
        ch=getchar();
    }
    return x*f;
}
```

- `x=0` 累计结果，`f=1` 记录符号。
- 第一个 `while` 跳过非数字字符，遇到 `-` 置 `f=-1`，用于读负数。
- 第二个 `while` 逐位读数字：`ch^48` 等价 `ch-'0'`，`(x<<1)+(x<<3)` 等价 `x*10`，三者相加即 `x = x*10 + digit`。
- 返回 `x*f` 带上符号。由于 `#define int long long`，`read` 的返回类型实际是 `long long`，可读入超出 `int` 范围的数。

### 快写 write()

```cpp
inline void write(int x){
    if(x<0){
        putchar('-');
        x=-x;
    }
    if(x>9) write(x/10);
    putchar(x%10+'0');
}
```

- 负数先输出 `-` 并取相反数。
- `if(x>9) write(x/10)` 递归先输出高位，实现「先高位后低位」。
- `putchar(x%10+'0')` 输出当前个位：`x%10` 得到数字，`+'0'` 转回字符。

## 复杂度分析

- **快读快写**：每次调用按十进制位数逐字符处理，时间复杂度为 $O(\log V)$，其中 $V$ 是数值大小，位数 $=\Theta(\log_{10} V)$。
- **关闭同步的流式读写**：单次读写接近常数，整体取决于数据规模。
- **模板整体**：视具体实现。本模板只提供框架，不决定所写算法的复杂度。
- **空间复杂度**：视具体实现。宏与类型别名不占用运行空间；快读快写只用常数个局部变量，为 $O(1)$。

## 适用场景

- 竞赛日常刷题、比赛的统一答题模板，开题即套用，省去重复的输入输出样板。
- 数据量大的题目：用 `read()` / `write()` 快读快写替代 `cin` / `cout` 或 `scanf` / `printf`，避免输入输出成为瓶颈。
- 需要 `long long` 的题目：`#define int long long` 规避累加、乘法等中间结果溢出。
- 树状数组等需要 `lowbit`、或大量使用 `pair`、`vector` 的题目：宏与别名显著减少代码量。

## 常见陷阱与注意事项

1. `#define int long long` 必须配 `signed main()`：否则 `int main()` 被展开成 `long long main()`，导致编译失败。
2. `#define endl '\n'` 在交互题必须去掉：`std::endl` 会 flush，`'\n'` 不会；交互题需要每次输出立即刷新，用 `'\n'` 可能因缓冲导致评测挂起。
3. 宏缺少整体括号：`#define lowbit(x) (x&(-x))` 只给参数加了括号，未给整体加括号。传 `lowbit(a+1)` 会展开成 `a+1&(-a+1)`，优先级出错；稳妥写法是 `((x)&(-(x)))`。
4. 别名被二次展开：`#define int long long` 之后，`vi` 展开为 `vector<int>` 再被二次展开为 `vector<long long>`；`typedef pair<int,int> PII` 同样变为 `pair<long long,long long>`。需要严格的 32 位 `int` 时应改用 `signed` 或 `int32_t`。
5. 快读不处理文件末尾：`while(ch<'0'||ch>'9')` 在 `getchar()` 读到 EOF（返回 $-1$）时，$-1 < 48$ 恒成立，会死循环。题目保证输入合法时无碍，稳健写法应在循环内判断 `ch == EOF`。
6. 万能头文件是 GCC 扩展：`<bits/stdc++.h>` 在 MSVC 下不存在，提交 OJ 多为 GCC 环境无碍，本地若用 VS 需注意。
7. 快读快写与流混用：`read` / `write` 走 `getchar` / `putchar`，与关闭同步后的 `cin` / `cout` 是两套缓冲，混用可能出现顺序错乱；同一程序要么全用快读快写，要么全用流。

## 对比与扩展

| 输入输出方式 | 写法 | 特点 | 适用 |
|---|---|---|---|
| 标准 cin/cout | `cin >> x; cout << x;` | 默认与 C 同步，较慢 | 数据量小、调试 |
| 关闭同步 cin/cout | `ios::sync_with_stdio(false)` | 关闭同步，较快 | 中等数据量 |
| scanf/printf | `scanf("%d",&x)` | C 风格，格式控制强 | 大数据量、格式控制 |
| 快读快写 | `read()` / `write()` | 无流同步，常数小 | 大数据量、追求常数 |

**扩展方向**：

- 万能头文件可换 `<bits/extc++.h>` 并引入 `__gnu_pbds` 命名空间，获得平衡树、堆等扩展结构，但需注意与 `std::priority_queue` 的冲突。
- 快读可扩展为读取 `long double`、`__int128`（需手动解析）、`string` 等版本；快写同理可扩展为写 `long long`（本模板中 `int` 已宏展开为 `long long`，`x/10`、`x%10` 已适用于 `long long`）。
- `#define int long long` 可换 `using ll = long long` 加显式使用，更可控但写起来略啰嗦。
- 可按个人习惯补充 `#define v2 vector<vector<int>>`、`for` 循环缩写等宏。$AKB372$, '实用工具', array['比赛模板', '快读快写', '宏定义', '输入输出', '实用工具'], 'col-hub-utility-other', null, 'knowledge'),
