这就是一份「自用竞赛模板」：把每次写题都要敲的开头攒成一块，比赛时复制粘贴，省下敲 `#include` 和快读快写的功夫。

它干的事主要有三件：

- 用**万能头** `bits/stdc++.h` 一口气把常用 STL 全包进来；
- 用一批**宏定义**给常用写法起短名字（`fi` / `se` / `pb` / `lowbit` 等），并且用 `#define int long long` 从源头堵住爆 `int` 的坑；
- 配上一套**快读 `read` / 快写 `write`**，在数据量大、`cin`/`cout` 顶不住的时候救场。

下面的代码原样取自源笔记，分模块拆开讲解。

## 逐行代码解析

### 宏定义块

```cpp
#include<bits/stdc++.h>
#define endl '\n'//交互题去掉
#define fi first
#define se second
#define lowbit(x) (x&(-x))
#define int long long
#define pb push_back
#define vi vector<int>
//#define v2 vector<vector<int>>
using namespace std;
typedef pair<int,int> PII;
typedef long long ll;
//const int N=1e5+10;
//int cnt=0;
//int a[N];
inline int read();
inline void write(int x);
```

- `#include<bits/stdc++.h>`：万能头，把 STL 全家桶一次引入。
- `#define endl '\n'`：`endl` 会顺带 flush，换成 `'\n'` 能快不少；**但交互题必须去掉**（交互要靠 flush 把输出推给对方）。
- `#define fi first` / `#define se second`：少打几个字符。
- `#define lowbit(x) (x&(-x))`：树状数组的低位提取惯用写法。
- `#define int long long`：把 `int` 全局替换成 `long long`，防溢出神器；代价是常数和内存都会涨，**有被卡的风险**，而且从此 `main` 得写成 `signed main()`。
- `#define pb push_back` / `#define vi vector<int>`：常用容器 / 操作缩写。
- 注释里的 `v2`、`N`、`cnt`、`a[N]` 是留着的备用声明，用不到就保持注释。
- 最后两行是对 `read` / `write` 的**前置声明**，让 `main` 里能直接调用（定义都写在后面）。

### 主函数 main

```cpp
signed main(){
//    freopen(".in","r",stdin);
//    freopen(".out","w",stdout);
    ios::sync_with_stdio(false);
    cin.tie(nullptr);cout.tie(nullptr);
	//int n;cin>>n;
    return 0;
}
```

- `signed main()`：因为上面 `int` 被替换成了 `long long`，标准要求的 `int main` 得显式写成 `signed main()`，否则报错。
- 注释里的 `freopen` 是本地读文件调试用，**提交前记得保持注释状态**。
- `ios::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);`：解除 `cin`/`cout` 与 C 标准 IO 的同步，加速输入输出。
- `return 0;`：正常结束。

### 快读 read

```cpp
inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch< '0'||ch>'9'){
        if(ch=='-') f=-1;
        ch=getchar();
    }
    while(ch>='0'&&ch<='9'){
        x=(x<<1)+(x<<3)+(ch^48);
        ch=getchar();
    }
    return x*f;
}
```

- `int x=0,f=1;`：`x` 存数值，`f` 存符号。
- 第一个 `while`：跳过所有非数字字符，遇到 `-` 记下负号。
- 第二个 `while`：逐位累加，`(x<<1)+(x<<3)` 就是 `x*10`，`ch^48` 等价于 `ch-'0'` 把字符转成数字。
- `return x*f;`：带上符号返回。
- `inline` 提示编译器内联，减少函数调用开销。

### 快写 write

```cpp
inline void write(int x){
    if(x<0){
        putchar('-');
        x=-x;
    }
    if(x>9) write(x/10);
    putchar(x%10+'0');
}
```

- 开头先处理负数：打一个 `-`，再取相反数。
- `if(x>9) write(x/10);`：递归处理高位，再打当前最低位，这样数字就是**正序**输出。
- `putchar(x%10+'0');`：把最低位数字转回字符输出。
- 注意 `write` 只支持整数，输出完不会自动换行，需要换行得自己补。

## 复杂度分析

各部分与「你的程序内容」无关，本身复杂度都很低：

- **快读 `read`**：与读入的字符数成正比，设一次读入的数字有 $d$ 位，则为 $O(d)$。
- **快写 `write`**：按位递归输出，位数 $d$，递归深度 $O(d)$，总时间 $O(d)$。
- **宏定义 / `main`**：均为 $O(1)$。
- 整体不改变算法复杂度，因此本知识点标注为**视具体实现**。

## 适用场景

- **竞赛一键模板**：比赛时复制粘贴，省去反复敲开头。
- **卡常 / 大数据量输入**：`cin`/`cout` 太慢时，改用这套快读快写。
- **防溢出**：`#define int long long` 让所有 `int` 都变大，省得逐个改。

## 常见陷阱与注意事项

1. **`#define int long long` 之后必须写 `signed main()`**：直接写 `int main()` 会报错；同时常数和内存都会变大，别在卡常题上无脑开。
2. **`#define endl '\n'` 交互题要去掉**：交互题依赖 flush，换成 `'\n'` 会导致输出没及时推给对方。
3. **解除同步后别混用两种 IO**：`ios::sync_with_stdio(false)` 之后再用 `scanf`/`printf` 与 `cin`/`cout` 混读混写会出问题；要用快读快写就统一用。
4. **`freopen` 提交前务必备注**：留着重定向会读不到标准输入、直接 RE/WA。
5. **`write` 不自动换行、只吃整数**：需要换行要自己补 `putchar('\n')`。
6. **末尾输出别忘 flush**：程序正常结束会自动 flush，但如果中途用 `_exit` 之类强退要注意。

## 对比与扩展

| 输入输出方式 | 写法 | 速度 | 备注 |
|---|---|---|---|
| `cin` / `cout` | 最简单 | 慢（解除同步后中等） | 代码短，适合小数据 |
| `scanf` / `printf` | 格式化 | 较快 | C 风格，格式符要小心 |
| `getchar` 快读 / `putchar` 快写 | 如上模板 | 快 | 数据量大时首选 |
| `fread` 整块读入 | 手写缓冲区 | 最快 | 代码更长，题解模板常见 |

扩展方向：把 `read` 重载成支持 `long long` / `double` / 字符串，或改用 `fread` 版本进一步提速；宏那部分也可以按个人习惯增删。若要参考同作者的自动机 / 字符串模板，可对照相关知识点。$AKB373$, '实用工具', array['模板', '头文件', '快读', '快写', '宏定义'], 'col-hub-utility-other', null, 'knowledge'),
('Fohen', 'col-basic-timing--fenfeng', '时间测试 · Fohen', $AKB374$## 算法原理

「时间测试」指不依赖评测机（OJ），在本地直接测量一段程序实际消耗的时间，从而判断它能否在时限内通过、以及不同写法之间的快慢。

核心工具是 C++ 标准库 `<ctime>` 提供的 `clock()` 函数与常量 `CLOCKS_PER_SEC`。`clock()` 返回自程序启动以来（或某个实现定义的起点）消耗的**处理器时间**（CPU 时间）的计数值；`CLOCKS_PER_SEC` 表示该计数值每秒钟对应的数量，即「时钟滴答」数。于是，先在被测代码执行前后各取一次计数值，两者之差除以 `CLOCKS_PER_SEC`，就得到这段代码消耗的秒数。

这里需要区分两点：`clock()` 统计的是 **CPU 时间**而非「墙上钟表时间」——程序因睡眠、等待输入、I/O 阻塞而挂起的时间不会被计入；因此它更适合衡量「这段代码真正干了多少活」，而不是「从开始到结束过了多久」。对竞赛中估测算法运行耗时而言，前者通常正是我们关心的对象。

## 核心公式 / 状态定义与转移方程

设被测代码块执行前后分别调用 `clock()` 得到两个计数值 $C_1$ 与 $C_2$，则这段代码消耗的处理器时间（单位：秒）为：

$$
t = \frac{C_2 - C_1}{\text{CLOCKS\_PER\_SEC}}
$$

其中 `CLOCKS_PER_SEC` 是 `<ctime>` 中定义的常量，表示 `clock()` 返回值每秒钟对应的计数值；不同系统上它的取值可能不同（常见为 $10^6$ 或 $10^3$），因此**不要**在代码里写死它的数值，一律使用该常量。

由于 `clock()` 返回整数计数，$C_2 - C_1$ 可能为 $0$（代码跑得太快、低于一个时钟滴答），此时测出的时间为 $0$，说明这段代码执行时间过短，需要把它放进循环里多跑若干次再取平均，才能得到有意义的测量值。

## 逐行代码解析

以下是最基本的计时框架（关键用法 / 伪代码，非可运行程序）：

```cpp
#include <ctime>                                      // 提供 clock() 与 CLOCKS_PER_SEC

clock_t t1 = clock();                                 // 第 1 次计时：记录起点
// 在这里放入要测量的程序主体
clock_t t2 = clock();                                 // 第 2 次计时：记录终点
double elapsed = (double)(t2 - t1) / CLOCKS_PER_SEC;  // 换算成秒
```

几个关键点：

- `clock()` 的返回类型是 `clock_t`（通常为整数类型），直接相减得到两个计数值之差，再除以 `CLOCKS_PER_SEC` 得到秒数；注意分子要先转成 `double`，避免整数除法把结果截断成 $0$。
- 计时范围必须严格覆盖被测代码：`t1` 取在主体之前、`t2` 取在主体之后，中间不要夹带无关的输入输出，否则会把 I/O 时间也算进去。
- 若代码运行时间极短，一次测量可能得到 $0$，可将被测代码整体放入循环重复 $m$ 次，再用总时间除以 $m$ 得到单次平均耗时。

## 复杂度分析

「时间测试」是一个观测工具，本身不改变被测算法的复杂度：`clock()` 每次调用是 $O(1)$ 的常量开销，两次计时几乎不引入额外成本。测量得到的数值取决于被测代码自身，因此本知识点的时间、空间复杂度**视具体实现**。

- **时间复杂度**：视具体实现。计时框架只是两次 $O(1)$ 调用，实际运行时间由被测算法决定。
- **空间复杂度**：视具体实现。计时框架只额外使用常数个变量（$O(1)$），其余空间全部来自被测算法。

## 适用场景

- **本地估时**：在本地（而非 OJ）大致判断某份代码会不会超时，避免「交上去才超时」。
- **比较不同写法**：对同一问题的多种实现各测一遍，横向对比谁更快，辅助选择与优化。
- **暴力卡时（骗分）**：在暴力程序里设置一个时限阈值，运行到接近超时时立刻结束并输出当前最优答案，从而在保证不超时的前提下尽量多拿部分分。
- **调试定位**：分别测出程序各阶段（读入、预处理、核心计算、输出）的耗时，定位性能瓶颈。

## 常见陷阱与注意事项

1. **`clock()` 测的是 CPU 时间，不是墙上时间**：程序睡眠、等待输入或被操作系统暂停的时间不会被计入；若要测量「从开始到结束的真实经过时间」，应改用 `std::chrono` 的 `steady_clock`。
2. **整数除法截断**：`(t2 - t1) / CLOCKS_PER_SEC` 若分子是整数，会先做整数除法再隐式转换，结果恒为 $0$；务必把分子先转成 `double` 再除。
3. **不要写死 `CLOCKS_PER_SEC` 的数值**：它在不同系统上的取值可能不同，必须使用常量本身，否则换算出的秒数会出错。
4. **计时区间要干净**：把无关的输入输出、文件读写夹在 `t1` 与 `t2` 之间，会把 I/O 时间混进测量结果。
5. **太短测不出**：单次运行时间低于一个时钟滴答时会得到 $0$，需循环多次取平均；计时函数自身也有极小的系统误差，短代码要多测几遍、剔除明显异常值。
6. **编译选项影响结论**：不同优化级别（如 `-O2`）下代码运行速度差异很大，对比不同写法时应在相同编译选项与相同环境下测量。

## 对比与扩展

| 方法 | 测量对象 | 特点 |
|---|---|---|
| `clock()` + `CLOCKS_PER_SEC` | CPU 时间 | 简单直观，适合估算算法耗时 |
| `std::chrono::steady_clock` | 墙上时间（单调时钟） | C++11 起推荐，精度高、不受系统改时间影响 |
| `std::chrono::high_resolution_clock` | 平台可用的最高精度时钟 | 精度最高，但不同平台语义略有差异 |
| `gettimeofday` / `QueryPerformanceCounter` | 墙上时间 / 高精度计数 | 平台相关，竞赛中不如前两者通用 |

扩展方向：

- **卡时暴力**：在暴力、搜索或随机化算法里，每次迭代前用 `clock()` 检查已用时间，一旦超过阈值（如题目时限的 $90\%$）立即停止并输出当前最优解，避免超时后连部分分都拿不到。
- **对拍测速**：把计时写进对拍脚本或 `stress` 流程，批量比较正解与暴力在不同数据规模下的耗时，辅助验证复杂度上界。
- **`std::chrono` 计时模板**：用 `steady_clock` 的 `now()` 与 `duration_cast` 封装成通用计时器，既能测量墙上时间，也能返回毫秒、微秒级结果。$AKB374$, '实用工具', array['计时', '卡时', '调试', '暴力'], 'col-hub-utility-debug', null, 'knowledge'),
('Xesir', 'col-basic-timing--xesir', '时间测试 · Xesir', $AKB375$## 算法原理

有时候你想知道自己的代码到底跑了多长时间，又懒得把代码丢到 OJ 上测——那就用 `clock()` 直接在本机量。

它的原理很朴素：`clock()` 返回**程序启动到现在消耗的时间**（以「时钟单位」计），而 `CLOCKS_PER_SEC` 是每秒钟包含多少个这样的时钟单位。后者是个常数，所以拿时间长度的差除以它，就换算成了**秒**。

除了便于调试，它在赛场上还有个更「实战」的用途：给暴力程序上一道保险。当运行快到超时的时候，直接结束并输出当前答案，就能多骗几个点。~~awa~~

## 逐行代码解析

源笔记里的完整计时段如下（原样搬运）：

### 计时段

```cpp
double t1=clock();
//TODO你的程序内容
double t2=clock();
double ans=(t2-t1)/CLOCKS_PER_SEC;
```

- `double t1=clock();`：在待测程序**开始前**记下当前时间。
- 中间那行注释是**占位**，把要测的程序内容替换到这里。
- `double t2=clock();`：程序跑完后，再记一次时间。
- `double ans=(t2-t1)/CLOCKS_PER_SEC;`：两次之差是消耗的时钟单位数，除以 `CLOCKS_PER_SEC` 换算成秒，结果就存进 `ans`。

### 卡时骗分

把 `ans` 的上限当作「预算」，在暴力搜索 / 枚举的主循环里定期检查：

```text
每次搜索一层时，如果 (clock()-t1)/CLOCKS_PER_SEC 已超过设定的安全值，
就立刻停止搜索并输出当前找到的答案
```

- 这样即使最优解没跑完，也能把已经得到的答案交上去，不至于 TLE 到一分没有。
- 但因为输出的是「当前最优」而非真解，本质是骗分手段，只适用于暴力 / 部分分的场合。

## 复杂度分析

`clock()` 本身是 $O(1)$ 的，取时间、做除法都不改变原算法的复杂度。

- **时间复杂度**：不改动被测程序的复杂度，取决于「你的程序内容」，故**视具体实现**。
- **空间复杂度**：只多了两个 `double`，$O(1)$。

## 适用场景

- **本地调试、对拍**：快速确认一段代码或一组数据的耗时。
- **暴力卡时骗分**：赛场上给搜索 / 枚举型暴力加一个时间上限，尽量多拿部分分。
- **估算常数**：同一算法不同写法，跑同一份数据对比耗时，选出常数更小的实现。

## 常见陷阱与注意事项

1. **`clock()` 量的是 CPU 时间**：它统计的是程序占用 CPU 的时间，和挂钟上流逝的时间不完全一样（比如程序阻塞等待时会「不计入」），所以和你在任务管理器里看到的时间可能对不上。
2. **单位要靠 `CLOCKS_PER_SEC` 换算**：它是个平台相关的常数（POSIX 上通常为 $10^6$），不要想当然当成 1000。
3. **精度有限**：在部分环境里 `clock()` 的分辨率较低，测极短程序误差会很大，多跑几遍 / 加大数据量更靠谱。
4. **别把卡时逻辑留在正式提交里**：骗分用的时间判断一旦触发会提前结束、输出不完整，正解程序必须去掉它。
5. **交互题慎用**：交互题里时间花在通信等待上，`clock()` 量到的 CPU 时间参考价值有限。

## 对比与扩展

| 工具 | 头文件 | 量的是 | 特点 |
|---|---|---|---|
| `clock()` / `CLOCKS_PER_SEC` | `<ctime>` | CPU 时间 | 简单，单位需换算，精度一般 |
| `time()` | `<ctime>` | 挂钟时间（秒级） | 精度低（秒），适合粗测 |
| `std::chrono::steady_clock` | `<chrono>` | 单调挂钟时间 | C++11 起，精度高，推荐 |
| `gettimeofday` / `std::chrono::system_clock` | `<sys/time.h>` / `<chrono>` | 系统时间 | 高精度，写法略繁琐 |

扩展方向：真要精确测时，C++11 之后优先用 `std::chrono`；而对拍、卡时这类脚本化操作，往往配合 `tools/stress.cmd` 之类的对拍流程一起用。$AKB375$, '实用工具', array['clock', '时间测试', '卡时', '骗分', '调试'], 'col-hub-utility-debug', null, 'knowledge'),
('Fohen', 'col-ds-pbds--fenfeng', 'pb_ds（基于策略的数据结构） · Fohen', $AKB376$## 算法原理

pb_ds（Policy-Based Data Structures，基于策略的数据结构）是 GCC 自带的扩展库，封装了平衡树、堆、字典树（Trie）与哈希表四类数据结构，功能强大且实现现成，省去手写的麻烦。竞赛中最常用的两个部分是：

1. **平衡树 `tree`**：一个"免写平衡树"，把几十甚至上百行的手写平衡树压缩到十几行。
2. **配对堆 `priority_queue`**：补齐了 `std::priority_queue` 的短板——可以修改堆内已有元素、删除任意元素，并且支持 $O(1)$ 合并两个堆。

"基于策略"的含义是：底层行为由模板参数决定——`Tag` 参数选择底层实现（如红黑树、配对堆），`Node_Update` 参数选择节点更新策略（如是否启用排名统计）。同一套接口，换一个模板参数就能切换实现，这正是它灵活的原因。

关于 NOI 系列竞赛的合规性：2021 年 9 月 1 日发布的《关于 NOI 系列活动中编程语言使用限制的补充说明》允许使用以下划线开头的库函数或宏（明确禁止操作的除外），这让 pb_ds 库的使用有了文件依据，在 NOI 系列竞赛中属于**完全允许**的范围。

需要强调的是，pb_ds 只在以 libstdc++ 为标准库的编译器（如 GCC / MinGW）下可用；在部分竞赛使用的 Dev-C++ 等环境中往往无法通过本地编译，导致代码难以本地调试，使用前需确认评测环境与本地环境一致。

## 核心公式 / 状态定义与转移方程

### 模板参数定义

平衡树 `tree` 的完整定义：

```cpp
tree<Key, Mapped, Cmp_Fn, Tag, Node_Update, Allocator>
```

- `Key`：存储的元素类型（自动去重）。
- `Mapped`：映射值类型；作 set 用时填 `null_type`，作 map 用时填具体值类型。
- `Cmp_Fn`：键的比较函子，决定元素在树中的排序规则，如 `less<Key>` 或 `greater<Key>`。
- `Tag`：底层数据结构，平衡树一般选用红黑树 `rb_tree_tag`。
- `Node_Update`：节点更新策略，填 `tree_order_statistics_node_update` 可启用排名统计，默认不启用。
- `Allocator`：空间配置器，使用默认值即可。

配对堆 `priority_queue` 的完整定义：

```cpp
__gnu_pbds::priority_queue<T, Compare, Tag, Allocator>
```

- `T`：存储的元素类型（支持自定义类型）。
- `Compare`：提供严格弱序的比较类型。
- `Tag`：堆的实现类型，默认为 `pairing_heap_tag`（配对堆）。
- `Allocator`：空间配置器，一般用不到。

### 排名与顺序统计

设树中已含 $n$ 个元素，$x$ 为待查询的键：

- `order_of_key(x)` 返回树中**严格小于** $x$ 的元素个数，记为 $k$。因此 $x$ 在树中的排名（从 $1$ 计）为 $k+1$。
- `find_by_order(k)` 返回从 $0$ 开始计的第 $k$ 个元素（即第 $k+1$ 小）的迭代器；当 $k \ge n$ 时返回 `end()`。

这两个操作互为逆操作：若 `find_by_order(k)` 指向元素 $x$，则 `order_of_key(x)` 返回 $k$。

### 复杂度关系

- 平衡树（红黑树）：所有查询与修改操作均为 $O(\log n)$。
- 配对堆：`push`、`top`、`join` 为 $O(1)$；`pop`、`modify`、`erase` 最坏 $O(n)$，均摊 $O(\log n)$。

## 逐行代码解析

### 头文件与命名空间

```cpp
#include <bits/extc++.h>    // 同时包含 STL、pb_ds 与 <bits/stdc++.h> 的全部内容
using namespace __gnu_pbds; // pb_ds 的通用命名空间
```

pb_ds 主要位于 `ext/pb_ds/assoc_container.hpp` 与 `ext/pb_ds/tree_policy.hpp` 两个头文件，`<bits/extc++.h>` 一次把它们连同 STL 全部引入。需要注意的是，`__gnu_pbds::priority_queue` 与 `std::priority_queue` 同名冲突，不要同时打开 `using namespace std;` 与 `using namespace __gnu_pbds;`。

### 配对堆用法

```cpp
__gnu_pbds::priority_queue<int> pq;   // 默认配对堆，大根堆
pq.push(x);                            // O(1) 压入，返回指向该元素的迭代器
int t = pq.top();                      // O(1) 取堆顶
pq.pop();                              // 弹出堆顶，均摊 O(log n)
pq.modify(it, new_key);                // 修改迭代器 it 处键值并重新调整
pq.erase(it);                          // 删除迭代器 it 处的元素
pq.join(other);                        // O(1) 合并 other，并把 other 清空
```

配对堆不仅支持普通堆的操作，还多了修改、删除任意元素与 $O(1)$ 合并，因此它同时是一个**可并堆**，很多场景下不必再手写左偏树。

### 平衡树用法

```cpp
tree<int, null_type, less<int>, rb_tree_tag, tree_order_statistics_node_update> tr;
tr.insert(x);                          // O(log n) 插入（自动去重）
auto it = tr.find(x);                  // 查找 x，找不到返回 end()
int k = tr.order_of_key(x);            // 严格小于 x 的元素个数
auto it2 = tr.find_by_order(k);        // 第 k（0 基）个元素的迭代器
tr.erase(x);                           // 删除所有等于 x 的元素
```

`tree` 的 `Key` 会自动去重；若需要保留重复元素（即模拟 multiset），常用 `pair<int, int>` 作为键，用第二维编号区分相同元素，例如 `tree<pair<int,int>, null_type, less<pair<int,int>>, rb_tree_tag, tree_order_statistics_node_update>`。

## 复杂度分析

### 配对堆

| 操作 | 说明 | 复杂度 |
|---|---|---|
| `push(x)` | 压入元素 | $O(1)$ |
| `top()` | 取堆顶 | $O(1)$ |
| `pop()` | 弹出堆顶 | 最坏 $O(n)$，均摊 $O(\log n)$ |
| `modify(it, k)` | 修改迭代器处键值并调整 | 最坏 $O(n)$，均摊 $O(\log n)$ |
| `erase(it)` | 删除迭代器处元素 | 最坏 $O(n)$，均摊 $O(\log n)$ |
| `join(other)` | 合并另一堆并清空 | $O(1)$ |

### 平衡树

| 操作 | 说明 | 复杂度 |
|---|---|---|
| `insert(x)` | 插入元素 | $O(\log n)$ |
| `erase(x)` / `erase(it)` | 删除元素 | $O(\log n)$ |
| `find(x)` | 查找元素 | $O(\log n)$ |
| `lower_bound(x)` / `upper_bound(x)` | 二分定位 | $O(\log n)$ |
| `order_of_key(x)` | 严格小于 x 的元素个数 | $O(\log n)$ |
| `find_by_order(k)` | 第 k（0 基）个元素 | $O(\log n)$ |
| `join(other)` | 合并两树（值域不相交） | 理论 $O(\log n)$，实测常数较大 |
| `split(k, other)` | 分裂出大于 k 的部分 | 理论 $O(\log^2 n)$，可能退化 $O(n)$ |

空间复杂度：两者均随元素个数线性增长，为 $O(n)$。红黑树每个节点需携带颜色与若干指针，常数略大于手写结构，但在竞赛中通常可接受。

## 适用场景

**适用**：

- 需要平衡树、但不想手写 Splay / Treap 的场景（NOI 系列竞赛已允许使用）。
- 需要第 $k$ 小查询与排名统计（`order_of_key` / `find_by_order`）时，`std::set` 不支持，pb_ds 原生支持。
- 需要删除任意元素、修改堆内元素、$O(1)$ 合并堆的场景（配对堆）。
- 元素可去重、且评测环境确定为 libstdc++ 的竞赛代码。

**不适用**：

- 评测机或本地环境不是 libstdc++（如 MSVC、部分旧 Dev-C++）时，代码无法编译。
- 需要严格本地调试、而本地编译器不支持 pb_ds 时。
- 需要自定义维护（如子树和、懒标记）时，标准 `tree` 只提供排名统计，需手写平衡树。
- 对常数敏感且频繁使用 `split` 时，其实际表现可能退化。

## 常见陷阱与注意事项

1. **命名空间冲突**
   - `__gnu_pbds::priority_queue` 与 `std::priority_queue` 同名，同时 `using namespace std;` 与 `using namespace __gnu_pbds;` 会产生二义性。
   - 建议只在需要的范围内打开 `__gnu_pbds`，或全程使用 `__gnu_pbds::` 前缀。

2. **本地编译失败**
   - pb_ds 依赖 libstdc++，非 GCC 系编译器或部分旧版 Dev-C++ 上无法通过编译。
   - 写题前先确认本地与评测环境一致；本地无法调试时改用等价手写结构。

3. **配对堆默认只用配对堆标签**
   - pb_ds 提供五种堆实现，除配对堆外的四种（如 `binary_heap_tag` 等）在竞赛中常因常数过大或内存占用过高而表现不佳，默认一律使用配对堆。

4. **`order_of_key` 的排名语义**
   - 返回的是**严格小于** key 的个数，等于"排名减 $1$"；要用 $1$ 基排名需再加 $1$。
   - 未启用 `tree_order_statistics_node_update` 时，`order_of_key` 与 `find_by_order` 无法使用（编译错误）。

5. **去重与 multiset 模拟**
   - `tree` 的 `Key` 自动去重；需要保留重复元素时，用 `pair<值, 编号>` 作为键。

6. **`join` / `split` 的前置条件**
   - `join(other)` 要求两棵树的值域不相交，合并后 `other` 被清空。
   - `split(k, other)` 要求 `other` 调用前为空；实测常数较大，极端情况下可能退化。

7. **头文件与命名空间的选择**
   - 一般用 `#include <bits/extc++.h>` 一次引入全部内容；也可仅包含 `ext/pb_ds/assoc_container.hpp` 与 `ext/pb_ds/tree_policy.hpp`。

## 对比与扩展

### 平衡树对比

| 对比维度 | pb_ds `tree` | `std::set` / `std::map` | 手写 Splay / Treap |
|---|---|---|---|
| 第 k 小 / 排名 | 原生支持 $O(\log n)$ | 不支持（需另写） | 需自行维护 size |
| 插入 / 删除 / 查找 | $O(\log n)$ | $O(\log n)$ | $O(\log n)$（均摊） |
| 代码量 | 极低（十几行） | 低 | 高（几十到上百行） |
| 自定义维护 | 弱（仅排名统计） | 不支持 | 强（子树和、懒标记等） |
| 可移植性 | 仅 libstdc++ | 标准库，全平台 | 全平台 |

### 堆对比

| 对比维度 | pb_ds 配对堆 | `std::priority_queue` | 左偏树 |
|---|---|---|---|
| $O(1)$ 合并 | 支持 | 不支持 | 支持 |
| 删除任意元素 | 支持 | 不支持 | 支持 |
| 修改堆内元素 | 支持 | 不支持 | 一般需删除后重插 |
| 实现成本 | 低 | 低 | 中 |
| 可移植性 | 仅 libstdc++ | 标准库 | 全平台 |

**扩展**：

- pb_ds 还提供哈希表（`gp_hash_table` 与 `cc_hash_table`，前者更常用且更快）与字典树（`trie`），在需要高性能哈希或前缀匹配时可选用。
- 需要"子树和 / 懒标记"等自定义维护时，pb_ds `tree` 无法胜任，应改用 FHQ-Treap / Splay 等手写结构。
- 配对堆的 $O(1)$ 合并使其成为可并堆的现成替代，适用于需要动态合并集合的堆合并类问题。$AKB376$, '实用工具', array['数据结构', '平衡树', '配对堆', '红黑树', '优先队列'], 'col-hub-utility-stl', null, 'knowledge'),
('Xesir', 'col-ds-pbds--xesir', 'pb_ds（基于策略的数据结构） · Xesir', $AKB377$## 算法原理

**pb_ds**，即「基于策略的数据结构」（policy-based data structures），是 GCC 自带的扩展库。它封装了**平衡树、堆、字典树、哈希表**四种数据结构，功能极其强大。~~STL 你不要给我打电话了我怕 pb_ds 误会~~

2021 年 9 月 1 日，根据《关于 NOI 系列活动中编程语言使用限制的补充说明》，允许使用以下划线开头的库函数或宏（但具有明确禁止操作的库函数和宏除外）。这让在 NOI 系列活动中使用 pb_ds 库的合规性有了文件上的依据。所以在 NOI 系列竞赛中**完全允许**使用 pb_ds，可以正常运行，不用担心误入小黑屋。

> 但有一点需要注意：pb_ds 只在使用 libstdc++ 为标准库的编译器下可以使用，在 NOI 系列竞赛中使用的 Dev 等编译器上往往**无法通过本地编译**，这使得用 pb_ds 实现的代码难以在本地调试，使用需慎重。~~当然你要是打网赛用这个那就啥事没有~~

**下面是食用方法。**

## 逐行代码解析

### 配置

pb_ds 库主要包含在这两个头文件中：

```text
ext/pb_ds/assoc_container.hpp
ext/pb_ds/tree_policy.hpp
```

一般情况下我们直接使用 `#include <bits/extc++.h>`，它包含了 `STL` 库、`pb_ds` 库以及 `<bits/stdc++.h>` 里的所有内容，可以直接无脑使用。~~健忘症福音~~

pb_ds 的通用命名空间是 `__gnu_pbds`，所以使用时**可以无脑用下面这个配置：**

```cpp
#include <bits/extc++.h>
using namespace __gnu_pbds;
```

唯一需要注意的是，这个命名空间会与 `std` 里的 `priority_queue` 冲突，所以**不要同时开** `using namespace __gnu_pbds;` 与 `using namespace std;`。

### 配对堆

STL 默认的 `std::priority_queue` 是个「死标准堆」：元素一旦 `push` 进去就再也没法修改，也不能快速删除任意元素，更不能 $O(1)$ 合并两个堆。pb_ds 的 `priority_queue` 直接补上了这几个缺口，功能更丰富，常数还很小。

一般堆的定义语法：

```cpp
__gnu_pbds::priority_queue<T, Compare, Tag, Allocator>
```

- `T`：储存的元素类型（支持自定义）。
- `Compare`：提供严格弱序的比较类型。
- `Tag`：`__gnu_pbds` 提供五种不同的堆，默认是 `pairing_heap_tag`，即**配对堆**。除配对堆外的四种堆要么容易 T 飞、要么是 MLE 狂欢节，所以我们默认 pb_ds 的堆只有配对堆，其他都是滚木。
- `Allocator`：空间配置器，一般用不到。

配对堆的成员函数：

| 名称 | 作用 | 返回类型 / 值 | 复杂度 |
|---|---|---|---|
| `push()` | 向堆中压入一个元素 | 迭代器（该元素位置） | $O(1)$ |
| `pop()` | 弹出堆顶元素 | `void` | 最坏 $O(n)$，均摊 $O(\log n)$ |
| `top()` | 返回堆顶元素 | 堆中元素类型 | $O(1)$ |
| `size()` | 返回元素个数 | `size_type` | $O(1)$ |
| `empty()` | 返回是否为空 | `bool` | $O(1)$ |
| `modify(iterator, key)` | 把迭代器位置的键改为传入的 `key` 并重排 | `void` | 最坏 $O(n)$，均摊 $O(\log n)$ |
| `erase(iterator)` | 删除迭代器位置的键值 | `void` | 最坏 $O(n)$，均摊 $O(\log n)$ |
| `join(other)` | 把 `other` 合并到当前堆并把 `other` 清空 | `void` | $O(1)$ |

~~居然还是可并堆，再也不用手写左偏树了 doge~~

### 平衡树

pb_ds 的 `tree` 是竞赛里性价比最高的「免写平衡树」，代码比手写平衡树少了巨多。

一般平衡树的定义语法：

```cpp
tree<Key, Mapped, Cmp_Fn = std::less<Key>, Tag, Node_Update, Allocator>
```

- `Key`：储存的元素类型（自动去重）。
- `Mapped`：映射值类型，类似 set 填 `null_type`，类似 map 填值类型 `V`。
- `Cmp_Fn`：键的比较函子，定义元素的排序规则，如 `less<Key>` 或 `greater<Key>`。
- `Tag`：底层数据结构实现，即平衡树类型，一般选红黑树 `rb_tree_tag`。
- `Node_Update`：节点更新策略，用 `tree_order_statistics_node_update` 可以启用排名功能，默认不启用。
- `Allocator`：空间配置器，用默认值即可。

最常用的是：

```cpp
tree<PII, null_type, less<PII>, rb_tree_tag, tree_order_statistics_node_update> a;
```

平衡树的成员函数：

| 函数 | 作用 | 返回值 | 时间复杂度 |
|---|---|---|---|
| `size()` | 返回当前树中元素个数 | `size_type` | $O(1)$ |
| `empty()` | 判断树是否为空 | `bool` | $O(1)$ |
| `max_size()` | 返回理论最大容量（极少使用） | `size_type` | $O(1)$ |
| `clear()` | 清空树中所有元素 | `void` | $O(1)$ |
| `insert(value)` | 插入元素（或键值对） | `pair<iterator, bool>` | $O(\log n)$ |
| `insert(first, last)` | 插入迭代器区间内的所有元素 | `void` | $O(\log n)$ |
| `erase(iterator)` | 删除迭代器指向的元素 | `void` | $O(\log n)$ |
| `erase(first, last)` | 删除迭代器区间 $[first, last)$ 内的元素 | `void` | $O(\log n)$ |
| `erase(key)` | 删除所有等于 key 的元素 | `size_type`（删除个数，set 中为 0 或 1） | $O(\log n)$ |
| `find(key)` | 查找键为 key 的元素 | 迭代器（找不到返回 `end()`） | $O(\log n)$ |
| `lower_bound(key)` | 返回第一个 $\ge$ key 的元素的迭代器 | 迭代器 | $O(\log n)$ |
| `upper_bound(key)` | 返回第一个 $>$ key 的元素的迭代器 | 迭代器 | $O(\log n)$ |
| `equal_range(key)` | 返回 `pair<lower_bound(key), upper_bound(key)>` | `pair<iterator, iterator>` | $O(\log n)$ |
| `order_of_key(key)` | 返回树中严格小于 key 的元素个数 | `size_type`（相当于排名减 1） | $O(\log n)$ |
| `find_by_order(index)` | 返回排名为 `index`（从 0 开始）的元素的迭代器 | 迭代器（若 `index` $\ge$ size 返回 `end()`） | $O(\log n)$ |
| `join(other)` | 把 `other` 的所有元素合并到当前树，合并后 `other` 被清空，需保证两棵树值域无交集 | `void` | 理论 $O(\log n)$，实测常数较大 |
| `split(key, other)` | 把当前树中所有 $>$ key 的元素移到 `other`，$\le$ key 的留在当前树，要求 `other` 调用前为空 | `void` | 理论 $O(\log^2 n)$，实测可能退化为 $O(n)$ |

pb_ds 本质是个「竞赛速通外挂」：在绝大多数数据结构题里，能把几十甚至上百行的手写代码直接压到十几行，非常适合 OI 选手掌握。

## 复杂度分析

pb_ds 把复杂度都封装在库里，各操作的具体量级**视所选容器与实现**，要点如下：

- **配对堆**：`push` / `top` / `size` / `empty` / `join` 为 $O(1)$；`pop` / `modify` / `erase` 均摊 $O(\log n)$（单个操作最坏可达 $O(n)$）。
- **平衡树（红黑树）**：绝大多数操作（插入、删除、查找、排名相关）都是 $O(\log n)$；`join` 理论 $O(\log n)$、`split` 理论 $O(\log^2 n)$，但实测常数偏大甚至可能退化。
- **空间复杂度**：与元素个数成正比，$O(n)$。

## 适用场景

- **需要「可并堆」**：多路归并、可合并的优先队列场景，配对堆 $O(1)$ `join` 比手写左偏树省事。
- **需要修改 / 删除堆内元素**：普通 `priority_queue` 做不到，配对堆的 `modify` / `erase` 可以。
- **需要平衡树功能又懒得手写**：需要 `order_of_key`（查排名）、`find_by_order`（按排名取值）时，直接用 pb_ds 的 `tree`。
- **哈希表 / 字典树**：pb_ds 还封装了哈希表（`gp_hash_table`）与字典树，卡 `unordered_map` 被 hack 时可作为替代。

## 常见陷阱与注意事项

1. **命名空间冲突**：`using namespace __gnu_pbds;` 与 `using namespace std;` 同开会让 `priority_queue` 歧义，二选一或显式加前缀。
2. **本地编译不过**：pb_ds 依赖 libstdc++，Dev 等竞赛常用编译器常常无法本地编译，导致难以本地调试，赛前先确认评测机能用。
3. **`join` / `split` 有前提**：`join` 要求两棵树值域无交集，`split` 要求目标树调用前为空，违反前提行为未定义。
4. **迭代器会失效**：`pop` / `erase` 之后，原来指向被删元素的迭代器不能再用。
5. **`modify` 要传对迭代器**：它是按迭代器定位的，找不到正确迭代器就改不了；改完键值后库内部会重排。
6. **平衡树自动去重**：`tree` 的 `Key` 自动去重，类似 set，别指望它能存重复键（要多重集得把键设成 `pair<Key, int>` 之类）。
7. **`insert(first, last)` 的复杂度标注**：文档里常写作 $O(\log n)$，实际按区间长度叠加，理解为「每个元素 $O(\log n)$」更稳。

## 对比与扩展

| 需求 | 手写方案 | STL 方案 | pb_ds 方案 |
|---|---|---|---|
| 可并堆 | 左偏树 / 斜堆 | 无 | `priority_queue`（`pairing_heap_tag`） |
| 改 / 删堆内元素 | 手写堆 | 无（需惰性删除） | `priority_queue::modify` / `erase` |
| 查排名 / 按排名取值 | 手写平衡树 | 无 | `tree` + `tree_order_statistics_node_update` |
| 哈希表 | 手写散列表 | `unordered_map` | `gp_hash_table` |

扩展方向：pb_ds 的 `tree` 配合 `order_of_key` / `find_by_order` 可以轻松实现「动态第 $k$ 小」「区间排名」；`gp_hash_table` 在需要抗 hack 时比 `unordered_map` 更稳。想深入可对照站内的平衡树、堆、哈希表相关知识点。$AKB377$, '实用工具', array['pb_ds', '平衡树', '配对堆', '可并堆', 'GCC扩展'], 'col-hub-utility-stl', null, 'knowledge'),
('dbywsc', 'col-ds-stl-associative--dbywsc', '关联式容器（set / map / multiset） · dbywsc', $AKB378$## 算法原理

给定若干个数，如何判断某个数有没有出现过、出现了多少次？最直接的做法是开桶数组 `book[x]`，但数值很大、出现负数、元素不是整数时，桶数组就不好用。

**关联式容器**用“键”来组织数据，内部通常是平衡二叉搜索树（红黑树），因此元素自动有序，查找、插入、删除都是 $O(\log n)$。最常用的三个是：

- `std::map`：键值映射，键有序；
- `std::set`：集合，元素有序且去重；
- `std::multiset`：多重集合，元素有序但不去重。

### std::map

- 定义：`map<int, int> M;`，使用上类似数组。
- `M.count(x)`：判断是否存在键 $x$，返回 $0$ 或 $1$。
- `M[x]`：访问键 $x$ 对应的值；如果不存在会自动插入 `{x, 0}`。
- `M[x]++`、`M.count(x)` 的时间复杂度都是 $O(\log n)$，$n$ 是当前元素个数。
- C++11 起可以范围遍历：

```cpp
for (auto i : M) {
    cout << i.first << ' ' << i.second << '\n';
}
```

### std::set

- 定义：`set<int> S;`
- 元素有序且去重。
- `S.count(x)`：判断是否存在；`S.insert(x)`：插入；`S.erase(x)`：删除。
- 上述操作平均 $O(\log n)$。
- 范围遍历：

```cpp
for (auto i : S) {
    cout << i << '\n';
}
```

### std::multiset

- 定义：`multiset<int> S;`
- 与 `set` 的区别是不去重。
- `S.count(x)` 返回 $x$ 的个数；最坏情况下 `count` 会退化到 $O(n)$。
- `S.erase(x)`：
  - 若 $x$ 是**迭代器**，只删除该迭代器指向的一个元素；
  - 若 $x$ 是**元素值**，删除所有等于 $x$ 的元素。
- 其它用法与 `set` 相同。

### 容器内的二分

`set` / `multiset` 支持 `S.lower_bound(x)` 和 `S.upper_bound(x)`，时间复杂度 $O(\log n)$，语义与 STL 的 `lower_bound` / `upper_bound` 一致。

### 容器嵌套

关联式容器可以嵌套，例如 `map<int, set<int>>`、`map<string, vector<int>>`。嵌套时要注意外层键的有序性和内层容器的操作复杂度。

## 核心公式 / 状态定义与转移方程

- `map<Key, Value>`：键值映射，键唯一、有序；`M[key]` 不存在时会插入默认值。
- `set<Key>`：集合，元素唯一、有序；`insert` / `erase` / `count` 都是 $O(\log n)$。
- `multiset<Key>`：多重集合，元素可重复；`erase(value)` 删除全部等于该值的元素，`erase(iterator)` 只删一个。
- `lower_bound(x)`：第一个 $\ge x$ 的位置；`upper_bound(x)`：第一个 $>x$ 的位置。
- 遍历顺序：`map` / `set` / `multiset` 都按键/元素升序；需要自定义顺序时传比较器。

## 逐行代码解析

### map 计数

```cpp
map<int, int> M;
for (int i = 1; i <= n; i++) {
    int x;
    cin >> x;
    M[x]++;
}
cout << M.count(3) << ' ' << M[3] << '\n';
```

- `M[x]++` 会在键不存在时插入 `{x, 0}` 再加一，所以可以直接计数。
- `M.count(3)` 只判断是否存在，不插入；`M[3]` 若不存在会插入，查询时要注意这个副作用。

### set 去重与查找

```cpp
set<int> S;
S.insert(3);
S.insert(3);
S.insert(5);
cout << S.size() << '\n';      // 2
cout << S.count(3) << '\n';    // 1
S.erase(3);
cout << S.count(3) << '\n';    // 0
```

- `set` 自动去重，重复 `insert` 不会增加元素。
- `S.count(x)` 返回 $0/1$；`S.erase(x)` 删除值为 $x$ 的元素。

### multiset 删除一个与删除全部

```cpp
multiset<int> S;
S.insert(2); S.insert(2); S.insert(3);

S.erase(S.find(2));   // 只删一个 2
cout << S.count(2) << '\n';  // 1

S.erase(2);           // 删除所有 2
cout << S.count(2) << '\n';  // 0
```

- `S.find(2)` 返回第一个等于 $2$ 的迭代器；`erase(iterator)` 只删这一个。
- `erase(2)` 传的是值，会删除所有等于 $2$ 的元素。

## 复杂度分析

- `map` / `set` / `multiset` 的插入、删除、查找平均 $O(\log n)$，最坏 $O(\log n)$（红黑树平衡）。
- 范围遍历 $O(n)$。
- `multiset::count(x)` 最坏 $O(n)$，因为要数完所有等于 $x$ 的元素；如果只需要判断存在性，用 `find(x)`。
- 空间 $O(n)$。

## 适用场景

- 需要按值快速查找、插入、删除，且元素有序。
- 需要维护“某个值出现了几次”的映射（`map`）。
- 需要去重并保持有序（`set`）。
- 需要允许重复且保持有序（`multiset`）。
- 需要前驱/后继、区间内第一个大于等于某值的元素（`lower_bound` / `upper_bound`）。
- 预处理可能出现的结果、为特定条件计数、判断条件是否出现过。

## 常见陷阱与注意事项

1. **`M[x]` 会插入**：查询 `map` 时若只想判断存在，用 `M.count(x)` 或 `M.find(x)`，不要用 `M[x]`，否则会悄悄插入 `{x, 0}`。
2. **`multiset.erase(value)` 删除全部**：只想删一个时用 `erase(find(value))`。
3. **`multiset.count` 可能很慢**：最坏 $O(n)$，只判断存在用 `find`。
4. **迭代器失效**：删除元素后，指向被删元素的迭代器失效；遍历中删除要先用 `it = S.erase(it)` 的写法。
5. **自定义比较器**：`set` / `map` 的键必须满足严格弱序；比较器写错会导致元素丢失或行为未定义。
6. **`unordered_map` 不是有序容器**：需要有序/前驱后继时不能用 `unordered_map`；它平均 $O(1)$，但可能被卡哈希。
7. **键的类型**：`map` 的键要可比较；结构体作键需要自定义比较器。
8. **范围遍历时修改容器**：遍历中插入/删除可能使迭代器失效，先收集操作或使用迭代器返回值。

## 对比与扩展

- **`map` vs `unordered_map`**：前者有序、$O(\log n)$、支持前驱后继；后者平均 $O(1)$、无序、可能被哈希冲突卡。
- **`set` vs `multiset`**：前者去重，后者允许重复；需要计数时 `multiset` 更方便，但 `count` 可能慢。
- **`set` vs 排序数组**：静态数据用排序数组 + `lower_bound` 更省空间；需要动态插入删除时用 `set`。
- **容器嵌套**：`map<int, set<int>>` 适合“一个键对应多个有序值”；注意外层键的 `[]` 会插入空容器。
