('Fohen', 'col-ds-stl-associative--fenfeng', '关联式容器（set / map） · Fohen', $AKB379$## 算法原理

关联式容器是 C++ 标准模板库（STL）中的一类容器，其内部通常以**红黑树**（一种自平衡二叉搜索树）实现，因此元素会**按键自动排序**，查找、插入、删除等操作的时间复杂度均为 $O(\log n)$。与之相对的是**无序关联式容器**（如 `unordered_set`、`unordered_map`），它们内部通过**哈希表**实现，元素不以任何特定顺序排列。

本节介绍两种最常用的关联式容器：

- **`set`**：元素集合，元素**不重复**（等价于数学意义上的集合），插入时会自动排序。若需要保留相同元素，可使用 **`multiset`**。
- **`map`**：键值对容器，每个键**唯一**，按键排序，用于建立「键 → 值」的映射。若需要允许多个元素拥有同一键，可使用 **`multimap`**。

两者共同的性质：

1. 内部通常通过红黑树实现。
2. 元素按键值自动排序（从小到大）。
3. 插入、删除、查找的时间复杂度均为 $O(\log n)$。

## 核心公式 / 状态定义与转移方程

关联式容器属于「语言工具」而非「算法」，没有状态转移方程；它的核心刻画是各类容器的复杂度差异。设 $n$ 为容器内元素个数：

- `set` / `map`：插入、删除、查找均为 $O(\log n)$。
- `multiset` / `multimap`：与 `set` / `map` 相同，但允许重复键。
- `unordered_set` / `unordered_map`：查找与插入均摊 $O(1)$，最坏 $O(n)$，且元素无序。

由于同一知识点覆盖多种容器、复杂度各不相同，frontmatter 中的复杂度记作「视具体实现」，实际使用时按具体容器取值。

## 逐行代码解析

本节给出 `set` 与 `map` 的关键用法片段，说明接口形态，不要求与任何完整程序一一对应。

### set 的声明与常用操作

```cpp
set<int> s;             // 有序、不重复的整数集合
multiset<int> ms;       // 有序、可重复的整数集合
unordered_set<int> us;  // 无序、不重复的整数集合（哈希实现，不支持二分查找）

// 插入与删除
s.insert(x);               // 若不存在等价元素，则将 x 插入容器
s.erase(x);                // 删除值为 x 的所有元素，返回删除元素的个数
s.erase(pos);              // 删除迭代器 pos 指向的元素，要求迭代器合法
s.erase(first, last);      // 删除迭代器 [first, last) 范围内的所有元素
s.clear();                 // 清空容器

// 查找
s.count(x);                // 返回容器内键为 x 的元素数量（set 中为 0 或 1）
s.find(x);                 // 存在键为 x 的元素时返回其迭代器，否则返回 s.end()
s.lower_bound(x);          // 返回指向首个不小于 x 的元素的迭代器，不存在则返回 s.end()
s.upper_bound(x);          // 返回指向首个大于 x 的元素的迭代器，不存在则返回 s.end()

// 容量
s.empty();                 // 返回容器是否为空
s.size();                  // 返回容器内元素个数
```

要点：

- `multiset` 与 `set` 用法相同；`unordered_set` 内部无序，不支持 `lower_bound` / `upper_bound` 这类二分查找操作。
- `insert` 有返回值，类型为 `pair<iterator, bool>`：迭代器指向被插入的元素（或原本就存在的等值元素），布尔值表示是否插入成功。由于 `set` 元素唯一，插入已存在的等值元素会失败并返回 `false`；`map` 的 `insert` 同理。

### map 的声明与常用操作

```cpp
map<string, int> mp;              // 键为 string、值为 int 的有序映射
multimap<string, int> mmp;        // 允许同一键对应多个值
unordered_map<string, int> ump;   // 无序映射（哈希实现）

// 插入与删除
mp["Alan"] = 100;                               // 下标访问：查询或插入键 "Alan" 并赋值为 100
mp.insert(pair<string, int>("Alan", 100));      // 插入一个 pair<Key, T> 类型的键值对
mp.erase(key);                                  // 删除键为 key 的所有元素，返回删除元素的数量
mp.erase(pos);                                  // 删除迭代器 pos 指向的元素，要求迭代器合法
mp.erase(first, last);                          // 删除迭代器 [first, last) 范围内的所有元素
mp.clear();                                     // 清空整个容器

// 查询
mp.count(x);                // 返回容器内键为 x 的元素数量
mp.find(x);                 // 存在键为 x 的元素时返回其迭代器，否则返回 end()
mp.lower_bound(x);          // 返回指向首个键不小于 x 的元素的迭代器
mp.upper_bound(x);          // 返回指向首个键大于 x 的元素的迭代器

// 容量
mp.empty();                 // 返回容器是否为空
mp.size();                  // 返回容器内元素个数
```

要点：

- 下标访问 `mp[key]` 在键不存在时会**自动插入**一个默认值；若只想查询而不插入，应改用 `mp.find(key)` 或 `mp.count(key)`。
- `count(x)` 返回键为 $x$ 的元素个数，复杂度为 $O(\log n)$ 加上匹配到的元素个数。
- `map` 的元素类型为 `pair<const key, type>`，其中键为常量不可修改，值可以修改。

## 复杂度分析

设 $n$ 为容器内元素个数，各类容器的复杂度对比如下：

| 操作 | `set` / `map` | `multiset` / `multimap` | `unordered_set` / `unordered_map` |
|---|---|---|---|
| 插入 | $O(\log n)$ | $O(\log n)$ | 均摊 $O(1)$，最坏 $O(n)$ |
| 删除 | $O(\log n)$ | $O(\log n)$ | 均摊 $O(1)$，最坏 $O(n)$ |
| 查找（`find`） | $O(\log n)$ | $O(\log n)$ | 均摊 $O(1)$，最坏 $O(n)$ |
| 二分查找（`lower_bound`） | $O(\log n)$ | $O(\log n)$ | 不支持 |
| 空间 | $O(n)$ | $O(n)$ | $O(n)$ |

- `set` / `map` 基于红黑树实现，查找、插入、删除均为 $O(\log n)$，且元素始终有序、支持二分查找。
- `unordered_*` 基于哈希表实现，均摊 $O(1)$，但在哈希冲突严重时可能退化到 $O(n)$，且元素无序、不支持二分查找。

由于不同容器的复杂度各不相同，frontmatter 中的复杂度记作「视具体实现」，实际使用时按上表选取对应的复杂度。

## 适用场景

- **`set`**：需要**去重**且**有序**的元素集合；需要频繁判断「某个值是否存在」、二分查找前驱/后继的场景。
- **`multiset`**：需要保留重复元素且保持有序的场景，如维护可重复的有序序列。
- **`map`**：需要建立「键 → 值」映射且键有序、唯一，如统计出现次数、离散化后的映射、字符串到编号的映射。
- **`multimap`**：同一键对应多个值的映射。
- **`unordered_set` / `unordered_map`**：只关心「是否存在 / 快速取值」而不需要有序，且元素数量较大时，哈希表通常比红黑树更快。

选择建议：默认使用 `set` / `map`（有序、行为可预测）；确认不需要有序且追求更小常数时，改用 `unordered_set` / `unordered_map`；需要保留重复元素时，改用 `multiset` / `multimap`。

## 常见陷阱与注意事项

1. **下标访问会意外插入**：`map` 的 `mp[key]` 在键不存在时会插入一个默认值。若只想判断键是否存在，务必使用 `mp.find(key)` 或 `mp.count(key)`，否则会向容器中误插入元素。
2. **`count` 与 `find` 的语义**：`count(x)` 返回匹配个数，在 `set` / `map` 中只有 $0$ 或 $1$；判断存在性用 `count` 更简洁，但若要取得元素本身，应使用 `find` 返回的迭代器。
3. **`erase` 的重载语义不同**：`s.erase(x)` 删除值为 $x$ 的**所有**元素并返回删除个数；`s.erase(pos)` 删除迭代器指向的单个元素。二者返回值与行为不同，混用容易出错。
4. **`unordered_*` 不支持二分查找**：`unordered_set` / `unordered_map` 内部无序，调用 `lower_bound` / `upper_bound` 会编译失败。
5. **哈希表的最坏复杂度**：`unordered_*` 均摊 $O(1)$，但构造数据可能使其退化为 $O(n)$；在对抗性较强的题目中，使用红黑树实现的 `set` / `map` 往往更稳妥。
6. **`map` 的键不可修改**：`map` 中元素的键类型是 `const key`，不能直接修改；需要改键时应先 `erase` 旧元素，再 `insert` 新键值对。
7. **迭代器失效**：删除元素会使指向被删元素的迭代器失效；遍历过程中如需删除元素，应先保存下一个迭代器再删除当前元素。

## 对比与扩展

- **`set` vs `unordered_set`**：`set` 基于红黑树，有序、支持二分查找，复杂度 $O(\log n)$；`unordered_set` 基于哈希表，无序、均摊 $O(1)$。需要有序或二分查找时用 `set`，只关心存在性且追求常数时用 `unordered_set`。
- **`set` vs `multiset`**：`set` 元素唯一，`multiset` 允许重复；需要「有序可重复集合」时用 `multiset`。
- **`map` vs `unordered_map`**：与 `set` 对比同理，`map` 有序，`unordered_map` 无序但均摊更快。
- **关联式容器 vs 序列式容器**：序列式容器（如 `vector`）按下标访问、元素按插入顺序排列；关联式容器按键自动排序、通过键查找，二者适用场景不同。
- **扩展方向**：`set` 的「有序 + 可二分查找」性质使其常被用于维护动态有序集合，进而衍生出如珂朵莉树（基于 `set` 维护区间）等数据结构；`map` 可用于离散化、统计、建立各类映射关系。无序关联式容器的底层是哈希表，其细节可参考哈希表相关知识。$AKB379$, '实用工具', array['数据结构', 'STL', '关联式容器', '集合', '映射'], 'col-hub-utility-stl', null, 'knowledge'),
('Xesir', 'col-ds-stl-associative--xesir', '关联式容器（set / map） · Xesir', $AKB380$## 算法原理

前面那些「序列式容器」只关心你排队排第几，而**关联式容器**关心的是「你叫什么」——它按**键**来存东西，内部通常用**红黑树**（一种自平衡二叉搜索树）实现，所以元素会**自动排好序**，查找、插入、删除都是 $O(\log n)$。

按「是否需要排序」还分两个阵营：

- **关联式容器**：底层红黑树，元素有序，`set` / `map` / `multiset` / `multimap` 都是这一挂。
- **无序关联式容器**（如 `unordered_set` / `unordered_map`）：底层是**哈希（hash）**，元素不以任何特定顺序排列，平均更快但退化时可能变差。

这里讲最常用的两个：`set`（集合）和 `map`（映射）。

## 核心公式 / 状态定义与转移方程

关联式容器不是动态规划结构，没有转移方程；它的复杂度来自红黑树的高度。含 $n$ 个结点的红黑树高度满足

$$
h = O(\log n)
$$

而查找 / 插入 / 删除都只沿着「根到叶子」的一条链走，代价正比于树高，所以三者都是 $O(\log n)$。至于无序关联式容器，键先经哈希函数映射到桶，理想情况下均摊 $O(1)$，但冲突多了会退化。

## 逐行代码解析

原笔记的「食用方法」照搬如下，分 `set` 和 `map` 两块，再补一条关于 `insert` 返回值的冷知识。都是关键片段，不要求拼成一个能 AC 的完整程序。

### 集合（set）

性质：内部通常通过红黑树实现；元素不重复（想要能重复的就上 **multiset**）；会自动排序插入的数字（不想排序就用**无序关联式容器 unordered_set**）；因为是红黑树，插入查询复杂度都是 $O(\log n)$。

声明、包含 `#include<set>`：`set<type> s;` / `multiset<type> s;` / `unordered_set<type> s;`。

```cpp
set<int> s;//multiset同，unordered_set无二分查询
//插入与删除操作
s.insert(x);		//当容器中没有等价元素的时候，将元素 x 插入到 set 中
s.erase(x);		//删除值为 x 的 所有 元素，返回删除元素的个数
s.erase(pos);		//删除迭代器为 pos 的元素，要求迭代器必须合法
s.erase(first,last);	//删除迭代器在[first,last)范围内的所有元素
s.clear() 		//清空 set
//迭代器 不想写了自己看oi.wiki去罢（
//查找操作
s.count(x);		//返回 set 内键为 x 的元素数量。
s.find(x);		//在 set 内存在键为 x 的元素时会返回该元素的迭代器，否则返回 s.end()
s.lower_bound(x);	//二分搜索，返回指向首个不小于给定键的元素的迭代器。如果不存在这样的元素，返回 s.end()
s.upper_bound(x);	//二分搜索，返回指向首个大于给定键的元素的迭代器。如果不存在这样的元素，返回 s.end()
//容量
s.empty();		//返回容器是否为空。
s.size();		//返回容器内元素个数。
```

- `insert` 若容器里已有等价元素则不插（set 去重的来源）；`erase(x)` 一次删掉**所有**值等于 $x$ 的元素（set 里最多一个）。
- `lower_bound` / `upper_bound` 是二分，能直接在容器上做，`unordered_set` 没有这俩。

### 关于 insert 的返回值（冷知识）

> insert 函数其实是==有返回值==的。返回值类型为 `pair<iterator, bool>`：`iterator` 指向所插入的元素（或者是指向等于所插入值、原本就在容器里的那个元素），`bool` 表示是否插入成功。由于 set 元素唯一，若容器已有等值元素则插入失败返回 false，否则成功返回 true；**map 的 insert 也是同理**。

### 映射（map）

性质：内部通常通过红黑树实现；是键值对容器，键是**唯一**的（`multimap` 允许一个键对应多个元素）；查找插入 $O(\log n)$。

声明、包含 `#include<map>`：`map<key,type>` / `multimap<key,type>` / `unordered_map<key,type>`。

```cpp
//插入与删除操作
//可以直接通过下标访问来进行查询或插入操作。例如 mp["Alan"]=100;
//通过向 map 中插入一个类型为 pair<Key, T> 的值可以达到插入元素的目的，例如 mp.insert(pair<string,int>("Alan",100));
erase(key)		//函数会删除键为 key 的 所有 元素。返回值为删除元素的数量
erase(pos)		//删除迭代器为 pos 的元素，要求迭代器必须合法
erase(first,last)	//删除迭代器在[first,last)范围内的所有元素
clear()			//函数会清空整个容器。

//查询操作
count(x)		//返回容器内键为 x 的元素数量。复杂度为O(log(size)+ans)（关于容器大小对数复杂度，加上匹配个数）。
find(x)			//若容器内存在键为 x 的元素，会返回该元素的迭代器；否则返回 end()。
lower_bound(x)		//返回指向首个不小于给定键的元素的迭代器。
upper_bound(x)		//返回指向首个大于给定键的元素的迭代器。若容器内所有元素均小于或等于给定键，返回 end()。
empty()			//返回容器是否为空。
size()			//返回容器内元素个数。
```

- `mp[key]` 既能查也能插：键不存在时会**默认构造**一个值并插进去，所以别拿 `[]` 随便探一个不存在的键。
- `mp.insert(pair<Key,T>(k, v))` 是显式插入，键已存在则不插（配合上一条冷知识，可用返回值判断是否插成功）。

## 复杂度分析

| 容器 | 查找 / 插入 / 删除 | 底层 | 是否有序 | 元素是否可重复 |
|---|---|---|---|---|
| `set` / `map` | $O(\log n)$ | 红黑树 | 有序 | 键唯一 |
| `multiset` / `multimap` | $O(\log n)$ | 红黑树 | 有序 | 键可重复 |
| `unordered_set` / `unordered_map` | 均摊 $O(1)$，最坏 $O(n)$ | 哈希表 | 无序 | 键唯一 |

空间复杂度为 $O(n)$。`map::count` 因为要数个数，复杂度是 $O(\log n + \text{ans})$（对数查找再加上匹配个数）。

## 适用场景

- **去重 + 有序**：`set` 收集后自动去重并排好序；`multiset` 允许重复。
- **动态维护有序序列**：要频繁插入 / 删除还要能二分查前驱后继，红黑树容器很趁手。
- **建映射 / 计数**：`map<string,int>` 做名字到编号的映射、`unordered_map` 做哈希计数。
- **不想自己写平衡树**时：需要 `lower_bound` / `upper_bound` / 前驱后继，又懒得手写 Treap / Splay，`set` 是现成答案。

## 常见陷阱与注意事项

1. `set` 里不能直接改元素（元素是键，改动会破坏有序性），要改就先 `erase` 再 `insert`。
2. `erase(x)` 删的是**所有**等值元素，删单个要传迭代器 `erase(s.find(x))`，且得先确认迭代器合法。
3. `unordered_set` / `unordered_map` **没有** `lower_bound` / `upper_bound`（无序，二分无意义）。
4. `map` 用 `mp[key]` 查不存在的键会默默插入一个默认值，容易让 `size()` 虚增；只想查就用 `find` / `count`。
5. `set` / `map` 的迭代器遍历天然有序（从小到大），要倒序可用 `rbegin` / `rend`。
6. `insert` 有返回值 `pair<iterator, bool>`，能靠 `bool` 判断是否插入成功（见上文冷知识）。

## 对比与扩展

| 容器 | 头文件 | 底层 | 排序 | 键重复 |
|---|---|---|---|---|
| `set` | `<set>` | 红黑树 | 自动升序 | 否 |
| `multiset` | `<set>` | 红黑树 | 自动升序 | 是 |
| `map` | `<map>` | 红黑树 | 按键升序 | 否 |
| `multimap` | `<map>` | 红黑树 | 按键升序 | 是 |
| `unordered_*` | `<unordered_set>` / `<unordered_map>` | 哈希表 | 无序 | 视具体而定 |

扩展方向：哈希实现的无序关联式容器（更快但无序、可能被卡）、自己手写平衡树以获得「第 $k$ 大 / 排名」等红黑树封装不了的操作，以及 `map` 的 `[]` 与 `insert` 在「查 / 插」语义上的区别。$AKB380$, '实用工具', array['数据结构', 'STL', '关联式容器', '集合', '映射'], 'col-hub-utility-stl', null, 'knowledge'),
('world-needs-sunday', 'col-ds-stl-list', 'std::list（双向链表）', $AKB381$## 算法原理

`std::list` 是 C++ 标准库里的**双向链表**：每个元素单独分配一个结点，结点里存「数据 + 前驱指针 + 后继指针」。因此任意位置的插入、删除都是 $O(1)$，但**不支持随机访问**，也没有 `operator[]`。

它在语法上是完整的，但在 OI 里几乎不用。原因不是「功能不够」，而是**理论优势换不来实际收益**：

1. **缓存局部性极差**。结点在堆上逐个分配，地址不连续。遍历时每一步都可能是一次缓存未命中，CPU 无法像遍历 `vector` 那样预取连续内存。
2. **每个结点都带额外开销**。除了数据本身，还要存两个指针和堆管理信息；每次插入是一次 `new`/`malloc`，删除是一次释放，单次常数远大于数组下标移动。
3. **有更好的替代**。真需要链表结构时（邻接表、可持久化结构、需要精细控制结点关系），标准做法是**数组模拟静态链表**：开 `e[N]`、`ne[N]`（必要时加 `pre[N]`），用下标代替指针。

一句话：`list` 的 $O(1)$ 插入在纸面上成立，但在卡常语境下，它带来的缓存与分配开销通常比省下的移动更贵。这也和「用数组模拟 `stack` / `queue`」是同一个逻辑——能被数组以更低常数替代的封装容器，自然退居次要位置。

## 语法速查

```cpp
#include <list>
list<int> lt;
```

| 类别 | 用法 | 说明 |
|---|---|---|
| 访问 | `lt.front()` / `lt.back()` | 首/尾元素，**没有 `lt[pos]`** |
| 插入 | `lt.push_front(x)` / `lt.push_back(x)` | 头/尾插入，$O(1)$ |
| 删除 | `lt.pop_front()` / `lt.pop_back()` | 删头/删尾，$O(1)$ |
| 插入 | `lt.insert(pos, x)` | 在迭代器 `pos` 前插入 |
| 删除 | `lt.erase(pos)` | 删除迭代器 `pos` 处的元素 |
| 清空 | `lt.clear()` | 清空所有元素 |
| 容量 | `lt.empty()` / `lt.size()` | 是否为空 / 元素个数 |
| 排序 | `lt.sort()` | 链表自带归并排序，**不能用 `std::sort`** |
| 合并 | `lt.merge(other)` | 合并两个有序链表 |
| 剪切 | `lt.splice(pos, other)` | 把 `other` 的结点剪到 `pos` 前，不拷贝 |
| 删除值 | `lt.remove(x)` | 删除所有值为 `x` 的元素 |
| 去重 | `lt.unique()` | 删除**相邻**的重复元素 |

注意 `size()` 在某些旧实现里是 $O(n)$ 的，需要频繁求长度时自己维护计数。

## 逐行代码解析

```cpp
lt.push_back(x);
lt.insert(lt.begin(), y);
lt.erase(lt.begin());
```

- `push_back(x)` 在尾部新分配一个结点，把原来的尾结点与它互连，$O(1)$。
- `insert(lt.begin(), y)` 在头结点前插入，同样是改几个指针，不移动任何已有元素——这正是 `list` 唯一真正的优势。
- `erase(lt.begin())` 释放头结点并把新的头结点前驱置空，$O(1)$。

```cpp
lt.sort();
lt.merge(other);
lt.splice(pos, other);
```

- `sort()` 是链表自带的归并排序，$O(n\log n)$，且不需要随机访问；用 `std::sort` 会编译失败。
- `merge(other)` 要求两链表都有序，直接把结点接起来，$O(n+m)$。
- `splice(pos, other)` 把 `other` 的整条链「剪」到 `pos` 之前，只改指针、不复制元素，$O(1)$——这是 `list` 里最有价值的一个操作。

```cpp
lt.unique();
lt.remove(x);
```

- `unique()` 只删**相邻**重复，想对所有重复生效必须先 `sort()`。
- `remove(x)` 会遍历整条链并删除所有等于 `x` 的结点，$O(n)$。

## 适用场景

**适合**：

- 需要在**已知迭代器位置**频繁插入/删除，且完全不需要随机访问；
- 需要 `splice` 这种「把一段结点整体搬到另一处、不复制」的语义（如把多个有序链表合并、LRU 缓存）。

**不适合**：

- 任何需要按下标访问的场景——`list` 没有 `operator[]`，只能从头走；
- 数据量大的遍历型操作，缓存不友好的代价会吃掉所有理论优势；
- OI 中绝大多数链表题（邻接表、静态链表、手写可持久化）——**用数组模拟更快也更可控**。

## 复杂度分析

| 操作 | 复杂度 |
|---|---|
| `push_front` / `push_back` | $O(1)$ |
| `insert` / `erase`（已有迭代器） | $O(1)$ |
| 按位置查找 | $O(n)$ |
| `sort` | $O(n\log n)$ |
| `splice` | $O(1)$ |
| `merge` | $O(n+m)$ |

空间上每个元素额外承担两个指针和堆块头部，$n$ 个 `int` 的实际占用远大于 `vector<int>` 的 $4n$ 字节。

## 常见陷阱与注意事项

- **不能用 `std::sort`**，只能 `lt.sort()`。
- **没有随机访问**，`lt[i]` 编译不过；取第 $k$ 个要 `advance` 从头走。
- **迭代器失效规则**：插入不会让其他迭代器失效，删除只让被删元素的迭代器失效——这点比 `vector` 宽松，但容易误判。
- **`unique()` 只处理相邻重复**，跨位置重复要先排序。
- **`size()` 可能是 $O(n)$**，频繁调用很伤。
- **内存碎片**：大量小结点反复分配释放，长期运行的程序容易碎片化。

## 对比与扩展

| 容器 | 随机访问 | 中间插入删除 | 缓存友好 | OI 常用度 |
|---|---|---|---|---|
| `vector` | $O(1)$ | $O(n)$ | 好 | 极高 |
| `deque` | $O(1)$ | 两端 $O(1)$ | 较好 | 高 |
| `list` | 不支持 | $O(1)$ | 差 | 极低 |
| 数组模拟静态链表 | 不支持 | $O(1)$ | 好 | 高 |

- **与静态链表对比**：静态链表用预分配的 `e[]`、`ne[]`、`pre[]` 存同样信息，没有动态分配、内存连续、行为可预测，是 OI 里真正会用的「链表」。
- **与 `deque` 对比**：如果只是需要两端快速增删，`deque` 的访问和缓存表现都更好，没有理由用 `list`。
- **什么时候仍会用 `list`**：需要 `splice` 语义、且结点数量不大、对常数不敏感时；或者纯粹为了让代码读起来接近「链表」的教科书描述。$AKB381$, '实用工具', array['list', '双向链表', 'STL', '常数优化', '缓存'], 'col-hub-utility-stl', null, 'knowledge'),
('Fohen', 'col-ds-stl-queue--fenfeng', '队列（queue） · Fohen', $AKB382$## 算法原理

队列（queue）是一种「先进先出」（FIFO，First In First Out）的线性数据结构：元素只能从队尾（rear）入队，只能从队首（front）出队。它只关心元素到达的先后顺序，不关心元素之间的大小关系，因此出队顺序与入队顺序完全一致。

C++ STL 提供三种常用的队列相关容器：

- `queue<T>`：普通队列，只能从队尾入队、队首出队，底层默认由 `deque` 实现，需要包含 `<queue>`（使用万能头 `<bits/stdc++.h>` 时可省略）。
- `deque<T>`：双端队列（double-ended queue），两端都可插入和删除，还支持随机访问，需要包含 `<deque>`。
- `priority_queue<T>`：优先队列，底层是堆，每次取出的都是当前最值元素，需要包含 `<queue>`。

普通队列的入队、出队示意：

```
入队:  队尾 <-- 新元素         出队:  队首 --> 弹出
       [ a1 | a2 | a3 | x ]          [ a2 | a3 | x ]
        队首           队尾           队首        队尾
```

## 核心公式 / 状态定义与转移方程

队列的核心约束是「先入先出」。设元素按 $a_1, a_2, \dots, a_n$ 的顺序依次入队，则出队顺序恒为 $a_1, a_2, \dots, a_n$，即第 $i$ 次出队得到的元素是 $a_i$。若队首在前，把队列记为 $[a_1, a_2, \dots, a_n]$，则一次出队操作满足：

$$
\text{pop}\big([a_1, a_2, \dots, a_n]\big) = (a_1,\ [a_2, a_3, \dots, a_n])
$$

即弹出队首 $a_1$，剩余部分成为新的队列。

若用循环数组（环形缓冲）手写队列，设容量为 $N$、队首下标为 $head$、队尾下标为 $tail$（$tail$ 指向队尾元素的下一个空位），则入队与出队只移动指针、不搬动元素：

$$
head = (head + 1) \bmod N, \qquad tail = (tail + 1) \bmod N
$$

此时队列中元素个数可表示为 $(tail - head + N) \bmod N$。

## 逐行代码解析

下面是三种队列容器的关键用法（伪代码 / 关键片段，非完整可运行程序）。

### 普通队列 `queue`

```cpp
#include<queue>            // 使用万能头<bits/stdc++.h>时可省略
queue<int> q;

q.push(x);   // 在队尾插入元素 x
q.front();   // 返回队首元素（不删除）
q.back();    // 返回队尾元素（不删除）
q.pop();     // 弹出队首元素（无返回值）
q.empty();   // 判断队列是否为空
q.size();    // 返回队列中元素的数量

queue<int> q1, q2;
q1 = q2;     // 将 q2 赋值给 q1
```

- `front()` / `back()` 只访问不删除；`pop()` 只删除不返回，取值需先调用 `front()`。
- `queue` 默认底层是 `deque`，因此 `push` / `pop` 都是常数时间。

### 双端队列 `deque`

```cpp
#include<deque>
deque<int> dq;

dq.front(); dq.back();      // 访问队首 / 队尾元素
dq.push_back(x);            // 在队尾插入
dq.pop_back();              // 弹出队尾元素
dq.push_front(x);           // 在队首插入
dq.pop_front();             // 弹出队首元素
dq.insert(it, x);           // 在迭代器 it 指向位置之前插入 x
dq.erase(it);               // 删除迭代器 it 指向的元素
dq.empty(); dq.size();      // 判空 / 元素个数
```

- `deque` 两端操作都是 $O(1)$，并支持 `operator[]` 随机访问。
- `insert` / `erase` 在中间位置操作是 $O(n)$。

### 优先队列 `priority_queue`

```cpp
#include<queue>
priority_queue<int> q;                           // 默认大根堆
priority_queue<int, vector<int>, greater<int>> q; // 小根堆

q.top();    // 返回堆顶元素（不删除）
q.pop();    // 弹出堆顶元素
q.push(x);  // 插入元素 x
q.empty();  // 判断是否为空
```

- 优先队列没有 `front()` / `back()`，只能用 `top()` 访问堆顶。
- 默认是大根堆；第三个模板参数填 `greater<int>` 使其成为小根堆。

## 复杂度分析

各容器的单次操作复杂度如下：

| 容器 | 访问 | 插入 / 删除 | 说明 |
|---|---|---|---|
| `queue` | `front` / `back` $O(1)$ | `push` / `pop` $O(1)$ | 底层为 `deque` |
| `deque` | 两端 $O(1)$，随机访问 $O(1)$ | 两端 $O(1)$，中间 `insert` / `erase` $O(n)$ | 双端操作 |
| `priority_queue` | `top` $O(1)$ | `push` / `pop` $O(\log n)$ | 底层为堆 |

空间复杂度均为 $O(n)$，其中 $n$ 为容器中元素个数。

## 适用场景

- 需要按到达先后顺序处理元素：BFS 广度优先搜索的扩展队列、树的层次遍历。
- 任务排队、缓冲区、生产者与消费者模型等「先进先出」语义。
- 需要在两端插入或删除：单调队列（滑动窗口最值）、01BFS（用 `deque`）。
- 需要动态维护最值：`priority_queue` 用于 Dijkstra、Prim、哈夫曼编码、求第 $k$ 大等。

## 常见陷阱与注意事项

1. `pop()` 无返回值：先 `front()` 取值，再 `pop()`，否则会丢失队首元素。
2. 访问前先判空：对空队列调用 `front()` / `pop()` 是未定义行为。
3. `queue` 没有迭代器，不能遍历或随机访问；需要遍历时应改用 `deque` 或手写数组队列。
4. `priority_queue` 只有 `top()`，没有 `front()` / `back()`：访问堆顶必须用 `top()`，误用 `front()` 会编译报错。
5. 小根堆写法 `priority_queue<int, vector<int>, greater<int>>` 在 C++11 之前，两个 `>` 之间必须加空格写成 `> >`；C++11 起可省略。
6. `queue` 没有 `clear()`：清空可写成 `q = queue<int>();` 或循环 `pop()`。
7. `queue` / `deque` / `priority_queue` 都支持整体赋值（如 `q1 = q2`），本质是拷贝容器内容。

## 对比与扩展

| 容器 | 头文件 | 底层结构 | 访问方式 | 核心特点 | 典型应用 |
|---|---|---|---|---|---|
| `queue` | `<queue>` | `deque` | `front` / `back` | 队尾入队、队首出队（FIFO） | BFS、层次遍历 |
| `deque` | `<deque>` | 分块双端数组 | 两端 + 随机访问 | 两端均可插删 | 单调队列、01BFS |
| `priority_queue` | `<queue>` | 二叉堆 | `top` | 每次取最值 | Dijkstra、top-k |
| `stack` | `<stack>` | `deque` | `top` | 后进先出（LIFO） | DFS、括号匹配 |

扩展方向：

- **单调队列**：用 `deque` 维护滑动窗口内的最值，是滑动窗口与动态规划问题的常用优化（见 `ds-monoqueue-1d`）。
- **01BFS**：边权为 $0$ 或 $1$ 的最短路，用 `deque` 的 `push_front` / `push_back` 代替普通队列。
- **循环队列**：手写数组 + 取模指针实现，避免动态扩容，适合空间受限的场合。
- **优先队列与堆**：`priority_queue` 是对二叉堆的封装；需要随机删除或修改元素时，应改用手写堆或平衡树。$AKB382$, '实用工具', array['数据结构', 'STL', '队列', '双端队列', '优先队列'], 'col-hub-utility-stl', null, 'knowledge'),
('Xesir', 'col-ds-stl-queue--xesir', '队列（queue） · Xesir', $AKB383$## 算法原理

队列，顾名思义，就是排队打饭的那条队——先到的先打饭，后来的老老实实排后面。这就是它的性质：**先进先出**（FIFO，first in first out）。元素只能从**队尾**进、从**队首**出，中间插队？想都别想。

STL 里跟「队」沾边的有三个容器，都写在 `#include<queue>` 里（用了万能头 `bits/stdc++.h` 就可以省略，下文同）：

- `queue<type>`：普通队列，只能队尾进、队首出，底层默认是 `deque`。
- `priority_queue<type>`：优先队列，跟堆差不多，每次拿出来的是当前最值。
- `deque<type>`：双端队列（double-ended queue），两头都能进出，得包含 `#include<deque>`。

它只关心你**什么时候来**，不关心你**是谁**，所以出队顺序和入队顺序一模一样。

## 核心公式 / 状态定义与转移方程

队列的核心约束就是「先入先出」。设元素依次按 $a_1, a_2, \dots, a_n$ 入队，那出队顺序也恒为 $a_1, a_2, \dots, a_n$，第 $i$ 个出队的永远是 $a_i$。把队首记在左、队尾记在右，队列写作 $[a_1, a_2, \dots, a_n]$，一次出队就是：

$$
\text{pop}\big([a_1, a_2, \dots, a_n]\big) = (a_1,\ [a_2, a_3, \dots, a_n])
$$

即弹出队首 $a_1$，剩下的接上。

如果是手写循环队列（用数组 + 取模指针，避免动态扩容），设容量为 $N$、队首下标 $head$、队尾下标 $tail$（$tail$ 指向队尾元素的下一个空位），那么入队出队只挪指针、不搬元素：

$$
head = (head + 1) \bmod N, \qquad tail = (tail + 1) \bmod N
$$

此时队列里的元素个数是 $(tail - head + N) \bmod N$。

## 逐行代码解析

下面按「食用方法」分三块，都是关键片段，不要求拼成一个能 AC 的完整程序。

### 普通队列

```cpp
queue<int> q;

// 元素访问
q.front();  // 返回队首元素（不删除）
q.back();   // 返回队尾元素（不删除）
// 修改
q.push(x);  // 在队尾插入元素 x
q.pop();    // 弹出队首元素（无返回值）
// 容量
q.empty();  // 队列是否为空
q.size();   // 返回队列中元素的数量

queue<int> q1, q2;
q1 = q2;    // 把 q2 的内容赋值给 q1
```

- `front()` / `back()` 只看不删；`pop()` 只删不返回，想取值得先 `front()`。
- `queue` 没有迭代器，别想着 `for` 一遍。

### 双端队列

```cpp
deque<int> q;

// 元素访问
q.front();      // 返回队首元素
q.back();       // 返回队尾元素
// 修改
q.push_back(x); // 在队尾插入元素
q.pop_back();   // 弹出队尾元素
q.push_front(x);// 在队首插入元素
q.pop_front();  // 弹出队首元素
q.insert(it, x);// 在迭代器 it 指向位置前插入 x
q.erase(it);    // 删除迭代器 it 指向的元素
// 容量
q.empty();      // 队列是否为空
q.size();       // 返回队列中元素的数量
```

- 两头进出都是 $O(1)$，还支持 `q[i]` 随机访问，这就是它比 `queue` 强的地方。

### 优先队列

```cpp
priority_queue<int, vector<int>, greater<int> > q;  // 小根堆
q.top();    // 返回堆顶（最小值）
q.pop();    // 弹出堆顶
q.push(x);  // 插入元素 x
q.empty();  // 是否为空

priority_queue<int> Q;  // 大根堆（默认）
Q.top();    // 返回堆顶（最大值）
Q.pop();
Q.push(x);
Q.empty();
```

- 优先队列**只有 `top()`，没有 `front()`**。原主页里大根堆那块写的是 `q.front()`，那是个手滑，编译直接报错，记得改成 `top()`。
- 默认是大根堆，第三个模板参数塞 `greater<int>` 就变（小根堆）。

## 复杂度分析

| 容器 | 访问 | 插入 / 删除 | 说明 |
|---|---|---|---|
| `queue` | `front` / `back` $O(1)$ | `push` / `pop` $O(1)$ | 底层 `deque` |
| `deque` | 两端 $O(1)$，随机访问 $O(1)$ | 两端 $O(1)$，中间 `insert` / `erase` $O(n)$ | 双端进出 |
| `priority_queue` | `top` $O(1)$ | `push` / `pop` $O(\log n)$ | 底层是堆 |

空间都是 $O(n)$，$n$ 是容器里元素个数。一句话：普通队列和双端队列随便用，优先队列每次操作带个 $\log$。

## 适用场景

- **按到达顺序处理**：BFS 的扩展队列、树的层序遍历。
- **两端插入删除**：单调队列（滑动窗口最值）、01BFS（用 `deque`）。
- **动态维护最值**：优先队列上 Dijkstra、Prim、哈夫曼、求第 $k$ 大。
- 排队、缓冲这种「先来先服务」的语义，用 `queue` 最贴切。

## 常见陷阱与注意事项

1. `pop()` 没有返回值：先 `front()` 取值再 `pop()`，否则队首元素直接丢。
2. 取元素前先 `empty()` 判空，对空队列 `front()` / `pop()` 是未定义行为。
3. `queue` 不能遍历、不能随机访问，要遍历请换 `deque` 或手写数组队列。
4. `priority_queue` 只有 `top()`，误写 `front()` 会编译报错（原主页就有这个坑）。
5. 小根堆写法 `priority_queue<int, vector<int>, greater<int> >`：C++11 之前两个 `>` 之间必须留空格写 `> >`，C++11 起可以省略。
6. `queue` 没有 `clear()`，清空得写 `q = queue<int>();` 或循环 `pop()`。

## 对比与扩展

| 容器 | 头文件 | 底层 | 访问方式 | 特点 | 典型应用 |
|---|---|---|---|---|---|
| `queue` | `<queue>` | `deque` | `front` / `back` | 队尾进队首出（FIFO） | BFS、层序遍历 |
| `deque` | `<deque>` | 分块双端数组 | 两端 + 随机访问 | 两端都能进出 | 单调队列、01BFS |
| `priority_queue` | `<queue>` | 二叉堆 | `top` | 每次拿最值 | Dijkstra、top-k |
| `stack` | `<stack>` | `deque` | `top` | 后进先出（LIFO） | DFS、括号匹配 |

扩展方向：单调队列（`ds-monoqueue-1d`）、01BFS、循环队列，还有和堆的对照——优先队列就是二叉堆的封装，想随机删除 / 改元素就得手写堆或上平衡树。$AKB383$, '实用工具', array['数据结构', 'STL', '队列', '双端队列', '优先队列'], 'col-hub-utility-stl', null, 'knowledge'),
('Fohen', 'col-ds-stl-stack--fenfeng', '栈（stack） · Fohen', $AKB384$## 算法原理

栈（stack）是一种**后进先出**（LIFO，Last In First Out）的线性数据结构：最后入栈的元素最先出栈。可以把栈想象成一摞盘子——每次只能从顶部放入或取出，无法直接操作中间或底部的元素。

在 C++ 中，标准库提供 `std::stack`（头文件 `<stack>`）。它并不是一个独立的容器，而是一个**容器适配器**：默认基于 `std::deque`（双端队列）实现，只对外暴露栈这一侧的接口，屏蔽了底层容器的细节。

栈只允许在**栈顶**这一个位置进行操作，因此接口非常简洁：

- `push(x)`：将元素 $x$ 压入栈顶
- `pop()`：弹出栈顶元素（不返回该元素）
- `top()`：返回栈顶元素的引用（不移除）
- `empty()`：判断栈是否为空
- `size()`：返回栈内元素个数

## 核心公式 / 状态定义与转移方程

设栈内元素自栈底到栈顶为序列 $S = (a_1, a_2, \ldots, a_n)$，其中 $a_1$ 为栈底、$a_n$ 为栈顶。三种基本操作的状态转移如下：

- 入栈：`push(x)` 后 $S = (a_1, \ldots, a_n, x)$，新栈顶为 $x$，长度变为 $n+1$
- 出栈：`pop()` 后 $S = (a_1, \ldots, a_{n-1})$，移除原栈顶 $a_n$，长度变为 $n-1$（要求 $n \ge 1$）
- 取栈顶：$\text{top}(S) = a_n$，栈状态不变

核心不变量是**后进先出**：元素出栈的顺序与入栈顺序恰好相反。若依次入栈 $x_1, x_2, \ldots, x_n$，则第一个出栈的元素必为 $x_n$，最后一个出栈的必为 $x_1$。

## 逐行代码解析

以 `std::stack` 的基本用法为例：

```cpp
#include <stack>       // 引入栈
using namespace std;

stack<int> st;         // 声明一个存放 int 的栈，默认基于 deque

st.push(1);            // 入栈 1，栈: [1]
st.push(2);            // 入栈 2，栈: [1, 2]，2 为栈顶
int x = st.top();      // 取栈顶，x = 2，栈不变
st.pop();              // 弹出栈顶，栈: [1]
bool b = st.empty();   // 判空，b = false
int n = st.size();     // 元素个数，n = 1
```

- `stack<int> st;` 声明时模板参数是元素类型；第二个模板参数可指定底层容器（默认 `std::deque`），如 `stack<int, vector<int>>`
- `top()` 只返回栈顶元素的**引用**，不删除；想要移除必须再调用 `pop()`
- `pop()` 无返回值，这是新手最容易写错的地方：不能写 `int x = st.pop();`
- 对空栈调用 `top()` 或 `pop()` 是未定义行为，操作前应先 `empty()` 判空

## 复杂度分析

`std::stack` 的所有成员操作都直接转调底层容器，均为常数时间：

| 操作 | 时间复杂度 | 说明 |
|---|---|---|
| `push(x)` | $O(1)$ | 在栈顶插入一个元素 |
| `pop()` | $O(1)$ | 删除栈顶元素 |
| `top()` | $O(1)$ | 返回栈顶引用 |
| `empty()` / `size()` | $O(1)$ | 查询状态与大小 |

空间复杂度取决于底层容器与元素数量，为 $O(n)$（$n$ 为栈内元素个数）。由于底层默认是 `deque`，`push` 可能触发动态扩容，但均摊后仍是 $O(1)$。

## 适用场景

- **括号匹配**：遇到左括号入栈、右括号与栈顶配对后出栈，遍历结束后栈为空即匹配成功
- **表达式求值与后缀表达式**：操作数入栈，运算符弹出栈顶若干操作数计算后把结果压回
- **模拟递归（DFS）**：把递归调用栈显式化，可避免递归层数过深导致的栈溢出
- **撤销 / 回退**：编辑器撤销、浏览器后退等历史记录，天然是后进先出
- **单调栈**：以栈为底层并维护栈内元素单调性，解决「下一个更大/更小元素」等问题
- **图的非递归遍历**：用显式栈替代系统调用栈做深度优先遍历

## 常见陷阱与注意事项

1. **`pop()` 不返回元素**：必须先 `top()` 取值、再 `pop()` 移除，否则会丢失数据
2. **对空栈操作是未定义行为**：调用 `top()` 或 `pop()` 前务必 `empty()` 判空
3. **栈不能随机访问**：`std::stack` 不提供 `operator[]`、迭代器与随机访问，只能操作栈顶；需要随机访问时应改用 `vector` 或 `deque`
4. **递归深度过大会爆栈**：系统调用栈空间有限，深层递归（如 $n$ 达 $10^5$ 以上）可能栈溢出，可改用显式 `std::stack` 模拟递归或增大栈空间
5. **底层容器默认是 `deque`**：若对内存布局有特殊要求，可指定 `std::vector` 作为底层容器，但要理解两者的分配差异

## 对比与扩展

| 对比维度 | `std::stack` | `std::queue` | `std::vector` | 单调栈 |
|---|---|---|---|---|
| 访问规则 | 后进先出（LIFO） | 先进先出（FIFO） | 随机访问 | 后进先出 + 单调性 |
| 插入 / 删除位置 | 栈顶 | 队尾入 / 队头出 | 任意位置 | 栈顶 |
| 随机访问 | 否 | 否 | 是 | 否 |
| 典型用途 | 括号匹配、递归模拟 | 层序遍历、BFS | 顺序存储 | 下一个更大元素 |

**扩展**：

- **手写数组栈**：用数组 `stk[]` 加指针 `top` 模拟栈，常数更小、空间可控，适合竞赛中频繁操作
- **双栈实现队列**：用两个栈 `in`、`out` 分别负责入队和出队，可 $O(1)$ 均摊实现队列
- **单调栈**：在普通栈基础上维护单调性，解决区间最值相关的一类问题
- **栈与递归**：函数调用本身依赖系统栈，理解栈有助于调试递归与爆栈问题$AKB384$, '实用工具', array['数据结构', 'STL', '栈', '后进先出', '容器'], 'col-hub-utility-stl', null, 'knowledge'),
('Xesir', 'col-ds-stl-stack--xesir', '栈（stack） · Xesir', $AKB385$## 算法原理

栈，想象成一摞盘子——你只能往最上面摞，也只能从最上面拿。想抽中间那张？先把上面的搬空再说。这就是它的性质：**后进先出**（LIFO，last in first out）。元素只能从**栈顶**进、也从**栈顶**出，插队是不可能插队的。

它写在 `#include<stack>` 里（用了万能头 `bits/stdc++.h` 就可以省了，下文同），一行声明搞定：

```
stack<type> st;
```

`type` 是元素类型，下面「食用方法」里统一拿 `int` 演示。

栈跟队列最大的不同就是**开口只在一头**：队列是两头各开一个口（先进先出），栈是一头堵死、只留别人开的那一头进进出出。

## 核心公式 / 状态定义与转移方程

栈的核心约束是「后进先出」。设元素依次按 $a_1, a_2, \dots, a_n$ 入栈，那出栈顺序刚好是反过来的 $a_n, a_{n-1}, \dots, a_1$。把栈底记在左、栈顶记在右，栈写作 $[a_1, a_2, \dots, a_n]$，一次出栈（pop）就是：

$$
\text{pop}\big([a_1, a_2, \dots, a_n]\big) = (a_n,\ [a_1, a_2, \dots, a_{n-1}])
$$

也就是弹出栈顶 $a_n$，剩下的接上；而入栈（push）则永远往最右边追加。

顺带一提，栈顶指针（用数组手写时）就跟着元素个数走：入栈 $top \mathrel{+}= 1$、出栈 $top \mathrel{-}= 1$，元素个数即 $top$（若从下标 $0$ 开始存）。

## 逐行代码解析

原笔记里「食用方法」就一段，下面照搬并补几句要点。这是关键片段，不要求拼成一个能 AC 的完整程序。

### 基本操作

```cpp
stack<int> st;

st.top();    //这里是返回 栈顶 元素
st.pop();    //这里是弹出 栈顶 元素
st.push();   //元素入栈
st.empty();
```

- `top()` 只看不删，返回栈顶元素（**不删除**）；`pop()` 只删不返回，想取值得先 `top()` 再 `pop()`。
- `push()` 是入栈，元素被压到栈顶。
- `empty()` 判断栈是否为空；取元素（`top` / `pop`）之前最好先判一下空。

## 复杂度分析

单次操作都是常数级别：

| 操作 | 时间复杂度 | 说明 |
|---|---|---|
| `top` | $O(1)$ | 直接看栈顶 |
| `push` | $O(1)$ | 压入栈顶 |
| `pop` | $O(1)$ | 弹出栈顶 |
| `empty` | $O(1)$ | 判空 |

空间复杂度为 $O(n)$，$n$ 是栈里元素个数。一句话：栈的操作全是 $O(1)$，比隔壁带 $\log$ 的堆省心多了。

## 适用场景

- **后进先出**语义的场景：括号匹配、表达式求值、函数调用栈。
- **DFS / 深搜**的显式栈、递归转迭代时手动压栈。
- **回溯**：走到死胡同退回来，天然是栈的形态（撤销/上一状态）。
- **单调栈**：求「下一个更大元素」「直方图最大矩形」这类题。

## 常见陷阱与注意事项

1. `pop()` 没有返回值：先 `top()` 取值再 `pop()`，否则栈顶元素直接丢。
2. 取元素前先 `empty()` 判空，对空栈 `top()` / `pop()` 是未定义行为。
3. `stack` 没有迭代器，不能遍历、不能随机访问，想遍历请换手写数组栈或 `vector`。
4. `stack` 没有 `clear()`，清空得写 `st = stack<int>();` 或循环 `pop()`。
5. 默认底层是 `deque`，也可以指定 `vector` / `list` 作为底层容器。

## 对比与扩展

| 容器 | 头文件 | 底层 | 访问/进出 | 特点 | 典型应用 |
|---|---|---|---|---|---|
| `stack` | `<stack>` | `deque` | `top` | 后进先出（LIFO），只在一头进出 | DFS、括号匹配、单调栈 |
| `queue` | `<queue>` | `deque` | `front` / `back` | 先进先出（FIFO），一端进一端出 | BFS、层序遍历 |
| `deque` | `<deque>` | 分块双端数组 | 两端 + 随机访问 | 两头都能进出 | 单调队列、01BFS |

扩展方向：单调栈（每个元素进出各一次，求左右第一个更大/更小元素）、用栈把递归改写成非递归、括号匹配与表达式求值。栈和队列经常同台出现——BFS 用队列、DFS 用栈，是搜索的两大基础。$AKB385$, '实用工具', array['数据结构', 'STL', '栈', '后进先出'], 'col-hub-utility-stl', null, 'knowledge'),
('Fohen', 'col-ds-stl-tips--fenfeng', 'STL 小妙招 · Fohen', $AKB386$## 算法原理

STL（Standard Template Library，标准模板库）的「小妙招」，本质是**利用容器的内部实现细节与成员函数的返回值**，写出更短、更快、更不易出错的代码。核心是三条认知：

1. **容器内部结构决定复杂度**：`vector` 是连续内存的动态数组（随机访问 $O(1)$、末尾插入均摊 $O(1)$）；`set` / `map` 内部是红黑树（查找、插入、删除均为 $O(\log n)$ 且元素有序）；`unordered_set` / `unordered_map` 内部是哈希表（平均 $O(1)$、元素无序）。
2. **接口返回值是「免费的信息」**：许多成员函数（如 `set::insert`、`map::insert`）其实有返回值，善用它们可以省掉一次额外的查找。
3. **「均摊」不等于「每次」**：`vector` 的 `push_back` 均摊 $O(1)$，但单次扩容时是 $O(n)$；理解扩容机制，才能在需要稳定性能时用 `reserve` 提前避免。

掌握这些「小妙招」不需要死背 API，而是**把容器的内部模型想清楚**：数据存在哪、插入删除会动到哪、查找靠什么。

## 核心公式 / 状态定义与转移方程

> 本节是「语言/工具类」知识点，没有状态转移方程，取而代之的是几条最常用的「口诀/事实」，是理解并套用下列妙招的关键。

**关键事实（口诀）：**

- `vector` 扩容：容量不足时按约 $2$ 倍增长，因此 `push_back` 均摊 $O(1)$，单次最坏 $O(n)$。
- `set` / `map` 的 `insert` 返回 `pair<iterator, bool>`：`second == true` 表示插入成功（原容器中没有等值元素），`false` 表示已存在、插入失败。
- 有序容器（`set` / `map`）的查找、插入、删除为 $O(\log n)$；无序容器（`unordered_*`）平均 $O(1)$、最坏 $O(n)$。

**常用复杂度速查（标准库典型实现）：**

| 操作 | `vector` | `set` / `map` | `unordered_set` / `unordered_map` |
|---|---|---|---|
| 随机访问 / 按下标 | $O(1)$ | 不支持 | 不支持 |
| 查找 `find` / `count` | $O(n)$ | $O(\log n)$ | 平均 $O(1)$ |
| 插入 / 删除 | 末尾均摊 $O(1)$ | $O(\log n)$ | 平均 $O(1)$ |
| 是否有序 | 保持插入顺序 | 有序 | 无序 |

## 逐行代码解析

> 下面均为「小妙招」的关键用法片段，用于表达技巧本身；正式使用请按需补充头文件与具体类型。

```cpp
// 妙招 1：vector 提前 reserve，避免反复扩容带来的整块拷贝
vector<int> v;
v.reserve(1000000);          // 预分配 100 万个元素的容量，之后插入不再扩容
for (int i = 0; i < 1000000; ++i)
    v.push_back(i);          // 均摊 O(1)，全程只发生一次内存分配

// 妙招 2：用一个空 vector 交换，立即回收多余容量
vector<int>().swap(v);       // 传统写法：交换空 vector，立刻释放容量
// v.shrink_to_fit();        // C++11 起可用，语义更直白

// 妙招 3：set/map 的 insert 返回值 —— 判断是否真的插入了
set<int> s;
auto res = s.insert(5);      // res.first 是指向元素 5 的迭代器
if (res.second) {            // res.second == true 表示插入成功
    // 之前没有 5，已插入
} else {
    // 之前已有 5，插入失败，res.first 指向原有的 5
}

// 妙招 4：判断键是否存在，用 find 而不是 count
if (s.find(x) != s.end()) { /* 存在 */ }
// 对 multiset/multimap，find 只找一个，count 却要数完全部等价元素，故 find 更快

// 妙招 5：有序容器用成员函数 lower_bound/upper_bound，比全局函数更快
auto it = s.lower_bound(x);  // 首个 >= x 的元素，利用红黑树结构 O(log n)

// 妙招 6：优先队列实现小根堆 / 自定义比较
priority_queue<int, vector<int>, greater<int>> q;   // 小根堆
```

- 妙招 1、2：`vector` 扩容要把旧元素整体搬到新内存，元素多或元素是自定义类时开销大；`reserve` 一次到位、`shrink_to_fit` 回收冗余。
- 妙招 3：`insert` 的返回值把「查找 + 插入」合并成一次操作，避免先 `find` 再 `insert` 的两遍遍历。
- 妙招 4：`count` 的语义是「数有几个等价元素」，对 `multiset` 可能退化为 $O(n)$；判断「是否存在」一律用 `find`。
- 妙招 5：`std::lower_bound` 依赖随机访问迭代器，对 `set` / `map` 反而要线性遍历；成员函数版本利用内部结构做到 $O(\log n)$。
- 妙招 6：`greater<int>` 是标准库比较器，注意写全第二个模板参数 `vector<int>`，否则无法变成小根堆。

## 复杂度分析

STL 各容器的复杂度由「标准库典型实现」决定，此处给出常见值（不同实现可能略有差异，故整体标注「视具体实现」）：

- `vector`：随机访问、末尾 `push_back` / `pop_back` 均摊 $O(1)$；中间插入 / 删除 $O(n)$；`reserve` 提前分配后，批量插入可稳定 $O(1)$。
- `set` / `map`：基于红黑树，查找、插入、删除均为 $O(\log n)$，且保持有序。
- `multiset` / `multimap`：同 `set` / `map`，但 `count` 为 $O(\log n + k)$（$k$ 为等价元素个数），`find` 仍为 $O(\log n)$。
- `unordered_set` / `unordered_map`：哈希表，查找 / 插入 / 删除平均 $O(1)$，最坏 $O(n)$（哈希冲突严重时）。
- `priority_queue`：`push` / `pop` 为 $O(\log n)$，`top` 为 $O(1)$。

记忆重点：**「有序」与「$O(\log n)$」相伴（红黑树），「无序」与「平均 $O(1)$」相伴（哈希）**；判断存在用 `find`，需要数个数才用 `count`。

## 适用场景

- **`vector`**：需要随机访问、尾部增删、内存紧密排列的场景（如邻接表、DP 滚动数组、结果缓存）；配合 `reserve` 用于已知规模的批量插入。
- **`set` / `map`**：需要「有序 + 去重」或「按 key 有序遍历」的场景（如需要 `lower_bound` 查询、排名、前驱后继）。
- **`unordered_set` / `unordered_map`**：只关心「是否存在 / 快速映射」、不关心顺序，且 key 可哈希的场景；平均更快，但最坏有退化风险。
- **`priority_queue`**：需要动态维护最值（堆、Dijkstra、贪心）的场景。
- **`insert` 返回值、`find` / `count` 选择、成员函数二分**：任何用到关联容器的代码里都可以套用，属于「顺手就能变快 / 变稳」的通用技巧。

## 常见陷阱与注意事项

1. **忽略 `insert` 返回值**：`set` / `map` 的 `insert` 不会覆盖已有元素，若想「插入或更新」，应先判断 `res.second`，否则可能误以为更新成功。
2. **用 `count` 判断存在**：`multiset` / `multimap` 中 `count` 会数遍所有等价元素，最坏 $O(n)$；判断存在应使用 `find`。
3. **对有序容器用全局二分**：`std::lower_bound` / `std::upper_bound` 依赖随机访问，对 `set` / `map` 会退化为 $O(n)$；应调用容器的成员函数版本。
4. **`unordered_*` 的最坏退化**：哈希冲突严重（或遭遇刻意的碰撞构造）时单次操作退化为 $O(n)$；需要严格复杂度保证时选 `map` / `set`。
5. **`vector` 扩容与迭代器失效**：`push_back` 触发扩容会使所有迭代器失效；`erase` / `insert` 会使其后的迭代器失效，遍历中删除元素应使用返回的迭代器 `it = v.erase(it)`。
6. **`reserve` 不会改变 `size`**：`reserve(n)` 只增加容量、不增加元素个数，只有 `i < size()` 的下标才安全；误把 `reserve` 当 `resize` 会越界。
7. **容器语义混淆**：`unordered_*` 无序遍历、`set` 去重而 `multiset` 不去重，选错容器会引入隐蔽 bug。

## 对比与扩展

| 容器 | 内部结构 | 查找 | 插入 / 删除 | 有序 | 允许重复 |
|---|---|---|---|---|---|
| `vector` | 动态数组 | $O(n)$ | 尾部均摊 $O(1)$ | 插入顺序 | 是 |
| `set` | 红黑树 | $O(\log n)$ | $O(\log n)$ | 是 | 否 |
| `multiset` | 红黑树 | $O(\log n)$ | $O(\log n)$ | 是 | 是 |
| `unordered_set` | 哈希表 | 平均 $O(1)$ | 平均 $O(1)$ | 否 | 否 |

扩展方向：

- **自定义 key 的比较与哈希**：为自定义结构体写 `operator<`（用于 `set` / `map`），或特化 `hash` 并写 `operator==`（用于 `unordered_*`）。
- **`multiset` / `multimap`**：需要「有序且可重复」时使用，配合 `equal_range` 一次拿到所有等价元素。
- **平板电视（`__gnu_pbds`）**：提供 `tree`、`hash_map` 等扩展容器，支持 `order_of_key`、`find_by_order` 等按排名查询。
- **结构化绑定**：遍历 `map` 时用 `for (auto &[k, v] : mp)`（C++17），可读性更好。$AKB386$, '实用工具', array['数据结构', 'STL', 'vector', 'set', 'map'], 'col-hub-utility-stl', null, 'knowledge'),
('Fohen', 'col-ds-stl-vector--fenfeng', '动态数组（vector） · Fohen', $AKB387$## 算法原理

`vector` 是 C++ 标准模板库（STL）中最常用的**序列式容器**（sequence container），其底层是一片**连续内存**，元素在内存中依次相邻排列。连续存储带来两个直接好处：

1. **随机访问 $O(1)$**：`v[i]` 的地址可由首地址加偏移直接算出，无需像链表那样从头遍历。
2. **缓存友好**：遍历时按内存顺序访问，命中 CPU 缓存，常数很小。

vector 的核心机制是**动态扩容**。声明时通常只分配少量（甚至不分配）内存，当 `push_back` 使元素个数达到当前容量上限时，就重新分配一块更大的连续内存，把旧元素拷贝（或移动）过去，再释放旧内存。为了保证均摊效率，新容量一般按常数倍（约 2 倍，视实现而定）增长。

需要区分两个容易混淆的量：

- **`size()`（长度）**：当前实际存放的元素个数，记为 $n$。
- **`capacity()`（容量）**：当前已分配内存最多能容纳的元素个数，恒有 `size()` $\le$ `capacity()`。

此外，vector 重载了比较运算符（两容器按字典序逐元素比较）和赋值运算符（拷贝赋值、移动赋值），因此可以直接用 `==`、`<`、`=` 等对整个容器进行操作。

## 核心公式 / 状态定义与转移方程

vector 不是动态规划类结构，没有状态转移方程；它的核心刻画是「容量增长」与「均摊代价」之间的关系。

设扩容因子为常数 $c > 1$（常见 $c = 2$），从空 vector 开始连续执行 $n$ 次 `push_back`。第 $k$ 次扩容时容量从 $c^{k}$ 增长到 $c^{k+1}$，需要拷贝 $c^{k}$ 个旧元素。整个过程中因扩容产生的总拷贝次数是一个几何级数：

$$
T(n) = \sum_{k=0}^{\lfloor \log_c n \rfloor} c^{k} = \frac{c^{\lfloor \log_c n \rfloor + 1} - 1}{c - 1} \le \frac{c}{c - 1} \cdot n = O(n)
$$

把总代价 $O(n)$ 平摊到 $n$ 次 `push_back` 上，得到**均摊每次 $O(1)$**；其中恰好触发扩容的那一次操作，最坏代价为 $O(n)$。

随机访问按下标直接计算地址（`data()` 返回内部连续内存首元素的指针）：

$$
\text{address}(v[i]) = \text{data}() + i
$$

因此按下标访问是 $O(1)$。

## 逐行代码解析

本节按「声明与创建」「元素访问」「长度与容量」「元素增删与修改」四组给出关键用法，均为伪代码片段，不要求与任何完整程序一一对应。

### 声明与创建

```cpp
#include <vector>
using namespace std;

vector<int> v0;                                 // 1. 空 vector，常数复杂度
v0.reserve(3);                                  // 2. 预留 3 个元素的空间，之后插入前 3 个元素为常数复杂度
vector<int> v1(3);                              // 3. 长度 3，元素默认值 0，线性复杂度
vector<int> v2(3, 2);                           // 4. 长度 3，元素默认值 2，线性复杂度
vector<int> v4(v2);                             // 5. 拷贝构造，内容与 v2 相同，线性复杂度
vector<int> v5(v4.begin() + 1, v4.begin() + 3); // 6. 拷贝区间 [v4[1], v4[2])，线性复杂度
vector<int> v6(std::move(v2));                  // 7. 移动构造，不发生拷贝，常数复杂度（需 C++11）
```

- `reserve(n)` 只改容量不改长度，是提前避免多次扩容拷贝的关键。
- 构造函数 `(n)`、`(n, val)`、拷贝构造、区间构造都是线性复杂度（需要逐个构造元素）。
- 移动构造 / 移动赋值把旧容器的内存指针直接“接管”过来，旧容器被置空，因此是常数复杂度。

### 元素访问

```cpp
v.at(pos);   // 返回下标 pos 的引用；越界抛出 std::out_of_range 异常
v[pos];      // 返回下标 pos 的引用；不检查越界（越界是未定义行为）
v.front();   // 返回首元素的引用
v.back();    // 返回末尾元素的引用
v.data();    // 返回内部连续内存首元素的指针
```

- `at()` 与 `operator[]` 的区别在于是否做边界检查：`at()` 越界会抛出异常，`operator[]` 越界是未定义行为但常数更小。

### 长度与容量

```cpp
v.empty();          // 是否为空，等价于 v.begin() == v.end()
v.size();           // 元素个数，即 std::distance(v.begin(), v.end())
v.resize(n);        // 把长度改为 n：n 变大时补默认值，n 变小时删除末尾元素
v.max_size();       // 容器理论上可容纳的最大元素数
v.reserve(n);       // 预留容量，避免反复分配与拷贝
v.capacity();       // 当前容量（已分配空间可容纳的元素数）
v.shrink_to_fit();  // 把容量收缩到与长度一致，释放多余内存
```

### 元素增删与修改

```cpp
v.clear();       // 清空所有元素（长度归 0，容量不变）
v.insert(it, x); // 在迭代器 it 处插入 x；复杂度与 it 到末尾的距离成线性
v.erase(it);     // 删除迭代器 it 处的元素，返回下一个有效迭代器
v.push_back(x);  // 在末尾插入 x；均摊 O(1)，最坏 O(n)（触发扩容）
v.pop_back();    // 删除末尾元素；O(1)
v.swap(w);       // 与另一个 vector 交换全部内容；O(1)
```

- `insert` / `erase` 在中间操作时，需要把之后的所有元素整体后移或前移，所以是线性复杂度，这是连续内存容器的固有代价。
- `swap` 只交换两个容器内部指向内存的指针，不搬动元素，因此是常数复杂度。

## 复杂度分析

| 操作 | 时间复杂度 | 说明 |
|---|---|---|
| 随机访问 `v[i]` / `at` / `front` / `back` / `data` | $O(1)$ | 连续内存，按地址直接计算 |
| `push_back`（末尾插入） | 均摊 $O(1)$，最坏 $O(n)$ | 扩容时最坏线性，均摊常数 |
| `pop_back`（末尾删除） | $O(1)$ | 只减少长度 |
| `insert` / `erase`（中间操作） | $O(n)$ | 与操作位置到末尾的距离成正比 |
| `resize` / `reserve` / `shrink_to_fit` | $O(n)$ | 需要重建或搬移元素 |
| `clear` | $O(n)$ | 逐个析构元素 |
| `swap` | $O(1)$ | 交换内部指针 |

空间复杂度为 $O(n)$，实际占用由 `capacity()` 决定，通常介于 $n$ 与 $2n$ 之间（视扩容策略而定）。

## 适用场景

**适用**：
- 需要**连续内存**和 **$O(1)$ 随机访问**的场景，如普通数组的「动态长度替代品」。
- 元素只（或几乎只）在**末尾**增删，如记录答案、按顺序收集结果。
- 需要整体遍历、排序、二分查找：配合 `sort`、`lower_bound`、`upper_bound` 使用。
- 需要存储大量数据但长度事先未知、或长度会动态变化的场景。

**不适用**：
- 频繁在**头部或中间**插入 / 删除：每次都要 $O(n)$ 搬移，应改用 `deque` 或 `list`。
- 数据规模巨大且上限已知：静态数组常数更小、无扩容开销。
- 需要元素地址长期稳定（例如已取得元素指针后继续扩容）：扩容会整体搬移，地址失效。

## 常见陷阱与注意事项

1. **`size()` 与 `capacity()` 不要混淆**
   - `size()` 是元素个数，`capacity()` 是已分配容量，两者通常不同。
   - 循环 `for (int i = 0; i < v.size(); i++)` 用 `size`；判断“还能不能装”用 `capacity`。

2. **迭代器 / 指针 / 引用失效**
   - 触发扩容、或发生 `insert` / `erase` / `resize` / `clear` 时，之前保存的迭代器、指针、引用可能失效。
   - 尤其不要写 `auto *p = &v[0]; v.push_back(x);` 后继续使用 `p`——扩容后 `p` 已悬空。

3. **`at()` 与 `operator[]` 的边界检查差异**
   - `at(pos)` 越界抛出 `std::out_of_range`，便于定位问题；`operator[]` 越界是未定义行为，可能读到垃圾值甚至崩溃。
   - 竞赛中为追求常数常用 `operator[]`，但必须自行保证下标合法。

4. **`reserve()` 与 `resize()` 的区别**
   - `reserve(n)` 只把容量调到至少 $n$，**不改变长度**，此时 `v[i]` 仍不可直接访问。
   - `resize(n)` 改变长度：变长时新元素用默认值（或指定值）填充。

5. **`clear()` 不释放内存**
   - `clear()` 后 `size()` 归 0，但 `capacity()` 不变，内存仍被占用。
   - 若要真正释放，用 `vector<int>().swap(v)` 或 `shrink_to_fit()`。

6. **`size()` 返回无符号类型**
   - `v.size()` 的类型是 `size_t`（无符号），`v.size() - 1` 在空容器时会下溢成巨大的无符号数。
   - 与有符号整数比较、相减时要小心，倒序循环建议写成 `for (int i = (int)v.size() - 1; i >= 0; i--)`。

7. **`vector<bool>` 是特化容器**
   - `vector<bool>` 按位压缩存储，元素不是真正的 `bool&`，`&v[0]` 这类取地址操作会编译失败。
   - 需要真正的 `bool` 数组时用 `vector<char>` 或 `std::bitset`。

## 对比与扩展

| 容器 | 底层结构 | 随机访问 | 头部/中间插入 | 内存连续 |
|---|---|---|---|---|
| `vector` | 动态数组 | $O(1)$ | $O(n)$ | 是 |
| `array` | 静态数组 | $O(1)$ | 不支持 | 是 |
| `deque` | 分段数组 | $O(1)$ | 头尾 $O(1)$，中间 $O(n)$ | 否 |
| `list` | 双向链表 | $O(n)$ | $O(1)$ | 否 |

**扩展**：
- **多维 vector**：`vector<vector<int>>` 可表示二维矩阵，但每行的 `vector` 各自独立分配内存，整体并不连续。
- **作为其他容器的底层**：`std::priority_queue` 默认基于 `vector` 实现，`std::stack` 也可指定 `vector` 作为底层容器。
- **手写动态数组**：理解扩容的均摊分析后，可以用「数组 + 记录 size/capacity + 扩容翻倍」手写一个简易版，加深对 STL 的理解；但实际使用中直接调用 `std::vector` 更安全、更高效。$AKB387$, '实用工具', array['数据结构', '动态数组', '序列式容器', '随机访问', '均摊复杂度'], 'col-hub-utility-stl', null, 'knowledge'),
('Xesir', 'col-ds-stl-vector--xesir', '动态数组（vector） · Xesir', $AKB388$## 算法原理

`vector` 是序列式容器里最常用的一个，你可以粗糙地理解成「一个会自动变长的数组」：底层是一片**连续内存**，元素挨着元素排排坐。连续带来两个好处——`v[i]` 直接按地址算出，随机访问 $O(1)$；遍历时按内存顺序跑，CPU 缓存吃得香。

它有两把刷子（性质）：

1. 可以**动态分配内存**：装满了就再开一块更大的、把老元素搬过去，不用你自己算长度。
2. 重写了比较运算符及赋值运算符：`==`、`<`、`=` 这类可以直接怼整个容器。

它写在 `#include<vector>` 里，声明也是一行：

```
vector<type> v;
```

`type` 是元素类型，下文「食用方法」统一拿 `int` 演示。注意有个容易搞混的点：**长度**（`size()`，实际存了几个）和**容量**（`capacity()`，已经分配了几个位置）不是一回事，前者永远不超过后者。

## 核心公式 / 状态定义与转移方程

vector 不是动态规划结构，没有状态转移方程；它值得记的是「扩容」和「均摊代价」的关系。

假设每次装不下就翻倍扩容（扩容因子 $c > 1$），从空开始连续 `push_back` $n$ 次。第 $k$ 次扩容要搬运约 $c^{k}$ 个旧元素，总搬运代价是等比级数：

$$
T(n) = \sum_{k} c^{k} \le \frac{c}{c-1} \cdot n = O(n)
$$

把 $O(n)$ 的总代价摊到 $n$ 次操作上，就得到人们常说的**均摊 $O(1)$**——大部分插入都是常数，偶尔那一次翻倍会是 $O(n)$，但很划算。

另外随机访问按下标直接算地址（`data()` 给出内部连续内存的首元素指针）：

$$
\text{address}(v[i]) = \text{data}() + i
$$

所以 `v[i]` 是 $O(1)$。

## 逐行代码解析

原笔记的「食用方法」按用途分了几组，下面照搬并补几句要点。都是关键片段，不要求拼成一个能 AC 的完整程序。

### 声明与创建

```cpp
// 1. 创建空vector; 常数复杂度
vector<int> v0;
// 1+. 这句话可以使得向vector中插入前3个元素时，保证常数时间复杂度
v0.reserve(3);
// 2. 创建一个初始空间为3的vector，其元素的默认值是0; 线性复杂度
vector<int> v1(3);
// 3. 创建一个初始空间为3的vector，其元素的默认值是2; 线性复杂度
vector<int> v2(3, 2);
// 4. 创建一个初始空间为3的vector，其元素的默认值是1，
// 并且使用v2的空间配置器; 线性复杂度
vector<int> v3(3, 1, v2.get_allocator());
// 5. 创建一个v2的拷贝vector v4， 其内容元素和v2一样; 线性复杂度
vector<int> v4(v2);
// 6. 创建一个v4的拷贝vector v5，其内容是{v4[1], v4[2]}; 线性复杂度
vector<int> v5(v4.begin() + 1, v4.begin() + 3);
// 7. 移动v2到新创建的vector v6，不发生拷贝; 常数复杂度; 需要 C++11
vector<int> v6(std::move(v2));  // 或者 v6 = std::move(v2);
```

- `reserve(n)` 只改容量不改长度，是提前躲开反复扩容搬家的关键。
- `(n)`、`(n, val)`、拷贝构造、区间构造都要逐个造元素，所以是线性复杂度。
- 移动构造 `std::move` 是把旧容器的内存直接「接手」过来，不拷贝，常数复杂度。

### 元素访问

```cpp
v.at(pos);	//返回容器中下标为 pos 的引用。如果数组越界抛出 std::out_of_range 类型的异常。
v[pos];		//返回容器中下标为 pos 的引用。不执行越界检查。
v.front();	//返回首元素的引用。
v.back();	//返回末尾元素的引用。
v.data();	//返回 v 内部存储数据使用的连续内存空间中首元素的指针。
```

- `at()` 和 `operator[]` 就差了「检不检查越界」：`at` 越界抛异常，`[]` 越界是未定义行为但更快。

### 与长度相关

```cpp
empty();	//返回一个 bool 值，即 v.begin() == v.end()，true 为空，false 为非空。
size();		//返回容器长度（元素数量），即 std::distance(v.begin(), v.end())。
resize(n);	//改变 vector 的长度为 n。如果 n 大于当前长度，则会补充元素，如果参数中提供了要补充的元素，则使用参数，否则使用默认值；如果 n 小于当前长度，则保留前 n 个元素，后续元素删除。
max_size();	//返回容器的最大可能长度。
```

### 与容量相关

```cpp
reserve();	//使得 vector 预留一定的内存空间，避免不必要的内存分配与拷贝。
capacity();	//返回容器的容量，即当前 vector 已经为多少个元素分配了空间。
shrink_to_fit();//使得 vector 的容量与长度一致，去除该 vector 没有用到的容量。
```

- `reserve` 动容量、`resize` 动长度，别混。
- `shrink_to_fit` 把多出来的容量还回去，想省内存时用。

### 元素增删及修改

```cpp
clear();	//清除所有元素
insert();	//支持在某个迭代器位置插入元素、可以插入多个。复杂度与 pos 距离末尾长度成线性而非常数的
erase();	//删除某个迭代器或者区间的元素，返回最后被删除的迭代器。复杂度与 insert 一致。
push_back();	//在末尾插入一个元素，均摊复杂度为 常数，最坏为线性复杂度。
pop_back();	//删除末尾元素，常数复杂度。
swap();		//与另一个容器进行交换，此操作是 常数复杂度 而非线性的。
```

- 末尾的 `push_back` / `pop_back` 是甜点区；中间的 `insert` / `erase` 要搬动后面一大串，天然是线性。

## 复杂度分析

| 操作 | 时间复杂度 | 说明 |
|---|---|---|
| 随机访问 `v[i]` / `at` / `front` / `back` / `data` | $O(1)$ | 连续内存，按地址直接算 |
| `push_back`（末尾插入） | 均摊 $O(1)$，最坏 $O(n)$ | 扩容那次最坏线性 |
| `pop_back`（末尾删除） | $O(1)$ | 只减长度 |
| `insert` / `erase`（中间） | $O(n)$ | 与操作位置到末尾的距离成正比 |
| `resize` / `reserve` / `shrink_to_fit` | $O(n)$ | 要重建或搬移元素 |
| `clear` | $O(n)$ | 逐个析构元素 |
| `swap` | $O(1)$ | 只换内部指针 |

空间复杂度 $O(n)$，实际占用看 `capacity()`，一般夹在 $n$ 和 $2n$ 之间（视扩容策略而定）。

## 适用场景

- 需要**连续内存**和 **$O(1)$ 随机访问**：普通数组的「会自动变长」替代品。
- 元素几乎只在**末尾**增删：收集答案、按顺序记录结果。
- 配合 `sort` / `lower_bound` / `upper_bound`：整体遍历、排序、二分。
- 长度事先不知道、会动态变化的数据。

反过来，**频繁在头部或中间插删**就别用 vector 了（每次 $O(n)$ 搬家），上 `deque` 或 `list` 更合适。

## 常见陷阱与注意事项

1. `size()` 和 `capacity()` 别混：前者是元素个数，后者是已分配容量，两者通常不相等。
2. 迭代器 / 指针 / 引用会因为扩容或 `insert` / `erase` / `resize` / `clear` 而失效，扩容后原来保存的地址全是悬空的。
3. `at()` 越界抛 `std::out_of_range`，`operator[]` 越界是未定义行为；竞赛里图快用 `[]`，但下标得自己保证合法。
4. `reserve(n)` 只改容量不改长度，`v[i]` 仍不可访问；`resize(n)` 才会改长度。
5. `clear()` 不释放内存：`size()` 归零但 `capacity()` 不变，真想还内存用 `shrink_to_fit()` 或和空 vector 交换。
6. `size()` 返回的是无符号的 `size_t`，`v.size() - 1` 在空容器上会下溢成很大的数，倒着循环建议写成 `for (int i = (int)v.size() - 1; i >= 0; i--)`。

## 对比与扩展

| 容器 | 底层结构 | 随机访问 | 头部/中间插入 | 内存连续 |
|---|---|---|---|---|
| `vector` | 动态数组 | $O(1)$ | $O(n)$ | 是 |
| `array` | 静态数组 | $O(1)$ | 不支持 | 是 |
| `deque` | 分段数组 | $O(1)$ | 头尾 $O(1)$，中间 $O(n)$ | 否 |
| `list` | 双向链表 | $O(n)$ | $O(1)$ | 否 |

扩展方向：`vector<vector<int>>` 可以当二维矩阵用（但每行各自分配内存，整体不连续）；`priority_queue`、`stack` 都可以拿 `vector` 当底层；理解了「翻倍扩容 + 均摊分析」之后，完全可以自己用「数组 + size/capacity」手写一个迷你版。$AKB388$, '实用工具', array['数据结构', 'STL', '动态数组', '序列式容器', '随机访问'], 'col-hub-utility-stl', null, 'knowledge'),
('world-needs-sunday', 'col-exam-bit-operation', 'CSP 初赛位运算完全笔记（详解 + 扩充版）', $AKB389$## 〇、地基：补码（看懂一切负数位运算的钥匙）

初赛爱直接考"写出某负数的补码"，先把地基打牢。

**核心三条：**

- `-x = ~x + 1`（取反加一）
- `~x = -x - 1`
- `~0 = -1`（-1 的二进制是全 1；`~1 = -2`）

**手算负数补码（例：8 位表示 -12）：**

```
12      = 0000 1100
按位取反 = 1111 0011
加一     = 1111 0100    ← 这就是 -12 的补码
```

**反向读补码**：最高位权值取负，直接算数值：

```
1111 0100 = -128 + 64 + 32 + 16 + 4 = -12 ✓
```

**范围**：$n$ 位补码范围 $[-2^{n-1},\; 2^{n-1}-1]$，int 是 $[-2^{31},\; 2^{31}-1]$。

> ⚠️ **坑**：`-INT_MIN` 溢出（INT_MIN 的相反数还是它自己），`abs(INT_MIN)` 同理，判断题常设陷阱。

## 一、三大恒等式（逐位证明）

**原理**：二进制每一位独立分析。单看某一位：

每一位都满足：

```
a位 + b位 = (a|b位) + (a&b位)
a位 + b位 = (a^b位) + 2×(a&b位)    （1&1 时异或丢掉的 1 变成进位 ×2）
```

按位加权求和，得到全局恒等式：

```
a | b = a + b - (a & b)
a ^ b = (a | b) - (a & b)
a + b = (a ^ b) + 2 * (a & b)
```

**验证**：`a=6(110)`，`b=3(011)` → `a&b=2`，`a|b=7`，`a^b=5`，`a+b=9`

```
9 = 5 + 2×2 ✓    7 = 9−2 ✓    5 = 7−2 ✓
```

**记忆钩子：**

- 异或 = 无进位加法
- `a&b` = 同时为 1 的位（这些位相加会进位，所以 ×2）
- `a|b` = a+b 去掉重复的部分

> **考场用法**：题目给 `a&b` 和 `a|b`，直接 `a+b = (a|b) + (a&b)`，不用求出 a 和 b。

## 二、异或 ^（初赛出题率最高）

### 性质

```
x ^ x = 0            （自己消自己）
x ^ 0 = x            （0 是单位元）
交换律、结合律成立
x ^ x ^ x = x        （奇数次保持，偶数次抵消）
x ^ (~x) = 全1 = -1
x ^ (-1) = ~x        （异或全1 = 取反）
x ^ y = 0  ⟺  x = y
```

**为什么 `a^b=c` 能推出 `a=b^c`？** 两边同时异或 b：

```
a^b^b = c^b → a^0 = b^c → a = b^c
```

（靠的就是结合律 + `x^x=0` + `x^0=x`）

### 应用一：找只出现一次的数

其余数都出现偶数次，全部异或后成对抵消为 0，剩下那个单独的数。

```cpp
ans = 0;
for (每个数 x) ans ^= x;
```

### 应用二：1^2^3^…^n 的公式（超高频！）

设 $f(n) = 1 \oplus 2 \oplus \dots \oplus n$，只看 $n \bmod 4$：

| $n \bmod 4$ | $f(n)$ |
|---|---|
| 0 | $n$ |
| 1 | $1$ |
| 2 | $n + 1$ |
| 3 | $0$ |

**原理**：任意连续 4 个数异或为 0（如 `4^5^6^7=0`），周期为 4。

自测：$f(1)=1$，$f(2)=3$，$f(3)=0$，$f(4)=4$，$f(5)=1$ ✓

### 应用三：无临时变量交换（含大坑）

```cpp
a ^= b;
b ^= a;
a ^= b;
```

> ⚠️ **坑**：若 a、b 是同一块内存（如 `swap(a[i], a[j])` 且 `i==j`），第一步就变 0。判断题陷阱。

### 应用四：Nim 博弈（与博弈论结合的选择题）

$n$ 堆石子，每次任选一堆取任意多个。先手必胜 $\iff$ 所有堆大小的异或和 $\neq 0$；异或和 $= 0$ 则先手必败。

## 三、与 &、或 |、非 ~ 的代数定律

**幂等律：**

```
x & x = x        x | x = x
```

**零元 / 单位元：**

```
x & 0 = 0        x | 0 = x          （0 是 | 的单位元）
x & ~0 = x       x | ~0 = ~0        （全1 是 & 的单位元）
```

**互补：**

```
x & ~x = 0       x | ~x = ~0(全1)
```

**还原律：**

```
~~x = x
```

**分配律（双向！这和普通算术不同，两边都能展开）：**

```
a & (b | c) = (a & b) | (a & c)
a | (b & c) = (a | b) & (a | c)
```

**吸收律（补充，选择题用来化简）：**

```
a & (a | b) = a
a | (a & b) = a
```

**德摩根律（补充）：**

```
~(a & b) = ~a | ~b
~(a | b) = ~a & ~b
```

**结合律**：`&`、`|`、`^` 都满足；不满足消去律：`a&b = a&c` 推不出 `b=c`（但 `a|b = a|c` 且 `a&b = a&c` 可以推出 `b=c`）。

## 四、移位 << >>

### 左移

`x << k` = $x \times 2^k$（不溢出的前提下！），低位补 0。

> ⚠️ **坑**：
> - int 溢出后不再等于乘 $2^k$，`1 << 31` 对 32 位 int 是移入符号位（UB/结果常为 INT_MIN）。要表示 $2^{31}$ 就写 `1LL << 31` 或 `1u << 31`。
> - 移位数 ≥ 类型位宽也是 UB：`x << 32` ≠ `x << 0`，读程序题挖过坑。

### 右移

- 无符号数 / 非负数：`x >> k` = $\lfloor x / 2^k \rfloor$，高位补 0（逻辑右移）
- 有符号负数：高位补 1（算术右移）

> ⚠️ **超级考点——负数右移 ≠ C++ 除法**：
> - `-7 >> 1 = -4`（算术右移 = 向下取整，数学意义 $\lfloor -3.5 \rfloor$）
> - `-7 / 2 = -3`（C++ 除法 = 向零截断）
>
> 另外：`-1 >> k = -1`（全1右移还是全1）。

### 移位取模（补充）

非负 $x \bmod 2^k$ = `x & ((1 << k) - 1)`

例：`x & 0xF` = x 的低 4 位

> ⚠️ 负数时 `&` 给的是数学模（结果非负），`%` 给的是截断（可为负），如 `-7 & 3 = 1` 而 `-7 % 3 = -1`。

## 五、两大神器：x&(x-1) 和 x&(-x)

### x & (x-1)：清除最低位的 1

**原理**：设 `x = …A 1 00…0`（最低的 1 后面跟 k 个 0）

```
减 1 借位 → x-1 = …A 0 11…1 （最低的 1 变 0，后面的 0 全变 1）
相与     → …A 00…0          （那个 1 消失，高位原封不动）
```

例：`x=10100`, `x-1=10011`, `x&(x-1)=10000`

**两大衍生：**

**判断 2 的幂**：

```cpp
x > 0 && (x & (x-1)) == 0
```

（2 的幂二进制只有一个 1，消掉就变 0）

**数 1 的个数**：每次至少消一个 1，循环几次就有几个 1（比逐位判快）

```cpp
int cnt = 0;
while (x) { x &= x-1; cnt++; }
```

（GCC 内建：`__builtin_popcount(x)`）

### x & (-x)：取出最低位的 1

**原理**：`-x = ~x + 1`。设 `x = …B 1 00…0`

```
~x = …~B 0 11…1
加 1 的进位链恰好停在原最低 1 的位置，把它重新置 1：
-x = …~B 1 00…0
x 与 -x 相与：高位 B & ~B = 0，低位全 0，只剩那个 1。
```

例：`x = 10100`，`-x = …11101100`，`x & -x = 00100` ✓

> 📌 **澄清一个常见误解**：它对任意整数（含正数）都有效，前提是"负数用补码表示"——C++ 恰好就是补码，所以放心用。它也叫 **lowbit**，是树状数组（复赛）的核心操作。

### 姊妹公式（补充，判断题会考）

```
x & (x+1) == 0   ⟺  x 是 2^k - 1（二进制全1，如 0,1,3,7,15,255）
~x & (x+1)        ：取出最低位的 0
```

## 六、位操作四件套 + 状压集合（复赛也常用）

**单个位的操作**（i 从 0 开始，最低位是第 0 位）：

| 操作 | 代码 |
|---|---|
| 取第 i 位 | `(x >> i) & 1` → 0 或 1 |
| 第 i 位置 1 | `x \| (1 << i)` |
| 第 i 位清 0 | `x & ~(1 << i)` |
| 第 i 位翻转 | `x ^ (1 << i)` |

**状压 DP / 集合运算**（把集合塞进一个 int）：

```
全集 = (1 << n) - 1        空集 = 0
加入元素 i：s | (1 << i)
删除元素 i：s & ~(1 << i)
判断 i ∈ s：(s >> i) & 1 → 非 0
A ⊆ B：(A & B) == A
```

**枚举 s 的所有非空子集：**

```cpp
for (int t = s; t; t = (t - 1) & s) { /* ... */ }
```

**格雷码**（偶尔考概念）：`gray(x) = x ^ (x >> 1)`

## 七、运算符优先级——初赛第一大坑！

从高到低完整链条：

```
~（一元） >  * / %  >  + -  >  << >>  >  < <= > >=  >  == !=  >  &  >  ^  >  |  >  &&  >  ||  >  赋值
```

**关键结论**：`&`、`^`、`|` 的优先级比 `==` 还低！由此产生两大经典陷阱：

**陷阱 1**：

```cpp
if (x & 1 == 0)        // 实际是 if (x & (1 == 0)) = if (x & 0) = 恒假！
if ((x & 1) == 0)      // 正确
```

**陷阱 2**：

```cpp
1 << 2 + 3             // 实际是 1 << (2+3) = 1 << 5 = 32（加减高于移位）
```

> ⚠️ **附加坑**：`&&` 有短路求值，`&` 没有——`if (p != NULL & p->x)` 可能崩，`&&` 不会。

**口诀**：位运算表达式一律手动加括号，永不失手。

## 八、有符号 / 无符号坑

混比 / 混算时有符号自动转无符号：

- `-1 < 1u` 结果是 `false`（-1 变成 4294967295）。
- `unsigned` 永远 ≥ 0：`for (unsigned i = 5; i >= 0; i--)` 死循环。
- `v.size()` 返回 unsigned：`for (int i = 0; i < v.size() - 1; i++)` 在 v 为空时，`size()-1` 变成巨大数——读程序题常客。

## 九、大小关系不等式链（选择题排除神器）

对非负整数 $a$、$b$：

$$a \mathbin{\&} b \;\leq\; \min(a,b) \;\leq\; \max(a,b) \;\leq\; a \mathbin{|} b \;\leq\; a + b$$

$$且 \quad a \oplus b \;\leq\; a \mathbin{|} b$$

**原理**：`a&b` 每一位 ≤ a 对应位；`a|b = a+b−(a&b)` ≤ a+b。

**验证**：`a=6`, `b=3`：$2 \leq 3 \leq 6 \leq 7 \leq 9$，$5 \leq 7$ ✓

**配套判断：**

- `a + b == a | b` $\iff$ `a & b == 0`（无公共 1，加法无进位）
- `a ^ b == a | b` $\iff$ `a & b == 0`（同一个条件）
- `a ^ b == a + b` $\iff$ 同上

## 十、必背常数 + 进制转换基本功

**2 的幂表：**

| 幂次 | 值 | 幂次 | 值 |
|---|---|---|---|
| $2^0$ | 1 | $2^6$ | 64 |
| $2^1$ | 2 | $2^7$ | 128 |
| $2^2$ | 4 | $2^8$ | 256 |
| $2^3$ | 8 | $2^{10}$ | 1024 |
| $2^4$ | 16 | $2^{16}$ | 65536 |
| $2^5$ | 32 | $2^{20}$ | $\approx 10^6$ |

| 常数 | 值 |
|---|---|
| $2^{30}$ | $\approx 10^9$ |
| $2^{31}$ | 2147483648 |
| INT_MAX ($2^{31}-1$) | 2147483647 |
| INT_MIN ($-2^{31}$) | -2147483648 |
| UINT_MAX ($2^{32}-1$) | 4294967295 |

**估算口诀**：$2^{10} \approx 10^3$，$2^k \approx 10^{0.3k}$

**常用十六进制：**

```
0xFF = 255
0x7FFFFFFF = INT_MAX
0xFFFFFFFF = -1(int) = 4294967295(unsigned)
0x3F3F3F3F ≈ 1.06×10^9（memset 设"无穷大"，两倍不爆 int）
```

**进制转换**（初赛第一大题就是它）：

- 十→二：除 2 取余，逆序写；小数部分乘 2 取整
- 二→十六：从右往左 4 位一组；二→八：3 位一组
- $2^k$ 的二进制 = 1 后 k 个 0；$2^k - 1$ = k 个 1

## 十一、终极速记卡（考场默写版）

**【补码】** `~x+1`、`~x = -x-1`、`~0 = -1`（全1）

**【三大恒等式】**

```
a | b = a + b - (a & b)
a ^ b = (a | b) - (a & b)
a + b = (a ^ b) + 2*(a & b)      （异或=无进位加法）
```

**【异或】** `x^x=0`、`x^0=x`、`a^b=c ⟹ a=b^c`

$1 \oplus \dots \oplus n$：$n \bmod 4 = 0 \to n$，$1 \to 1$，$2 \to n+1$，$3 \to 0$

找单独数 / Nim（异或和 0 必败）

**【定律】** 分配（双向）、吸收 `a&(a|b)=a`、德摩根 `~(a&b)=~a|~b`

**【移位】** `x<<k` = $x \times 2^k$（防溢出写 `1LL<<k`）

负数右移是 floor，C++ 除法是向零截断：`-7>>1=-4` ≠ `-7/2=-3`

$x \bmod 2^k =$ `x & (2^k - 1)`

**【神器】** `x&(x-1)` 去掉最低位 1（判 2 幂 / 数 1 个数）

`x&(-x)` 取出最低位 1（lowbit，树状数组）

`x&(x+1)==0` $\iff$ x 是 $2^k - 1$

**【四件套】** 取：`>>i & 1`　置：`| 1<<i`　清：`& ~(1<<i)`　翻：`^ 1<<i`

**【大小链】** `a&b ≤ min ≤ max ≤ a|b ≤ a+b`；`a^b ≤ a|b`

**【优先级】** `~ > */% > +- > <<>> > 关系 > == > & > ^ > | > &&`

大坑：`x & 1 == 0` 实为 `x & (1==0)` 恒假；`1<<2+3 = 32`

铁律：位运算一律加括号！

**【无符号坑】** `-1 < 1u` 为假；`unsigned i≥0` 恒真；空容器 `size()-1` 爆炸

**【常数】** $2^{31}=2147483648$　INT_MAX $= 2147483647$　$2^{10} \approx 10^3$

> **使用建议**：每天默写一遍速记卡；做题时优先用"逐位分析"和"大小关系链"两条思路排除选项；遇到负数、unsigned、优先级三类题先警觉三分——初赛的坑 90% 藏在这三处。$AKB389$, '实用工具', array['位运算', '补码', '异或', '移位', '状压', '运算符优先级', 'CSP初赛'], 'col-hub-exam', null, 'knowledge'),
