这个故事告诉我们一定要以代码为准。~~QAQ~~

### T3
```cpp
#include <iostream>
using namespace std;
int n, fa[100007], f[100007], ans;
int main() {
    cin >> n;
    for (int i = 2; i <= n; ++i) {
        cin >> fa[i];
    }
    for (int i = n; i >= 2; --i) {
        if (f[fa[i]] + f[i] + 1 > ans) {
            ans = f[fa[i]] + f[i] + 1;
        }
        if (f[i] + 1 > f[fa[i]]) {
            f[fa[i]] = f[i] + 1;
        }
    }
    cout << ans << endl;
    return 0;
}
```

说明：输入第一行为结点个数 $n$，第二行为 $n-1$ 个整数，依次表示结点 $2\sim n$ 的父结点编号，满足 $1\le fa[i]<i$，根结点为 $1$。

### 解析

由于题目保证 $fa[i]<i$，所以每个结点的父结点编号都小于自己的编号。反过来说，一个结点的所有子结点编号一定大于该结点。
因此，程序按照：
```cpp
for (int i = n; i >= 2; --i)
```
从大到小处理结点时，处理结点 `i` 之前，它的所有子结点都已经处理完毕。

`f[i]` 表示从结点 `i` 出发，向其子树中的叶子结点延伸，最多能经过多少条边。也就是以 `i` 为根的子树高度。
更新语句：
```cpp
if (f[i] + 1 > f[fa[i]]) {
    f[fa[i]] = f[i] + 1;
}
```
表示从父结点 `fa[i]` 经过一条边到达 `i`，再沿着 `i` 的最长路径继续向下。因此 $f[fa[i]]=\max(f[fa[i]],f[i]+1)$。

`ans` 在更新 `f[fa[i]]` 之前执行：
```cpp
ans = max(ans, f[fa[i]] + f[i] + 1);
```
此时 `f[i] + 1` 是从父结点 `fa[i]` 经过 `i` 向下延伸的最长路径，`f[fa[i]]` 是此前处理过的其他子树提供的最长路径。
把这两条路径在父结点处连接起来，长度为 $f[fa[i]]+f[i]+1$。


程序枚举了所有可能作为路径转折点的结点，因此最终 `ans` 表示树的直径，即树中距离最远的两个结点之间路径所经过的边数。


**Q1：当 $n=5$，$fa[2]\sim fa[5]=\{1,2,3,4\}$ 时，程序输出 4。（ ）**

**答案：正确（T）**
**解析**：

对应的树是一条链：

![](https://cdn.luogu.com.cn/upload/image_hosting/l9s25ty7.webp)

从结点 1 到结点 5 一共经过 4 条边，因此树的直径为 4。

也可以模拟程序：

| 处理的 `i` | 更新后的相关 `f` | `ans` |
|---|---|---:|
| 5 | `f[4]=1` | 1 |
| 4 | `f[3]=2` | 2 |
| 3 | `f[2]=3` | 3 |
| 2 | `f[1]=4` | 4 |

最终输出：

```text
4
```

所以该说法正确。

**Q2：程序输出前，`f[1]` 的值一定等于 `ans` 的值。（ ）**

**答案：错误（F）**

**解析**：

`f[1]` 表示从根结点 1 到最远叶子结点的距离，也就是树的高度；`ans` 表示树中任意两个结点之间的最大距离，也就是树的直径。

树的直径不一定经过根结点，所以二者不一定相等，该说法错误。

---

**Q3：将第 10—12 行与第 13—15 行两个 `if` 语句的顺序交换后，程序输出结果不受影响。（ ）**

**答案：错误（F）**

**解析**

原程序必须先计算 `ans`，再更新 `f[fa[i]]`：

```cpp
ans = max(ans, f[fa[i]] + f[i] + 1);
f[fa[i]] = max(f[fa[i]], f[i] + 1);
```

计算 `ans` 时，`f[fa[i]]` 应当表示父结点此前处理过的其他子树所提供的最长路径。

如果交换顺序，先执行：

```cpp
f[fa[i]] = max(f[fa[i]], f[i] + 1);
```

那么 `f[fa[i]]` 可能已经包含当前结点 `i` 所在的路径。随后再计算：

```cpp
f[fa[i]] + f[i] + 1
```

就可能把当前这条路径计算两遍。因此交换顺序会影响结果，该说法错误。

---


**Q4：程序输出的 `ans` 表示的是（ ）。**

A. 树中距离最远的两个结点之间路径所经过的边数  
B. 根结点 1 到最远叶子结点之间路径所经过的边数  
C. 树中叶子结点的个数  
D. 所有结点的父结点编号之和  

**答案：A**
**解析**：

上面程序解析已经讲过，不再赘述。

---

**Q5：当 $n=7$，$fa[2]\sim fa[7]=\{1,1,2,2,3,3\}$ 时，输出为（ ）。**

A. 2　B. 3　C. 4　D. 5

**答案：C**
**解析：**


![](https://cdn.luogu.com.cn/upload/image_hosting/8l5t71m9.webp)

树中最长路径可以从结点 2 的子树中的某个叶子出发，经过结点 1，到达结点 3 的子树中的某个叶子。
因此树的直径为 4，程序输出 4，故选 **C**。

**Q6：当 $n=10$ 时，满足程序输出为 9 的合法输入种类数为（ ）。**

A. 0　B. 9　C. 256　D. 512

**答案：C**
**解析：**

一棵含 10 个结点的树最多只有 9 条边。如果程序输出 9，说明树的直径为 9，也就是存在一条包含 9 条边的路径，这条路径会经过全部 10 个结点。因此整棵树必须是一条**链**。

结点 1 不一定处在链的端点，也可能位于链的中间。例如：
```text
8 - 5 - 2 - 1 - 3 - 4 - 6 - 7 - 9 - 10
```
由于题目要求 $fa[i]<i$，从根结点 1 沿着任意一条分支向外走时，结点编号必须严格递增。因此可以把结点 $2\sim10$ 分配到根结点 1 的两条链上。每条链中的排列顺序是唯一的，即按照编号从小到大排列。
先暂时区分“第一条链”和“第二条链”。结点 $2\sim10$ 一共有 9 个，每个结点都有两种选择，放入第一条链或放入第二条链。因此得到 $2^9=512$ 种分配。

但是输入只记录每个结点的父结点，并没有记录哪条链是“第一条”、哪条链是“第二条”。交换两条链后，父结点数组完全相同。

以上面的划分为例：
```text
第一组：{2, 5, 8}
第二组：{3, 4, 6, 7, 9, 10}
```
与：
```text
第一组：{3, 4, 6, 7, 9, 10}
第二组：{2, 5, 8}
```
都会得到同一个父结点数组：
```text
fa[2]=1
fa[3]=1
fa[4]=3
fa[5]=2
fa[6]=4
fa[7]=6
fa[8]=5
fa[9]=7
fa[10]=9
```
所以每一种合法输入都被重复统计了两次。最终输入种类数为：

$$
\frac{2^9}{2}=2^8=256
$$

故选 **C**。

## 完善程序
### T1

#### 题目描述

给定一张有 $n$ 个顶点、$m$ 条边的无向图，每条边带有符号 `'+'` 或 `'-'`。

对于一条从顶点 $s$ 到顶点 $t$ 的路线，允许重复经过顶点和边。记 $n^+$、$n^-$ 分别为路线中经过的 `'+'` 边数和 `'-'` 边数，则该路线的权值为：

$$
|n^+-n^-|
$$

请计算从 $s$ 到 $t$ 的路线的最小权值。若不存在从 $s$ 到 $t$ 的路线，则输出 $-1$。

输入第一行为四个整数 $n,m,s,t$。接下来 $m$ 行，每行给出两个整数 $a,b$ 和一个字符 `'+'` 或 `'-'`，描述一条连接 $a$ 与 $b$ 的无向边及其符号。

数据满足 $2\le n\le 2\times 10^5$，$1\le m\le4\times10^5$，$1\le s,t\le n$ 且 $s\ne t$，$1\le a,b\le n$，可能出现重边。

以下程序通过 BFS 求出最小权值，请补全程序。

```cpp
#include <iostream>
constexpr int N = 200005;
constexpr int M = 400005;
int n, m, s, t;
int h[N], e[M << 1], ne[M << 1], w[M << 1], idx;
int q[N], d[N], c[N];
void add(int a, int b, int z) {
    e[idx] = b;
    w[idx] = z;
    ne[idx] = h[a];
    h[a] = idx++;
}
int main() {
    std::cin >> n >> m >> s >> t;
    for (int i = 1; i <= n; i++)
        h[i] = d[i] = c[i] = -1;
    for (int i = 0; i < m; i++) {
        int a, b;
        char op[2];
        std::cin >> a >> b >> op;
        int z = /* ① */;
        add(a, b, z);
        add(b, a, z);
    }
    int hh = 0, tt = 0;
    int p = 0, ng = 0, ok = 1;
    q[tt++] = s;
    d[s] = c[s] = 0;
    while (/* ② */) {
        int x = q[hh++];
        for (int i = h[x]; i != -1; i = ne[i]) {
            int y = e[i];
            if (w[i] > 0) p = 1;
            if (w[i] < 0) ng = 1;
            if (d[y] == -1) {
                d[y] = /* ③ */;
                c[y] = c[x] ^ 1;
                q[tt++] = y;
            } else if (/* ④ */)
                ok = 0;
        }
    }
    if (d[t] == -1) {
        std::cout << -1;
        return 0;
    }
    if (!p || !ng) {
        std::cout << d[t];
        return 0;
    }
    if (/* ⑤ */) std::cout << 0;
    else std::cout << 1;
    return 0;
}
```

#### 解析

可以将 `'+'` 边的边权记为 $1$，将 `'-'` 边的边权记为 $-1$。这样，一条路线所经过边的权值之和就是：

$$
n^+-n^-
$$

题目要求最小化其绝对值：

$$
|n^+-n^-|
$$

程序从顶点 $s$ 开始进行 BFS，同时完成以下三项工作：

1. 判断 $t$ 是否与 $s$ 连通；
2. 计算从 $s$ 到每个顶点的最短边数 `d[i]`；
3. 对 $s$ 所在的连通块进行二分图染色，判断其中是否存在奇环。

其中：

- `p` 表示从 $s$ 出发能够访问到的连通块中是否存在 `'+'` 边；
- `ng` 表示该连通块中是否存在 `'-'` 边；
- `d[i]` 表示从 $s$ 到 $i$ 的最短路所经过的边数；
- `c[i]` 表示二分图染色中顶点 $i$ 的颜色；
- `ok` 表示该连通块是否为二分图。

如果 `d[t] == -1`，说明 $s$ 无法到达 $t$，输出 $-1$。

如果连通块中只存在一种符号的边，那么路线权值的绝对值就是路线经过的边数。此时应选择边数最少的路线，因此答案为 `d[t]`。

如果连通块中同时存在 `'+'` 边和 `'-'` 边，由于允许重复经过边，可以通过往返经过某条边来调整路线权值：

- 往返经过一条 `'+'` 边，权值之和增加 $2$；
- 往返经过一条 `'-'` 边，权值之和减少 $2$。

因此可以将路线权值调整到绝对值为 $0$ 或 $1$，奇偶性与路线长度相同。

- 若存在偶数长度路线，答案为 $0$；
- 若所有从 $s$ 到 $t$ 的路线长度均为奇数，答案为 $1$。

这是因为每条边的权值都是 $1$ 或 $-1$，在模 $2$ 意义下均与 $1$ 同余，所以路线的权值之和与路线长度奇偶性相同。

若图不是二分图，即 `ok == 0`，说明存在奇环。可以通过额外绕行一次奇环改变路线长度的奇偶性，因此一定存在偶数长度的 $s$ 到 $t$ 路线。

若图是二分图，则所有从 $s$ 到 $t$ 的路线长度奇偶性相同：

- `c[s] == c[t]` 时，路线长度为偶数，答案为 $0$；
- `c[s] != c[t]` 时，路线长度为奇数，答案为 $1$。

所以输出 $0$ 的条件为：

```cpp
!ok || c[s] == c[t]
```


**Q1：①处应填（ ）。**

A. `op[0] == '+' ? 0 : 1`  
B. `op[0] == '+'`  
C. `op[0] == '+' ? 1 : -1`  
D. `op[0] == '-' ? 1 : 0`

**答案：C**

**解析**：

程序需要记录每条边对 $n^+-n^-$ 的贡献：

- 经过一条 `'+'` 边，$n^+-n^-$ 增加 $1$；
- 经过一条 `'-'` 边，$n^+-n^-$ 减少 $1$。

因此应将 `'+'` 边的权值记为 $1$，将 `'-'` 边的权值记为 $-1$：

```cpp
int z = op[0] == '+' ? 1 : -1;
```

故选 **C**。



**Q2：②处应填（ ）。**

A. `hh < n`  
B. `tt < n`  
C. `hh <= tt`  
D. `hh < tt`

**答案：D**

**解析**：

数组 `q` 用来模拟 BFS 队列：

- `hh` 指向队首；
- `tt` 指向队尾的下一个位置；
- `q[hh]` 到 `q[tt-1]` 是尚未取出的元素。

只要 `hh < tt`，队列中就还有待处理的顶点。因此 BFS 的循环条件为：

```cpp
while (hh < tt)
```

不能使用 `hh <= tt`，因为当 `hh == tt` 时队列已经为空，继续访问 `q[hh]` 会取出无效元素。
类似于 STL 容器中 `q.begin(),q.end()` 的逻辑。

故选 **D**。



**Q3：③处应填（ ）。**

A. `d[y] + 1`  
B. `d[x] + 1`  
C. `d[x]`  
D. `d[x] - 1`

**答案：B**

**解析**：

`d[x]` 表示从起点 $s$ 到顶点 $x$ 的最短路长度。

当 BFS 第一次从 $x$ 访问到相邻顶点 $y$ 时，从 $s$ 到 $y$ 的路线比从 $s$ 到 $x$ 的路线多经过一条边，因此：

$$
d[y]=d[x]+1
$$

对应代码为：

```cpp
d[y] = d[x] + 1;
```

故选 **B**。



**Q4：④处应填（ ）。**

A. `c[y] == c[x]`  
B. `w[i] == 1`  
C. `c[y] != c[x]`  
D. `d[y] + 1 != d[x]`

**答案：A**

**解析**：

程序使用 `c[i]` 对图进行二分图染色。第一次访问顶点 $y$ 时，将其颜色设置为与 $x$ 相反：

```cpp
c[y] = c[x] ^ 1;
```

如果 $y$ 已经被访问过，那么对于边 $(x,y)$，两端点的颜色应当不同。

若出现：

```cpp
c[y] == c[x]
```

说明一条边连接了两个颜色相同的顶点，该连通块不是二分图，其中存在奇环，此时将：

```cpp
ok = 0;
```

故选 **A**。



**Q5：⑤处应填（ ）。**

A. `ok && c[s] == c[t]`  
B. `ok && c[s] != c[t]`  
C. `!ok || c[s] == c[t]`  
D. `!ok && c[s] != c[t]`

**答案：C**

**解析**：

运行到此处时，已经确定：

- $s$ 能够到达 $t$；
- $s$ 所在连通块中既有 `'+'` 边，也有 `'-'` 边。

因此最小权值只可能为 $0$ 或 $1$。当存在从 $s$ 到 $t$ 的偶数长度路线时，可以将路线权值调整为 $0$。

分两种情况讨论。

1. 图不是二分图

此时 `ok == 0`，图中存在奇环。通过额外绕行奇环，可以改变路线长度的奇偶性，因此一定能够得到一条偶数长度的 $s$ 到 $t$ 路线，答案为 $0$。

2. 图是二分图

此时路线长度的奇偶性由两端点颜色决定：

- `c[s] == c[t]`，从 $s$ 到 $t$ 的路线长度为偶数，答案为 $0$；
- `c[s] != c[t]`，从 $s$ 到 $t$ 的路线长度为奇数，答案为 $1$。

所以输出 $0$ 的条件是：

```cpp
!ok || c[s] == c[t]
```

故选 **C**。



补全后的关键代码为：

```cpp
int z = op[0] == '+' ? 1 : -1;

while (hh < tt) {
    int x = q[hh++];
    for (int i = h[x]; i != -1; i = ne[i]) {
        int y = e[i];
        if (w[i] > 0) p = 1;
        if (w[i] < 0) ng = 1;
        if (d[y] == -1) {
            d[y] = d[x] + 1;
            c[y] = c[x] ^ 1;
            q[tt++] = y;
        } else if (c[y] == c[x])
            ok = 0;
    }
}

// ...

if (!ok || c[s] == c[t]) std::cout << 0;
else std::cout << 1;
```

### T2
~~请输入文本~~

#### 题目描述

给定 $n$ 名学生参加一场考试，考试共有 $m$ 道选择题，每道题只有 A、B 两个选项。

第 $i$ 名学生的作答为一个长度为 $m$ 的字符串。若最终公布的标准答案与该学生在某道题上的作答相同，则该学生在这道题上得 $1$ 分，否则不得分。记第 $i$ 名学生最终得到的总分为 $r_i$。

每名学生还有一个预期得分 $x_i$。现在需要构造一份标准答案，使：

$$
\sum_{i=1}^{n}|r_i-x_i|
$$

尽可能大。

数据满足 $1\le n\le18$，$1\le m\le300$，$0\le x_i\le m$。

提示：可以换一个角度处理 $\sum_{i=1}^{n}|r_i-x_i|$，把它写成更易优化的形式；对于正整数 $x$，`__builtin_ctzll(x)` 返回 $x$ 的二进制表示末尾连续 $0$ 的个数，`__builtin_popcountll(x)` 返回 $x$ 的二进制表示中 $1$ 的个数。

以下程序构造出一组满足要求的标准答案，请补全程序。

```cpp
#include <cstdlib>
#include <iostream>
#include <string>
#include <vector>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
int main() {
    int n, m;
    cin >> n >> m;
    vector<ll> x(n), c(n);
    for (int i = 0; i < n; i++) {
        cin >> x[i];
        c[i] = /* ① */;
    }
    vector<string> a(n);
    for (int i = 0; i < n; i++)
        cin >> a[i];
    vector<int> s(n, -1);
    vector<ll> q(m, 0);
    ll C = 0, S = 0;
    for (int i = 0; i < n; i++) {
        C -= c[i];
        for (int j = 0; j < m; j++) {
            if (a[i][j] == 'A') q[j]--;
            else q[j]++;
        }
    }
    for (int j = 0; j < m; j++) S += abs(q[j]);
    ll ans = C + S;
    ull best = 0, lst = 0;
    for (ull mask = 1; mask < (1ULL << n); mask++) {
        ull g = /* ② */;
        ull d = g ^ lst;
        int k = /* ③ */;
        C -= /* ④ */;
        for (int j = 0; j < m; j++) {
            ll old = q[j];
            int v = (a[k][j] == 'A' ? 1 : -1);
            q[j] -= 2ll * s[k] * v;
            S += abs(q[j]) - abs(old);
        }
        s[k] = -s[k];
        if (C + S > ans) {
            ans = C + S;
            best = g;
        }
        lst = g;
    }
    for (int i = 0; i < n; i++) {
        if ((best >> i) & 1) s[i] = 1;
        else s[i] = -1;
    }
    string res(m, 'A');
    for (int j = 0; j < m; j++) {
        ll v = 0;
        for (int i = 0; i < n; i++) {
            if (a[i][j] == 'A') v += s[i];
            else v -= s[i];
        }
        if (/* ⑤ */) res[j] = 'A';
        else res[j] = 'B';
    }
    cout << res << endl;
    return 0;
}
```

#### 解析

这道题的关键是把绝对值转化为可以枚举的形式。

对于第 $j$ 道题，将学生答案与标准答案分别表示为 $1$ 或 $-1$：

- 学生选择 A，记为 $v_{i,j}=1$；
- 学生选择 B，记为 $v_{i,j}=-1$；
- 标准答案为 A，记为 $y_j=1$；
- 标准答案为 B，记为 $y_j=-1$。

当学生答案与标准答案相同时，$v_{i,j}y_j=1$；不同时，$v_{i,j}y_j=-1$。因此第 $i$ 名学生的得分为：

$$
r_i=\sum_{j=1}^{m}\frac{1+v_{i,j}y_j}{2}
=\frac{m+\sum_{j=1}^{m}v_{i,j}y_j}{2}
$$

从而：

$$
|r_i-x_i|
=\frac{1}{2}\left|m-2x_i+\sum_{j=1}^{m}v_{i,j}y_j\right|
$$

由于所有方案的目标值都同时乘以常数 $\frac12$，因此最大化原式等价于最大化：

$$
\sum_{i=1}^{n}\left|m-2x_i+\sum_{j=1}^{m}v_{i,j}y_j\right|
$$

利用恒等式：

$$
|z|=\max_{s\in\{-1,1\}}sz
$$

可以为每名学生设置一个 $s_i\in\{-1,1\}$，于是目标变为：

$$
\max_{s_1,\ldots,s_n}
\max_{y_1,\ldots,y_m}
\sum_{i=1}^{n}s_i
\left(m-2x_i+\sum_{j=1}^{m}v_{i,j}y_j\right)
$$

交换求和顺序可得：

$$
\sum_{i=1}^{n}s_i(m-2x_i)
+
\sum_{j=1}^{m}y_j\sum_{i=1}^{n}s_iv_{i,j}
$$

令：

$$
C=\sum_{i=1}^{n}s_i(m-2x_i)
$$

以及：

$$
q_j=\sum_{i=1}^{n}s_iv_{i,j}
$$

对于一组固定的 $s_i$，每道题的标准答案可以独立选择。为了让 $y_jq_j$ 最大：

- 当 $q_j\ge0$ 时，令 $y_j=1$，即标准答案选择 A；
- 当 $q_j<0$ 时，令 $y_j=-1$，即标准答案选择 B。

第 $j$ 道题的最大贡献就是 $|q_j|$，因此固定 $s_i$ 后的最优值为：

$$
C+\sum_{j=1}^{m}|q_j|
$$

程序枚举全部 $2^n$ 种 $s_i$。由于 $n\le18$，这样的枚举可以接受。

为了让相邻两种状态之间只有一名学生的 $s_i$ 改变，程序使用格雷码：

$$
g=mask\mathbin{\hat{\ }}(mask\mathbin{>>}1)
$$

相邻格雷码只有一个二进制位不同。找到发生变化的位置 $k$ 后，只需要更新第 $k$ 名学生对 `C` 和所有 `q[j]` 的贡献，不需要重新计算整个状态。

总时间复杂度为：

$$
O(2^n m)
$$

~~你CCF能把25年都从大纲删了的格雷码考出来，还有什么是CCF做不到的~~

**Q1：①处应填（ ）。**

A. `2 * x[i] - m`  
B. `-m + 2 * x[i] + 1`  
C. `m - 2 * x[i]`  
D. `m + 2 * x[i]`

**答案：C**

**解析**：

根据前面的推导，第 $i$ 名学生对应的式子为：

$$
m-2x_i+\sum_{j=1}^{m}v_{i,j}y_j
$$

其中与标准答案无关的常数部分为：

$$
c_i=m-2x_i
$$

因此①处应填：

```cpp
m - 2 * x[i]
```

程序最初令所有 `s[i]` 均为 $-1$，所以初始化时执行：

```cpp
C -= c[i];
```

正好得到：

$$
C=\sum_{i=1}^{n}s_ic_i=-\sum_{i=1}^{n}c_i
$$

故选 **C**。



**Q2：②处应填（ ）。**

A. `mask | (mask >> 1)`  
B. `mask ^ (mask >> 1)`  
C. `mask & (mask >> 1)`  
D. `mask ^ ((mask >> 1) + 1)`

**答案：B**

**解析**：

程序需要使用格雷码枚举，使相邻两个状态恰好只有一个二进制位发生改变。

整数 `mask` 对应的格雷码为：

$$
g=mask\mathbin{\hat{\ }}(mask\mathbin{>>}1)
$$

对应代码为：

```cpp
ull g = mask ^ (mask >> 1);
```

这样 `g` 与上一个格雷码 `lst` 之间只有一个二进制位不同，程序便可以只修改一名学生对应的状态。

故选 **B**。



**Q3：③处应填（ ）。**

A. `__builtin_ctzll(d) + 1`  
B. `__builtin_popcountll(d)`  
C. `__builtin_ctzll(g)`  
D. `__builtin_ctzll(d)`

**答案：D**

**解析**：

`g` 表示当前格雷码，`lst` 表示上一个格雷码，因此：

```cpp
ull d = g ^ lst;
```

`d` 中为 $1$ 的二进制位就是两个状态之间发生改变的位置。

由于相邻格雷码只有一位不同，所以 `d` 中恰好只有一个 $1$。`__builtin_ctzll(d)` 返回末尾连续 $0$ 的个数，也就是这个 $1$ 所在的下标。

例如：

```text
d = 001000
```

其末尾有 $3$ 个连续的 $0$，发生改变的是下标 $3$，因此：

```cpp
int k = __builtin_ctzll(d);
```

故选 **D**。



**Q4：④处应填（ ）。**

A. `2ll * s[k] * c[k]`  
B. `s[k] * c[k]`  
C. `2ll * (s[k] - c[k])`  
D. `2ll * c[k]`

**答案：A**

**解析**：

当前 `C` 为：

$$
C=\sum_{i=1}^{n}s_i c_i
$$

本次格雷码变化后，`s[k]` 将从原来的 $s_k$ 变为 $-s_k$。

变化前，第 $k$ 项对 `C` 的贡献为：

$$
s_kc_k
$$

变化后，其贡献为：

$$
-s_kc_k
$$

所以 `C` 的变化量为：

$$
-s_kc_k-s_kc_k=-2s_kc_k
$$

因此更新方式为：

```cpp
C -= 2ll * s[k] * c[k];
```

需要注意，这里使用的是翻转前的 `s[k]`，所以程序在更新完 `C` 和 `q[j]` 后，才执行：

```cpp
s[k] = -s[k];
```

故选 **A**。



**Q5：⑤处应填（ ）。**

A. `v >= (n & 1)`  
B. `v > (n & 1)`  
C. `v + (n & 1) >= 0`  
D. `v * (n & 1) >= 0`

**答案：A**

**解析**：

确定最优的 `s[i]` 后，程序对每道题计算：

```cpp
ll v = 0;
for (int i = 0; i < n; i++) {
    if (a[i][j] == 'A') v += s[i];
    else v -= s[i];
}
```

这里的 `v` 就是：

$$
v=\sum_{i=1}^{n}s_iv_{i,j}
$$

~~你CCF还能混用变量名~~

如果第 $j$ 道题选择 A，其贡献为 $v$；如果选择 B，其贡献为 $-v$。因此：

- 当 $v\ge0$ 时，选择 A；
- 当 $v<0$ 时，选择 B。

不过选项中没有直接给出 `v >= 0`，需要结合 `v` 的奇偶性判断。

`v` 是 $n$ 个 $1$ 或 $-1$ 的和，所以：

$$
v\equiv n\pmod 2
$$

分两种情况：

- 当 $n$ 为偶数时，`n & 1` 等于 $0$，条件 `v >= (n & 1)` 就是 `v >= 0`；
- 当 $n$ 为奇数时，`v` 一定是奇数，不可能等于 $0$，所以 `v >= 0` 等价于 `v >= 1`。此时 `n & 1` 等于 $1$，条件仍然成立。

因此：

```cpp
v >= (n & 1)
```

与 `v >= 0` 完全等价，⑤处应填：

```cpp
if (v >= (n & 1)) res[j] = 'A';
else res[j] = 'B';
```

故选 **A**。


补全后的关键代码为：

```cpp
c[i] = m - 2 * x[i];

// ...

ull g = mask ^ (mask >> 1);
ull d = g ^ lst;
int k = __builtin_ctzll(d);
C -= 2ll * s[k] * c[k];

// ...

if (v >= (n & 1)) res[j] = 'A';
else res[j] = 'B';
```

