('Xesir', 'col-gram-auto--xesir', '`auto` 的神秘用法 · Xesir', $AKB391$## 算法原理

`auto` 是 C++11 引入的类型推导关键字，让编译器根据初始化表达式自动推断变量类型，使用非常方便。说白了就是**你不写类型，编译器替你写**：它盯着 `=` 右边的表达式，推出左边变量该是什么类型。所以 `auto x;` 这种不给初值的写法是编译不过的。

它的价值在于「省事」和「防写错」两件事：类型长得离谱时（比如 `map<int,int>::iterator`）不用手抄；类型随模板变化时也不用挨个改。往下按场景拆开讲。

## 逐行代码解析

按使用场景分块，都是关键片段，拼不拼成完整程序无所谓。

### 遍历容器（最常用）

```cpp
for (auto it = mp.begin(); it != mp.end(); ++it)   // 不用写 map<int,int>::iterator
for (auto &x : vec) x *= 2;                        // 引用可修改
for (const auto &x : vec) cout << x;               // 只读，避免拷贝
```

- 第一行用 `auto` 接迭代器，省掉那一长串类型名，改容器类型时也不用动。
- 第二行的 `&` 是关键：不加 `&` 就是拷贝一份，`x *= 2` 改的是副本，原数组纹丝不动。
- 第三行 `const auto &` 是只读遍历的标配：既省拷贝，又防止手滑改到元素。

### 简化复杂类型声明

```cpp
auto p = make_pair(1, "hello");                    // pair<int, const char*>
auto f = [](int x) { return x * x; };              // lambda 类型
auto cmp = [](int a, int b) { return a > b; };     // 自定义排序
priority_queue<int, vector<int>, decltype(cmp)> pq(cmp);
```

- `auto` 天生适合接 `make_pair`、迭代器、lambda 这类「类型名根本写不出来」的东西。
- lambda 的类型是编译器生成的匿名类型，只能靠 `auto` 或 `decltype` 接住，手写是写不出来的。
- 最后一行把 lambda 交给优先队列当比较器：`decltype(cmp)` 取出 lambda 的类型，构造时再把 `cmp` 塞进去。

### 返回值类型推导（C++14）

```cpp
auto add(int a, int b) { return a + b; }           // 返回 int
template<class T, class U> auto mul(T a, U b) { return a * b; }
```

- 函数返回类型写 `auto`，编译器按 `return` 的表达式推断，适合模板函数。
- 踩坑点：多个 `return` 语句必须推出同一种类型，不然编译直接报错。

### 结构化绑定 + auto（C++17）

```cpp
auto [u, v] = edge;                                // 直接拆 pair
for (auto [k, v] : mp) cout << k << " " << v;      // 遍历 map
```

- `auto [u, v] = edge;` 把 `pair` 一次性拆成两个变量，比 `edge.first` / `edge.second` 清爽得多。
- 遍历 `map` 时直接拆成键值两个变量，代码读起来像自然语言。

### decltype(auto)（C++14）

```cpp
decltype(auto) foo() { return expr; }              // 保持 expr 的引用/值类型
```

- `auto` 会剥掉引用和 `const`，而 `decltype(auto)` 保留，用于完美转发这类场景。
- 平时写返回值用 `auto` 就够，`decltype(auto)` 是遇到引用语义时才请出来的。

## 复杂度分析

`auto` 是彻头彻尾的**编译期**行为：类型在编译阶段就定死了，运行期不会多花一条指令，**不会比手写类型慢一丝**。它唯一增加的是编译器的推导工作量和编译时间，对程序运行复杂度没有影响。

真正要留意的反而是遍历时 `auto` 不小心触发拷贝，那才是实打实的运行期开销——所以引用 `&` 该加就加。一句话：`auto` 用得好，零成本；忘了 `&`，白拷贝。

## 适用场景

- 类型名又长又难写：迭代器、`map`、嵌套模板。
- 类型根本无法书写：lambda、`make_pair` 的返回类型。
- 模板泛型代码：类型随模板参数变化，写死容易改漏。
- C++17 起遍历 `map`、拆 `pair`、拆 `tuple`，直接结构化绑定一把梭。

## 常见陷阱与注意事项

1. `auto` **丢掉引用和 const**：`const int x = 1; auto y = x;` 里 `y` 是 `int`，不是 `const int`；想保住引用要显式写 `auto&` 或 `auto&&`。
2. 遍历时忘了 `&` 会**拷贝**：`for (auto x : vec)` 改 `x` 改不到原容器，大对象还会白白复制一遍。
3. `auto` 不能「猜」：`auto x;` 没有初值推不出类型，直接编译报错。
4. 多个 `return` 类型不一致会报错：`auto` 函数要求所有 `return` 推出同一类型。
5. 用 `auto` 接 `size()` 这类无符号返回值时，和 `int` 混比可能冒出符号警告，需要时手动写 `int` 或转型。
6. 别滥用：类型很直观时写 `auto` 反而降低可读性，`int i` 比 `auto i` 更让人一眼看懂。

## 对比与扩展

| 写法 | 是否保留引用/const | 典型用途 |
|---|---|---|
| `auto` | 否（剥掉） | 通用推导 |
| `auto&` / `const auto&` | 是 | 遍历、避免拷贝 |
| `decltype(expr)` | 是（且不推导值） | 声明同类型变量 |
| `decltype(auto)` | 是 | 完美转发、返回引用 |

扩展：

- `decltype` 只关心类型、不计算表达式，适合「我想再要一个同类型的变量」。
- C++17 的 `auto` 还能用在非类型模板参数上：`template<auto N>`，把常量当模板参数传。
- 结构化绑定配 `auto&` 可以改原容器元素，这个组合在处理 `map` 时很好用。$AKB391$, '实用工具', array['auto', '类型推导', 'C++11', '结构化绑定', 'decltype'], 'col-hub-gram', null, 'knowledge'),
('Xesir', 'col-gram-builtin--xesir', '`__builtin` 全家桶 · Xesir', $AKB392$## 算法原理

`__builtin` 是 GCC/Clang 提供的一组**编译器内置函数**，它们直接映射到 CPU 指令（或者很短的位运算序列），**常数极小**，常用于位运算加速。因为编译器认识它们，所以不会被当成普通函数调用，从根上就没有函数调用开销。

OI 里最常打交道的几位：`popcount`（数 1）、`clz` / `ctz`（数前导零 / 末尾零）、`ffs`（最低位 1 的位置）、`parity`（1 的个数的奇偶性）。它们几乎都是 $O(1)$，是位运算题和状压 DP 的老朋友。

## 逐行代码解析

### 常用函数一览表

| 函数 | 功能 | 返回类型 | 复杂度 | 适用场景 |
|------|------|---------|--------|---------|
| `__builtin_popcount(x)` | 二进制中 1 的个数（32 位） | `int` | $O(1)$（硬件指令） | 状压 DP、位运算计数 |
| `__builtin_clz(x)` | 前导零个数（32 位，x>0） | `int` | $O(1)$ | 求最高位、快速 log2 |
| `__builtin_ctz(x)` | 末尾零个数（32 位，x>0） | `int` | $O(1)$ | 提取最低位 1、`lowbit` 的变种 |
| `__builtin_ffs(x)` | 最低位 1 的位置（从 1 开始） | `int` | $O(1)$ | 等同于 `ctz(x)+1` |
| `__builtin_parity(x)` | 二进制中 1 的奇偶性 | `int` | $O(1)$ | 校验、哈希 |

- 处理 `long long` 时函数名末尾加 `ll`，如 `__builtin_popcountll(x)`；`clz` / `ctz` 也有 `ll` 版。

### 枚举子集（状压常用）

```cpp
int S = 0b10110;
for (int sub = S; sub; sub = (sub - 1) & S) {
    int cnt = __builtin_popcount(sub);  // 当前子集的元素个数
}
```

- 枚举子集的经典套路：`sub = (sub - 1) & S` 依次枚举 $S$ 的所有非空子集。
- 顺手用 `popcount` 数出当前子集大小，比循环数位快得多。

### 快速求 log2（最高位）

```cpp
int msb = 31 - __builtin_clz(x);        // 对于 32 位整数
int msb64 = 63 - __builtin_clzll(x);    // 对于 64 位
```

- 最高位下标 = 位宽减 1 再减前导零个数，这就是 `clz` 最常见的用法。

### 提取最低位的 1

```cpp
int low = x & -x;                       // 经典 lowbit
int idx = __builtin_ctz(x);             // 最低位 1 的下标（从 0 开始）
```

- `x & -x` 取出最低位的 1 本身，`ctz` 取出它的下标，两者配合树状数组很常见。

### 判断是否为 2 的幂

```cpp
bool is_power_of_two = (x > 0) && (__builtin_popcount(x) == 1);
```

- 2 的幂在二进制里只有一个 1，用 `popcount == 1` 判断即可（别忘了 `x > 0`）。

### 枚举所有 1 位的位置

```cpp
for (int t = x; t; t &= t - 1) {
    int pos = __builtin_ctz(t);         // 当前最低 1 的位号
    // 处理 pos
}
```

- `t &= t - 1` 每次都消掉最低位的 1，循环次数正好是 1 的个数。

## 复杂度分析

这些函数基本都是**单条 CPU 指令**或常数条位运算，复杂度统一 $O(1)$：

- `popcount`：多数平台有专用指令，一条搞定。
- `clz` / `ctz`：同样有硬件指令（`BSR` / `BSF` 之类），常数极小。
- `parity` / `ffs`：由上面的指令组合而来，依然是常数级。

相比手写 while 循环数位，它们把 $O(\text{位数})$ 压成 $O(1)$，在状压题里累积起来差别明显。

## 适用场景

- 状压 DP：`popcount` 数集合大小，`lowbit` + `ctz` 取最低位。
- 位运算题：快速求最高位（`clz`）、最低位（`ctz`）、1 的个数（`popcount`）。
- 枚举子集 / 枚举二进制位：配合 `(sub-1)&S`、`t &= t-1` 两个套路。
- 需要「高效 log2」时，`31 - clz(x)` 比库函数 `log2` 更快更准。
- 判断 2 的幂、奇偶校验、哈希等零碎场景。

## 常见陷阱与注意事项

1. **`clz` / `ctz` 对 $x=0$ 未定义**：调用前必须保证 $x > 0$，否则结果没有意义（甚至可能读出随机值）。
2. **参数类型要匹配**：32 位函数配 `unsigned int`，64 位配 `unsigned long long`，用 `ll` 后缀版，类型混用可能出错。
3. **返回值是 `int`**：`popcount` 返回 `int`，别当成 `bool` 用；`parity` 返回 0/1 表示偶数/奇数个 1。
4. **`ffs` 从 1 开始计数**：`__builtin_ffs(x)` 等价 `__builtin_ctz(x) + 1`，数下标时注意起点。
5. **MSVC 下不存在这些函数**：跨平台需自己实现；OI 大多用 GCC，放心用。
6. **别和 std:: 版本混用**：C++20 的 `<bit>` 提供了 `std::popcount`、`std::countr_zero` 等，OJ 支持度不一，`__builtin` 仍是主流。

## 对比与扩展

| 需求 | `__builtin` 写法 | 手写版本 |
|---|---|---|
| 数 1 的个数 | `__builtin_popcount(x)` | `x &= x - 1` 循环 |
| 最高位下标 | `31 - __builtin_clz(x)` | while 移位 |
| 最低位下标 | `__builtin_ctz(x)` | while 移位 |
| 是否 2 的幂 | `__builtin_popcount(x) == 1` | `x & (x-1)` |

扩展：

- C++20 的 `<bit>`：`std::popcount`、`std::countr_zero`、`std::bit_width` 等，语义更安全，但要注意 OJ 支持度。
- `x & (x-1)` 消最低位 1、`x & -x` 取最低位 1，这两个位运算技巧和 `__builtin` 是黄金搭档。$AKB392$, '实用工具', array['__builtin', '位运算', '状压DP', 'popcount', 'clz', 'ctz'], 'col-hub-gram', null, 'knowledge'),
('Xesir', 'col-gram-io-tips--xesir', '输入输出相关冷知识 · Xesir', $AKB393$## 算法原理

OI 中 IO 效率往往决定程序的生死，尤其是大数据量时——同样的算法，别人 `scanf` 全过，你用没关同步的 `cin` 却全 T 掉。原因很简单：C++ 的 `cin` / `cout` 默认与 C 的 `stdio` **保持同步**，每次 IO 都要协调两边缓冲区，白白多花时间。

所以 IO 优化的主线就一句话：**减少同步、减少刷新、减少调用次数**。把同步关掉（`sync_with_stdio(false)`）、把 `endl` 换成 `'\n'`（不主动刷新）、大数据改用 `getchar` / `fread` 批量读，速度就能一节一节往上爬。

## 逐行代码解析

### 各 IO 方式对比

| 方式 | 速度 | 适用场景 | 优点 | 缺点 |
|------|------|---------|------|------|
| `cin` / `cout`（默认） | 慢 | 小数据（$10^5$ 以内） | 简洁，类型安全 | 慢，同步消耗大 |
| `cin` / `cout` + `ios::sync_with_stdio(false); cin.tie(nullptr);` | 快（竞赛最常用） | 常规数据（$10^6$） | 简洁，可关闭同步 | 不能与 `stdio` 混用 |
| `scanf` / `printf` | 较快 | 常规数据 | 简单，效率稳定 | 格式串繁琐，类型不安全 |
| `getchar()` / `putchar()` 快读快写 | 极快 | 大数据（$10^7$） | 极速，可自定义 | 实现麻烦，仅支持基本类型 |
| `fread` / `fwrite` | 最快 | 极限数据（$10^8$） | 批量读写，速度最快 | 代码冗长，需自己解析 |

- 一般做题默认用 `ios::sync_with_stdio(false)` 加 `'\n'` 就够了。

### 关闭同步流

```cpp
ios::sync_with_stdio(false);
cin.tie(nullptr);
cout.tie(nullptr);
```

- 让 C++ 流不再与 C 标准流同步，大幅提升 `cin` / `cout` 速度，但**不能再和 `scanf` / `printf` 混用**，混用会乱序。

### 使用 '\n' 而非 endl

- `endl` 会刷新缓冲区，拖慢速度；`'\n'` 不会。大数据输出时差异明显。
- 记住：`endl` = 换行 + 刷新，多出来的刷新就是白送的时间。

### 一次性输出

- 用 `std::ostringstream` 或直接 `string` 拼接，最后 `cout << str`，减少 IO 调用次数：

```cpp
string out;
out += to_string(ans);
out += '\n';
cout << out;
```

- 每次 `cout <<` 都可能触碰缓冲区，先拼成一个大字符串再输出，调用次数从 $n$ 降到 1。

### 快读模板（getchar 版本）

```cpp
inline int read() {
    int x = 0, f = 1; char ch = getchar();
    while (ch < '0' || ch > '9') { if (ch == '-') f = -1; ch = getchar(); }
    while (ch >= '0' && ch <= '9') { x = (x << 1) + (x << 3) + (ch ^ 48); ch = getchar(); }
    return x * f;
}
inline void write(int x) {
    if (x < 0) putchar('-'), x = -x;
    if (x > 9) write(x / 10);
    putchar(x % 10 + '0');
}
```

- `read` 用 `x = (x<<1) + (x<<3) + (ch^48)` 等价于 `x = x*10 + (ch-'0')`，位运算更快。
- `write` 是递归版，先把高位输出完再输出末位，天然正序。

### fread 批量读入（终极优化）

```cpp
const int BUFSIZE = 1 << 20;
char buf[BUFSIZE], *p1 = buf, *p2 = buf;
#define getchar() (p1 == p2 && (p2 = (p1 = buf) + fread(buf, 1, BUFSIZE, stdin), p1 == p2) ? EOF : *p1++)
```

- 一次 `fread` 把一大块数据读进缓冲区，`getchar` 从缓冲区取字符，系统调用次数骤减。
- 搭配上面的 `read()` 使用，适合 $10^7$ 以上输入。

### 文件读入 / 输出

- **重定向（最常用）**：

```cpp
freopen("data.in", "r", stdin);
freopen("data.out", "w", stdout);
```

之后所有 `cin` / `scanf` 和 `cout` / `printf` 都会从文件读写，OJ 提交时无需删除（OJ 没有对应文件就会回落到标准输入输出，CCF_NOI 系列基本通用要求）。

- **本地调试开关**：

```cpp
#ifdef LOCAL
    freopen("in.txt", "r", stdin);
    freopen("out.txt", "w", stdout);
#endif
```

编译时加 `-DLOCAL`，提交时去掉即可。

- **`ifstream` / `ofstream`**（面向对象方式）：

```cpp
ifstream fin("data.in");
ofstream fout("data.out");
fin >> x;
fout << x;
```

速度不如重定向，一般不用于 OI。

## 复杂度分析

IO 优化的「复杂度」体现在调用次数上：

- 默认 `cin` / `cout` 因为同步，相当于每次 IO 都带一个不小的常数因子。
- 关同步后，逻辑上仍是「读 $n$ 个数字」，但常数大幅缩小；`scanf` 与关同步的 `cin` 数量级相当。
- `getchar` 快读把每个字符的获取降到一次函数调用（乃至一次缓冲区访问），$O(1)$ 处理一位数字。
- `fread` 把 $O(n)$ 次系统调用压到 $O(n / \text{BUFSIZE})$，这是质变。

所以本质上优化的是**常数**，不改变算法复杂度，但在卡常题里常数就是生死。

## 适用场景

- 小数据：默认 `cin` / `cout` 直接用，别为了省事牺牲可读性。
- 常规数据（$10^6$ 级）：关同步 + `'\n'`，这是最常用的组合。
- 大数据（$10^7$ 级）：上 `getchar` 快读模板。
- 极限数据（$10^8$ 级）：`fread` 批量读入。
- 需要文件输入输出 / 本地调试时：`freopen` 或 `#ifdef LOCAL` 开关。

## 常见陷阱与注意事项

1. **关同步后别混用 `stdio`**：`ios::sync_with_stdio(false)` 之后再用 `scanf` / `printf` 可能乱序，二选一。
2. **`endl` 拖速度**：输出量大时 `endl` 的刷新开销很明显，统一用 `'\n'`。
3. **`#define getchar()` 的副作用**：重定义 `getchar` 后 `cin` / `scanf` 也会受影响，通常只在纯快读程序里这么干。
4. **`freopen` 的文件名**：写错文件名不会报错，程序会静默读空 / 写到别处，本地测试时务必核对。
5. **`__int128` 无法直接 IO**：`cin` / `cout` / `printf` 都不支持，要读字符串自己转，或扩展快读模板。
6. **输出末行换行**：有些 OJ 对行尾敏感，最好每行都以 `'\n'` 收尾。

## 对比与扩展

| 需求 | 推荐方案 |
|---|---|
| 省事 | 默认 `cin` / `cout` |
| 竞赛通用 | 关同步 + `'\n'` |
| 大数据 | `getchar` 快读 / `putchar` 快写 |
| 极限数据 | `fread` / `fwrite` |
| 文件 IO | `freopen` |

扩展：

- **`getchar_unlocked` / `putchar_unlocked`**（Linux 下非线程安全、但更快）：单线程程序里配合快读能再快一截。
- **`__int128` 的读写**：先读字符串再手写转换，或写成支持 `__int128` 的快读扩展。
- **`cout` 的 `rdbuf` 替换**：可挂自定义缓冲区，但很少用，了解即可。$AKB393$, '实用工具', array['输入输出', '快读快写', 'fread', 'freopen', '卡常', 'sync_with_stdio'], 'col-hub-io', null, 'knowledge'),
('Xesir', 'col-gram-local-debug--xesir', '本地调试 · Xesir', $AKB394$## 算法原理

调试是 OI 里最耗时的环节之一。你可能花 20 分钟写代码，然后花 2 小时找 bug。熟练掌握调试工具和技巧，能把 2 小时压到 20 分钟。~~从入门到放弃~~

调试的本质是**缩小嫌疑范围**：先分清是「编译错」「运行错（RE）」还是「答案错（WA）」，再针对性地二分排查——要么二分代码（注释法），要么二分数据（对拍）。本篇按「工具 → 断言 → 检查错误 → 看返回码 → 个人技巧」的顺序梳理一遍。

## 逐行代码解析

### Dev-C++ 相关功能

Dev-C++ 虽然年代久远，但依然是很多 OI 选手的入门 IDE，NOI Linux 环境下也会用到 Dev。

**常用调试功能**：

- **设置断点（F4 / Toggle Breakpoint）**：在行号左侧点击，程序运行到断点时会暂停，方便观察变量值。
- **单步执行（F7 / Step Into，F8 / Step Over）**：逐行执行代码，观察程序流向。
- **查看变量（Add Watch）**：右键变量 → Add Watch，在调试窗口实时跟踪变量变化。
- **查看调用栈（Call Stack）**：函数嵌套调用时，查看当前执行到哪一层。
- **条件断点**：断点右键 → 设置条件（如 `i == 5`），只有条件满足时才触发。

**编译器选项**：

- `-O2`：开启优化，释放版本用；调试时建议关闭，否则变量可能被优化掉，无法查看。
- `-g`：生成调试信息，调试时必须开。
- `-Wall -Wextra`：开启所有警告，很多 bug 在警告阶段就能发现（比如未使用的变量、符号比较警告）。

### assert（断言）

- 定义：`assert(condition);` 若 `condition` 为 `false`，程序会终止并输出错误位置。
- 实用用法：

```cpp
#include <cassert>
assert(n > 0);                    // 如果 n <= 0，程序崩溃并报错
assert(vec.size() > i);           // 防越界
```

- 可在 `#define NDEBUG` 后禁用所有 `assert`，提交时避免 RE（通常在 `#include <cassert>` 前定义）。
- 适合在调试阶段检查「不应该发生」的情况，如数组下标、指针非空等。
- **不能**用于 OJ 题目的正常逻辑判断（因为 RE 会判错）。

### try-catch 与 throw（异常处理）

- 定义：`throw` 抛出异常，`try-catch` 捕获并处理。
- 实用用法：

```cpp
try {
    if (x < 0) throw runtime_error("x 不能为负数");
    // 正常逻辑
} catch (const exception &e) {
    cerr << "错误: " << e.what() << '\n';
}
```

- OI 适用性：**几乎不用**！OJ 评测不关心异常处理，反而增加代码复杂度和运行开销。但了解它能帮助理解一些库函数的报错机制（如 `vector::at()` 抛出的 `out_of_range`）。

### 防溢出

- 整数溢出：`int` 范围约 $2\times10^9$，`long long` 约 $9\times10^{18}$。乘法前先估算，必要时用 `__int128`：

```cpp
__int128 prod = (__int128)a * b;   // 防止 a*b 爆 long long
```

- 检查结果溢出：可用 `__builtin_add_overflow(a, b, &res)`、`__builtin_sub_overflow(a, b, &res)`、`__builtin_mul_overflow(a, b, &res)`，溢出返回 `true`，否则返回 `false` 并将结果存入 `res`。

### 防类型混乱

- 隐式类型转换隐患：

```cpp
unsigned int a = 5;
int b = -1;
if (a > b) { ... }   // 这里 b 被转为 unsigned，变成巨大正数，条件为假！
```

- 解法：避免 `unsigned` 与 `signed` 混用，或强制转型。
- 浮点数比较用 `eps`：

```cpp
const double eps = 1e-9;
if (fabs(a - b) < eps) { ... }   // 而非 a == b
```

### 防越界（指针 / 迭代器）

- 使用迭代器时，确保 `it != vec.end()` 再解引用。
- 使用 `vector` 时，`reserve()` 预分配空间，避免 `push_back` 导致迭代器失效。
- 用 `if (l > r) return;` 提前处理空区间，防止递归无限。
- 数组越界：开数组时多开 $5 \sim 10$ 个（`const int N = 100000 + 10;`），减少意外越界导致的 RE。
- 使用 `vector` 的 `at()` 代替 `[]` 可检查越界（但会降低效率，仅调试时可用）。

### 程序异常返回码（RE 信息识别）

在本地运行程序时，操作系统会返回退出码，对应不同的错误类型：

| 返回码 | 常见原因 | 对应信号 | 典型场景 |
|--------|---------|---------|---------|
| `-1073741819`（Windows）/ `11`（Linux） | 段错误（Segmentation Fault） | SIGSEGV | 数组越界、访问空指针、栈溢出 |
| `-1073741571`（Windows）/ `8`（Linux） | 浮点异常（Floating Point Exception） | SIGFPE | 除以零、取模零 |
| `-1073741676`（Windows）/ `6`（Linux） | 非法指令（Illegal Instruction） | SIGILL | 调用不存在的函数、指令错乱 |
| `-1073740791`（Windows）/ `4`（Linux） | 总线错误（Bus Error） | SIGBUS | 内存未对齐（较罕见） |
| `0` | 正常退出 | — | 程序运行成功 |

**识别方法**：

- Windows 下的 Dev-C++ 会显示「程序返回 -1073741819」之类的提示。
- Linux 下 `./a.out` 运行后用 `echo` 打印退出码查看返回值，或用 `dmesg | tail` 查看内核日志。
- 常见 RE 的快速定位：
  - **段错误**：大概率是数组越界或递归爆栈（递归深度大时要注意，可改非递归或增大栈空间）。
  - **浮点异常**：检查所有除法、取模的分母是否为 0。
  - **溢出**：`long long` 不够时用 `__int128`，或调整算法避免大数。

### 个人调试技巧

**输出调试（printf 大法）**：

- 在关键位置输出变量值，观察程序流向。
- 使用 `cerr` 而非 `cout`，因为 `cerr` 不缓冲且仅在调试窗口显示（不会生成到输出文件中），可避免忘删输出错乱 WA。（但还是建议最后检查一遍删掉，毕竟 `cerr` 也耗时间，容易 TLE）

```cpp
cerr << "x = " << x << ", y = " << y << '\n';
```

- 配合 `#ifdef LOCAL` 控制调试输出，提交时自动屏蔽：

```cpp
#ifdef LOCAL
    cerr << "n = " << n << '\n';
#endif
```

**二分定位 bug**：

- 如果程序在某个位置出错，用二分法注释掉代码段，逐步缩小范围。
- 例如在 `solve()` 函数中，先检查输入是否正确，再检查核心逻辑，最后检查输出。

**对拍（与暴力程序对比）**：

- 写一个暴力解法（慢但绝对正确），用随机数据生成器，对比两者输出。
- 脚本自动化：

```cpp
while true; do
    ./gen > in.txt
    ./std < in.txt > ans.txt
    ./my < in.txt > out.txt
    diff ans.txt out.txt || break
done
```

**使用 valgrind（Linux）**：

- 检测内存泄漏和越界：

```cpp
valgrind --tool=memcheck ./a.out
```

- 虽然 OI 环境不一定有，但本地调试时非常强大。

**检查 undefined behavior**：

- C++ 中很多行为是未定义的（如 `i++ + ++i`），使用 `-fsanitize=undefined` 编译可检测：

```cpp
g++ -fsanitize=undefined -g -o a a.cpp
```

**注释法**：

- 把疑似出错的代码段注释掉，看程序是否还 RE。
- 如果 RE 消失，说明问题在注释掉的这段里，再逐步放回。

### 调试流程建议

1. 编译时开 `-Wall -Wextra -g`，处理所有警告。
2. 运行小样例，用 `cerr` 输出中间关键变量。
3. 若 RE，检查数组大小、递归深度、除零。
4. 若 WA，写暴力对拍，定位差异点。
5. 若问题复杂，用二分注释法缩小范围。
6. 最后清理调试代码，提交。

## 复杂度分析

调试技巧本身不改变算法复杂度，但改变的是**你自己的时间**：

- `cerr` 输出一次是 $O(1)$，但会占用运行时间，大量输出可能让程序 TLE。
- 对拍的成本 = 暴力程序复杂度 × 数据组数，暴力要「慢但绝对正确」，别把它写复杂。
- `-fsanitize=undefined` 会给程序加一层检查，运行变慢（常数变大），只适合本地调试。
- `assert` 在 `NDEBUG` 下会被完全去掉，对正式提交零开销。

## 适用场景

- 编译报错 / 警告：开 `-Wall -Wextra`，先把警告清零。
- 运行崩溃（RE）：看返回码定位段错误 / 浮点异常，检查数组、递归、除零。
- 答案错误（WA）：`cerr` 输出中间变量，或用对拍找反例。
- 疑难杂症：二分注释法缩小范围，`-fsanitize` 查未定义行为，`valgrind` 查越界和泄漏。

## 常见陷阱与注意事项

1. **忘删调试输出**：`cout` 的调试输出会被 OJ 判 WA，用 `cerr` 或 `#ifdef LOCAL` 包起来更安全（但也别忘清理）。
2. **调试时别开 `-O2`**：被优化掉的变量在调试器里看不到，调试用 `-O0 -g`。
3. **`assert` 带副作用**：`assert(f(x))` 里的函数调用在 `NDEBUG` 下也会消失，别把有副作用的语句塞进 `assert`。
4. **数组尺寸留足余量**：开数组多开 5~10 个（`const int N = 100000 + 10;`），越界往往就差那么一两个。
5. **递归深度**：深递归会爆栈（本地表现为段错误），必要时改迭代或加大栈空间。
6. **`freopen` 影响调试**：本地开了重定向后，忘了改回去会导致「没有输出」，注意区分是没输出还是输出到了文件。

## 对比与扩展

| 现象 | 首选手段 |
|---|---|
| 编译警告 | `-Wall -Wextra` |
| WA | `cerr` 输出 / 对拍 |
| RE（段错误） | 查数组越界、递归深度、空指针 |
| RE（浮点异常） | 查除零 / 取模零 |
| 未定义行为 | `-fsanitize=undefined` |
| 内存泄漏 / 越界 | `valgrind` |

扩展：

- **对拍自动化**：把 `gen` / `std` / `my` 三个程序用脚本串起来循环跑，一有差异就停，比手搓样例高效得多。
- **`__builtin_*_overflow`**：比「算完再判断是否溢出」更可靠，能在溢出发生的当下就抓住。
- **调试与算法分离**：把调试输出全部塞进 `#ifdef LOCAL`，正式提交时一行 `-DLOCAL` 都不带，干净利落。$AKB394$, '实用工具', array['调试', 'assert', '返回码', '对拍', 'sanitizer', 'Dev-C++'], 'col-hub-utility-debug', null, 'knowledge'),
('Xesir', 'col-gram-macro--xesir', '宏孩儿（#define、typedef 与 using） · Xesir', $AKB395$## 算法原理

头文件下三兄贵：`#define`、`using` 与 `typedef`，都能给一段代码起个「外号」。它们的本领相近，脾气却差很远。

先分清辈分：

- `#define` 属于**预处理器**。它在编译之前工作，做的事就是**纯文本替换**——把 `A` 无脑换成 `B`，替换完再交给编译器。它没有作用域、没有类型、不懂语法。
- `typedef` 是 C++98 的**类型别名**写法，有类型、有作用域，交给编译器处理。
- `using` 是 C++11 的新写法，同样是类型别名，但更灵活，还能做**模板别名**（`typedef` 做不到）。

一句话总结：`#define` 是「暴力的文本替换」，`typedef` / `using` 是「编译器认可的真别名」。能用后者就别用前者，这是老生常谈但依然有人记不住的忠告。

## 逐行代码解析

### 常用宏

```cpp
#define int long long              // 一键开 long long
#define For(i,x,y) for(int i=x;i<=y;i++)
#define all(x) x.begin(), x.end()  // 遍历神器
#define lowbit(x) (x & -x)         // 树状数组必备
#define ls dio[u].lc
#define rs dio[u].rc 
#define mid ((l+r)>>1)             // 线段树/二分常用
#define fi first
#define se second
#define pb push_back
#define vi vector<int>
#define PII pair<int, int>         // 单纯省字
```

- `#define int long long` 是最出圈的宏：全局把 `int` 偷换成 64 位，代价是常数变大、`main` 得写成 `signed main()`。
- 参数宏两侧的括号不能省：`#define lowbit(x) (x & -x)` 里那对括号是保命的，否则 `lowbit(a+b)` 展开后会跟着运算符优先级错位。
- `#define mid ((l+r)>>1)` 同理，双保险括号是为了不被外层运算符「吃掉」。

### 条件编译

```cpp
#ifdef LOCAL
    freopen("in.txt", "r", stdin);
#endif
```

- `#ifdef LOCAL` 表示「只有定义了 `LOCAL` 宏才编译这段」，本地调试时加 `-DLOCAL`，提交时去掉。
- 这是把调试代码和正式代码合进一份文件里的经典技巧。

### 可变参数宏（C++11）

```cpp
#define debug(...) fprintf(stderr, __VA_ARGS__)
debug("x = %d, y = %d\n", x, y);
```

- `__VA_ARGS__` 接住 `...` 里的全部参数，宏也能像函数一样接不定参数。
- 注意它依然是文本替换，报错位置会以展开后为准，调试时容易懵。

### typedef vs using

- `typedef` 是 C++98 的老写法，`using` 是 C++11 的新写法，更灵活。
- `using` 支持**模板别名**（`typedef` 不支持）：

```cpp
template<class T> using vec = vector<T>;           // using 模板别名
template<class T> using pii = pair<T, T>;
```

- 函数指针别名：

```cpp
typedef void (*Func)(int);                         // 老
using Func = void(*)(int);                         // 新（更直观）
```

- 函数指针别名这组对比最能说明问题：`using` 把新名字放左边、类型放右边，一眼能看出谁是谁；`typedef` 的嵌套括号则要反应半天。

## 复杂度分析

三者都是**编译期**的东西，运行期一条指令都不多。

- `#define` 的开销在预处理阶段：文本替换，宏越大、用得越多，编译越慢，但生成的代码与手写等价。
- `typedef` / `using` 只是给类型起别名，不生成任何代码，运行期开销为零。
- 真正要算「代价」的是可维护性：`#define` 无作用域、纯文本替换，一旦和同名变量撞上，报错信息会变得面目全非。

## 适用场景

- `#define`：`For` / `all` / `lowbit` 这类短小的代码片段替换，以及 `#ifdef` 条件编译。
- `typedef` / `using`：给类型起别名，让 `long long`、`pair<int,int>` 这类冗长类型变短。
- `using`：需要模板别名时是唯一选择。
- 定义常量时，优先 `const` / `constexpr` 而不是 `#define`。

## 常见陷阱与注意事项

1. **宏是文本替换，不是函数**：`#define sq(x) x*x` 在 `sq(a+b)` 下会展开成 `a+b*a+b`，参数和整体都要加括号。
2. **宏没有作用域**：一旦 `#define` 了，后面所有代码都受影响，容易和其他库撞名，必要时用 `#undef` 撤销。
3. **宏不能当变量用**：调试器看不到它，断点打进去也是一团展开后的代码，实际赛场能不用就不用。~~网赛用一用还是很方便的~~
4. **`#define int long long` 的连带后果**：开了它 `main` 要写 `signed main()`，而且全局常数变大，卡常题慎用。
5. **`typedef` 写不出模板别名**：`template<class T> typedef vector<T> vec;` 是非法的，只能改用 `using`。
6. **`#pragma once` 与头文件守卫**：`#pragma once` 比 `#ifndef/#define/#endif` 简洁，但老式守卫在跨文件同名时更稳，别一味图省事。

## 对比与扩展

| 维度 | `#define` | `typedef` | `using` |
|---|---|---|---|
| 处理阶段 | 预处理器（文本替换） | 编译器 | 编译器 |
| 有作用域 | 否 | 是 | 是 |
| 支持模板别名 | — | 否 | 是 |
| 可调试性 | 差 | 好 | 好 |

扩展：

- `constexpr` 定义常量，类型安全、可调试、能参与编译期计算，是 `#define` 常量的现代替代。
- `#undef` 用于「用完即撤」，避免宏污染扩散。
- `#pragma once` 是目前大多数编译器都支持的头文件去重方案。$AKB395$, '实用工具', array['宏', '#define', 'typedef', 'using', '条件编译', '模板别名'], 'col-hub-gram', null, 'knowledge'),
('Xesir', 'col-gram-sequence--xesir', '我的序列我做主：自定义比较规则 · Xesir', $AKB396$## 算法原理

C++ 内置的比较规则很单一：`sort` 默认按 `<` 升序，优先队列默认按 `<` 取最大（大根堆）。可现实是——我想按边权排序、想按距离取最小、想在结构体数组里按某个字段二分……内置规则根本不够用。

于是我们自己给「比较」下定义，让排序、优先队列、二分查找按我们的意愿工作。核心就一条：**告诉算法「谁排在谁前面」**。手段有四种：lambda、仿函数（重载 `operator()`）、普通函数指针，以及给类型重载 `operator<` / `operator>`。

## 逐行代码解析

### sort 的自定义比较

`sort` 接受第三个参数——比较器，返回 `true` 表示第一个参数应排在第二个前面。

- **Lambda 表达式**（最灵活）：

```cpp
vector<Edge> edges;
sort(edges.begin(), edges.end(), [](const Edge &a, const Edge &b) {
    return a.w < b.w;      // 按边权升序
});
```

- **函数对象（重载运算符）**：

```cpp
struct Cmp {
    bool operator()(const Edge &a, const Edge &b) const {
        return a.w < b.w;
    }
};
sort(edges.begin(), edges.end(), Cmp());
```

- **函数指针**（最好写）：

```cpp
bool cmp(const Edge &a, const Edge &b) { return a.w < b.w; }
sort(edges.begin(), edges.end(), cmp);
```

- 三种写法效果等价：lambda 最灵活（可就地捕获），仿函数能带自定义状态，函数指针最朴素。
- 注意比较器要满足**严格弱序**：`cmp(a,b)` 与 `cmp(b,a)` 不能同时为真，相等时都得返回 `false`。

### priority_queue 的自定义比较

- **默认是大根堆**（`less`），即 `priority_queue<T>` 等价于 `priority_queue<T, vector<T>, less<T>>`。
- **小根堆**：用 `greater<T>`，要求 `T` 可比较（有 `operator>`）：

```cpp
priority_queue<int, vector<int>, greater<int>> pq;   // 小根堆
```

- **自定义比较类**（和 `sort` 的仿函数类似，但语义相反）：

```cpp
struct Cmp {
    bool operator()(const Node &a, const Node &b) const {
        return a.dist > b.dist;   // 注意：这里 > 表示优先级小（小根堆）！
    }
};
priority_queue<Node, vector<Node>, Cmp> pq;  // 小根堆，按 dist 升序
```

- 这是最反直觉的一处：优先队列比较器的 `operator()` 返回 `true` 表示 `a` 的优先级**低于** `b`（`a` 沉到堆底），所以写 `>` 反而得到小根堆。

### 重载 operator< 用于 sort 和 set/map

```cpp
struct Edge {
    int u, v, w;
    bool operator<(const Edge &other) const {
        if (w != other.w) return w < other.w;
        if (u != other.u) return u < other.u;
        return v < other.v;
    }
};
set<Edge> st;                 // 自动按 operator< 排序
map<Edge, int> mp;            // 同理
```

- 把 `operator<` 写进结构体，`sort`、`set`、`map` 全都自动认识它，一举多得。
- 多关键字比较时按优先级依次比，最后一步保证「相等也不返回 true」，才符合严格弱序。
- 注意重载的是 `operator<`：`set` / `map` 只认 `<`，不认 `>`。

### lower_bound / upper_bound 自定义比较

适用于自定义结构体的数组，按某个字段查找，$O(\log n)$。

```cpp
vector<Edge> edges = ...;  // 假设已按 w 升序排序
Edge target; target.w = 5;
auto it = lower_bound(edges.begin(), edges.end(), target,
                       [](const Edge &a, const Edge &b) { return a.w < b.w; });
// 返回第一个 w >= target.w 的元素
```

- 前提是数组**已按同一规则排好序**，否则二分结果无意义。
- `lower_bound(begin, end, value, cmp)` 的 `cmp` 接受 `(element, value)` 或 `(value, element)`，顺序写反会得到相反结果。

### find

$O(n)$

```cpp
auto it = find(vec.begin(), vec.end(), v);
if (it != vec.end()) cout << *it;
```

- 线性查找，别在大数组里反复用；有序时优先二分。

### 常用函数对象（functional 头文件）

| 函数对象 | 作用 | 示例 |
|---------|------|------|
| `less<T>` | 小于比较（默认升序） | `sort(v.begin(), v.end(), less<int>())` |
| `greater<T>` | 大于比较（降序） | `sort(v.begin(), v.end(), greater<int>())` |
| `equal_to<T>` | 等于 | 用于 `find` 等 |
| `not_equal_to<T>` | 不等于 | 少见 |

- `less` / `greater` 就是标准库写好的仿函数，省得自己动手。

## 复杂度分析

- 比较器本身只决定「怎么比」，不改变算法的复杂度：`sort` 仍是 $O(n\log n)$（$n$ 次比较，每次比较器内部是 $O(1)$），一次 `push` / `pop` 的比较次数仍是 $O(1)$。
- 代价在于**比较函数写得好不好**：比较器里别做重活（别排序、别拷贝大对象），否则常数会爆炸。
- `find` 是 $O(n)$，`lower_bound` 是 $O(\log n)$，这个差距才是选它们时要看的。

## 适用场景

- `sort` 多关键字排序、按自定义字段排。
- `priority_queue` 需要小根堆，或按多个字段动态取最值（如 Dijkstra 按距离）。
- `set` / `map` 装自定义类型：必须提供 `operator<`。
- 结构体数组上按字段二分：`lower_bound` + 自定义比较器。

## 常见陷阱与注意事项

1. **优先队列的比较语义是反的**：`operator()` 返回 `true` 表示「优先级更低」，所以小根堆要写 `>`。这一条是历年血泪重灾区。
2. **比较器必须是严格弱序**：`cmp(a,b)` 和 `cmp(b,a)` 不能同时为真；相等情况要返回 `false`，否则 `sort` 可能越界崩溃。
3. **漏写 `const`**：仿函数的 `operator()` 和成员比较函数都建议加 `const`，否则在某些容器里编译不过。
4. **二分前必须先排序**，且排序规则要与二分比较规则一致，不然结果随机。
5. **`lower_bound` / `upper_bound` 的区别**：`lower_bound` 找第一个 `>=`，`upper_bound` 找第一个 `>`，两者配合能数出等于 `value` 的个数。
6. **`less` / `greater` 要带模板参数**：写成 `greater<int>()`，忘了 `<int>` 编译不过。

## 对比与扩展

| 场景 | 写法 | 认哪个运算符 |
|---|---|---|
| `sort` | 比较器 / `operator<` | `<` |
| `priority_queue` 大根堆 | 默认 `less` | `<` |
| `priority_queue` 小根堆 | `greater` / 自定义仿函数 | `>` |
| `set` / `map` | `operator<` | `<` |
| `lower_bound` | 比较器 | `<` |

扩展：

- `std::bind` 能绑定参数生成函数对象，但 lambda 更直观，OI 里很少用。
- `std::function` 是类型擦除的可调用对象包装，能存 lambda / 函数指针，但有额外开销，别在热路径频繁用。
- 三路比较（C++20）的 `<=>` 能自动生成全部比较运算符，但多数 OJ 还不支持 C++20，暂不引入。$AKB396$, '实用工具', array['自定义比较', '排序', '优先队列', '运算符重载', '仿函数', 'lower_bound'], 'col-hub-gram', null, 'knowledge'),
('dbywsc', 'col-gram-string-ops--dbywsc', '字符串常用操作 · dbywsc', $AKB397$## 算法原理

C++ 的 `std::string` 封装了字符数组的大部分操作，配合 `cin` / `cout`、`getline` 和 STL 算法，可以完成竞赛中绝大多数字符串处理。

常见操作可以分成几类：

- 读入：`cin >> s` 读一个单词，`getline(cin, s)` 读一整行；
- 遍历：下标遍历、范围遍历、找最大值/最小值；
- 修改：插入、删除、替换、拼接；
- 查找：`find`、`rfind`、`find_first_of`；
- 截取：`substr`；
- 转换：`stoi` / `stoll` / `to_string`；
- 字符判断：`isdigit`、`isalpha`、`isalnum`、`islower`、`isupper`、`tolower`、`toupper`。

## 核心公式 / 状态定义与转移方程

- `s.size()` / `s.length()`：字符串长度，返回无符号类型，和 `int` 比较时注意符号。
- `s[i]`：下标从 $0$ 开始；越界是未定义行为。
- `s.substr(pos, len)`：从 `pos` 开始截取 `len` 个字符；`len` 省略时截到末尾。
- `s.find(t)`：返回第一次出现的位置，找不到返回 `string::npos`（不是 $-1$，虽然常和 $-1$ 比较）。
- `s.insert(pos, t)`：在 `pos` 前插入；`s.erase(pos, len)`：从 `pos` 起删除 `len` 个。
- `s.replace(pos, len, t)`：把从 `pos` 起 `len` 个字符替换成 `t`。
- `stoi(s)` / `stoll(s)`：字符串转 `int` / `long long`；`to_string(x)`：数字转字符串。

## 逐行代码解析

### 循环读入

```cpp
char ch;
while (cin >> ch) {
    cout << ch;
}
```

- `cin >> ch` 会跳过空白字符，逐字符读入直到输入结束。
- 若要保留空格/换行，用 `getline(cin, s)`。

```cpp
string a, b;
while (cin >> a >> b) {
    // 处理一对字符串
}
```

- 适合没有固定组数的多测输入；`cin` 在读到 EOF 时返回假，循环结束。

### 遍历找最值

```cpp
char maxn = 0, minn = 127;
int idx = 0, idx2 = 0;
for (int i = 0; i < (int)s.size(); i++) {
    if (s[i] > maxn) {
        maxn = s[i];
        idx = i;
    }
    if (s[i] < minn) {
        minn = s[i];
        idx2 = i;
    }
}
```

- 找第一个最大值/最小值：用严格大于/小于，只在第一次出现时更新。
- 找最后一个最大值/最小值：用大于等于/小于等于，最后一次出现时更新。
- `s.size()` 是无符号类型，循环变量用 `int` 时建议先转换，避免符号比较警告。

### 插入

```cpp
s.insert(idx, str);      // 在 s 的第 idx 个字符前插入 str
s.insert(idx + 1, str);  // 在 s 的第 idx 个字符后插入 str
```

- `insert(pos, t)` 的 `pos` 是下标，范围 $0\sim size$；`pos == size` 表示末尾插入。

### 删除

```cpp
s.erase(idx, len);   // 从 idx 起删除 len 个字符
```

- 若 `len` 省略，删除从 `idx` 到末尾。
- 删除后字符串长度变小，后续下标要重新计算。

### 查找

```cpp
size_t p = s.find(str);
if (p != string::npos) {
    cout << p << '\n';
}
```

- `find` 返回第一次出现的位置；找不到返回 `string::npos`。
- `rfind` 从后往前找；`find_first_of` 找任意一个字符第一次出现。

### 替换

```cpp
s.replace(start, len, str);   // 把 [start, start+len) 替换成 str
```

- `start` 是下标，`len` 是要替换的长度。
- 替换后字符串长度可能变化。

### 截取

```cpp
string t = s.substr(start, len);   // 从 start 起截取 len 个字符
string u = s.substr(start);        // 截取到末尾
```

- `start` 不能越界；`len` 超过剩余长度时只截到末尾。

### 拼接

```cpp
string ans;
for (int i = 1; i <= n; i++) {
    ans = s[i] + ans;   // 头插，最终顺序会反过来
}
```

```cpp
string ans;
for (int i = 1; i <= n; i++) {
    ans = ans + s[i];   // 尾插，保持原顺序
}
```

- `ans = s[i] + ans` 是头插，适合逆序构造；`ans += s[i]` 是尾插。
- 大量拼接时 `+=` 通常比反复 `ans = ans + ...` 更高效。

### 字符串转数字

```cpp
string s;
cin >> s;
int x = stoi(s);        // 转 int
long long y = stoll(s); // 转 long long
```

- `stoi` / `stoll` 会跳过前导空格，遇到非数字停止；转换失败会抛异常。
- 也可以用手写 `for` 逐位累加，避免异常开销。

### 数字转字符串

```cpp
int x;
cin >> x;
string s = to_string(x);
```

- `to_string` 支持整数、浮点数；浮点数的格式由实现决定。

### 大小写转换

```cpp
char c = 'a';
if (islower(c)) c = toupper(c);   // 小写转大写
if (isupper(c)) c = tolower(c);   // 大写转小写
```

- `tolower` / `toupper` 返回 `int`，赋给 `char` 时注意转换。
- 只对字母有效，其他字符原样返回。

### 整行读入

```cpp
string s;
getline(cin, s);
```

- `getline` 读入一整行，保留空格。
- 如果前面用了 `cin >>`，缓冲区里可能残留换行符，先 `cin.ignore()` 再 `getline`。

### 字符判断

```cpp
if (isdigit(c)) { /* 数字字符 */ }
if (isalpha(c)) { /* 字母 */ }
if (isalnum(c)) { /* 字母或数字 */ }
```

- 这些函数接收 `unsigned char` 或 `EOF`；传负的 `char` 可能未定义，必要时先转 `unsigned char`。

## 复杂度分析

- `size` / 下标访问：$O(1)$。
- `find` / `rfind`：最坏 $O(nm)$（朴素匹配）；`substr` / `insert` / `erase` / `replace`：$O(n)$。
- 拼接 `+=`：均摊 $O(1)$（按容量增长）；反复 `ans = ans + ...` 可能 $O(n^2)$。
- 字符串转数字 / 数字转字符串：$O(\text{长度})$。

## 适用场景

- 读入单词、整行、逐字符处理。
- 统计字符出现次数、找最大/最小字符、判断回文。
- 插入、删除、替换、截取子串。
- 字符串与数字互转。
- 大小写转换、字符类型判断。
- 构造答案字符串、逆序拼接。

## 常见陷阱与注意事项

1. **`cin >> s` 不读空格**：需要整行用 `getline`；`cin >>` 后接 `getline` 要先 `cin.ignore()`。
2. **`s.size()` 是无符号类型**：和 `int` 比较时可能出现符号问题；循环用 `(int)s.size()` 或 `size_t`。
3. **`find` 找不到返回 `string::npos`**：不要直接和 $-1$ 比较，虽然 `npos` 通常是最大值；用 `!= string::npos`。
4. **下标越界**：`s[i]` 不检查边界；`substr` / `erase` / `replace` 的 `pos` 要在合法范围。
5. **`insert` / `erase` 后下标变化**：修改后旧下标可能失效，重新计算。
6. **`tolower` / `toupper` 返回 `int`**：赋给 `char` 时显式转换；参数用 `unsigned char`。
7. **`stoi` 异常**：输入不合法会抛异常；竞赛中可手写转换或先判断。
8. **大量字符串拼接**：`ans = ans + s` 可能 $O(n^2)$，用 `ans += s` 或 `reserve`。

## 对比与扩展

- **`string` vs `char[]`**：`string` 自动管理内存、支持动态长度；`char[]` 更快但容易越界。
- **`cin >>` vs `getline`**：前者按空白分割，后者读整行；混合使用时注意缓冲区。
- **`find` vs KMP**：`find` 是朴素匹配，最坏 $O(nm)$；需要线性匹配时用 KMP / Z 函数。
- **`to_string` vs `sprintf`**：`to_string` 更现代、类型安全；`sprintf` 格式控制更强。
- **讲义练习**：循环读入、字符串最值、插入/删除/查找/替换/截取、字符串与数字互转、大小写转换。$AKB397$, '实用工具', array['字符串', 'STL', 'string', '语法', '输入输出'], 'col-hub-gram', null, 'knowledge'),
('Xesir', 'col-gram-struct--xesir', '神秘结构体 · Xesir', $AKB398$## 算法原理

先破一个迷思：C++ 里 `struct` 和 `class` 都是**类**，区别**仅仅**在于成员的默认访问权限——`struct` 默认 `public`，`class` 默认 `private`。别的特性一个不少：成员变量、成员函数、构造函数、析构函数、继承、多态、访问控制，两边都能用。

那 OI 里为什么几乎清一色用 `struct`？因为它默认 `public`，省去满篇写 `public:` 的麻烦。它的核心用途就一个：把**一堆相关的数据打包成一个整体**——一条边、一个点、一个状态，顺手再给它配几个成员函数（尤其是比较运算），让 `sort` 和优先队列直接认识它。

## 逐行代码解析

### 共同点与区别

`struct` 和 `class` 可用的特性完全一样：

- **成员变量**：存储数据。
- **成员函数**：操作数据的函数。
- **构造函数**：初始化对象（可重载）。
- **析构函数**：清理资源（OI 中很少用到）。
- **继承与多态**：支持继承，但 OI 中极少使用。
- **访问控制**：`public`、`protected`、`private` 都支持。

| | `struct` | `class` |
|---|---|---|
| 默认访问权限 | `public` | `private` |
| 默认继承权限 | `public` | `private` |
| 用途习惯 | 纯数据聚合（边、点、状态） | 封装复杂的抽象数据类型 |

- OI 里几乎只用 `struct`，因为聚合数据时默认 `public` 更省事。

### 存边 / 存点（最常用）

```cpp
struct Edge { int to, w, next; };
struct Node { int x, y, dist; };
```

- 最常见的用途：把一条边的三个字段打包，边数组就是 `Edge e[N]`。
- 结构体数组可以像普通数组一样用，也能花括号初始化。

### 构造函数快速初始化

```cpp
struct Point {
    int x, y;
    Point() : x(0), y(0) {}                     // 默认构造函数
    Point(int a, int b) : x(a), y(b) {}         // 带参构造
};
// 使用：
Point p1;          // (0,0)
Point p2(3, 4);    // (3,4)
vector<Point> pts;
pts.push_back({1, 2});        // 直接花括号（聚合初始化）
```

- 冒号后面的 `x(0), y(0)` 是成员初始化列表，比在函数体里赋值更直接。
- `Point()` 带默认值让 `Point p1;` 就能得到 `(0,0)`。

### 成员函数（常用于自定义比较）

```cpp
struct Node {
    int val, id;
    bool is_ok() const { return val > 0; }      // 成员函数
};
```

- 成员函数可以直接访问自己的成员，末尾的 `const` 表示不改动成员，比较函数一般都要加。

### 运算符重载（核心）

```cpp
struct Edge {
    int u, v, w;
    bool operator<(const Edge &other) const {   // 用于 sort 默认升序
        return w < other.w;                     // 按边权排序
    }
};
// 用于优先队列的小根堆（注意重载 > 或者自定义 Compare）
struct Node {
    int dist, id;
    bool operator>(const Node &other) const {   // 用于 priority_queue 小根堆
        return dist > other.dist;
    }
};
priority_queue<Node, vector<Node>, greater<Node>> pq;  // 需要 operator>
```

- `sort` 默认按 `operator<` 升序，所以重载 `<` 就能让 `sort(edges.begin(), edges.end())` 直接生效。
- 优先队列的 `greater<Node>` 调用的是 `operator>`，这才是上面第二个例子里要重载 `>` 的原因。

### 友元函数

```cpp
struct Point {
    int x, y;
    friend bool operator==(const Point &a, const Point &b) { return a.x == b.x && a.y == b.y; }
};
```

- 友元函数能访问结构体的私有成员，重载运算符时用得上；OI 里很少遇到访问控制，所以不常用。

## 复杂度分析

结构体本身不引入算法复杂度，它的开销体现在**内存布局**和**拷贝**上：

- 成员按声明顺序排列，可能因**内存对齐**在成员之间插入填充字节，结构体的实际大小往往大于各成员之和；对大结构体用 `sizeof` 看一眼心里有数。
- 按值传参、按值遍历都会整份拷贝，大结构体要用 `const T&`。
- 运算符重载是普通函数，没有额外运行期代价，`sort` 的复杂度仍由排序算法决定，即 $O(n\log n)$。

## 适用场景

- 打包边、点、状态：图论邻接表、堆里的节点、DP 状态。
- 让自定义类型支持 `sort` / `set` / `map` / 优先队列：重载 `<` 或 `>`、写仿函数。
- 多字段返回（虽然 `pair` / `tuple` 也行，字段多了结构体更清晰）。
- 位域节省内存：状态压缩、二进制序列化。

## 常见陷阱与注意事项

1. **比较函数记得加 `const`**：写 `bool operator<(const Edge&) const`，漏了末尾的 `const` 在 `set` / `map` 里可能编译不过。
2. **运算符重载的语义**：`sort` 认 `<`，优先队列的 `greater` 认 `>`，两者别搞混（详见「我的序列我做主」）。
3. **内存对齐**：结构体大小不等于成员大小之和，敏感场景（`memcpy`、位域混合）要按 `sizeof` 计算。
4. **聚合初始化有前提**：`{}` 直接初始化要求是聚合类型，一旦自己写了构造函数，就不再是聚合，`pts.push_back({1, 2})` 会失效（除非补上对应构造函数）。
5. **结构体数组的初值**：全局/静态数组会自动清零，函数内的局部数组是随机的，别忘记初始化。
6. **位域不能取地址**：位域成员没法用 `&` 取地址，也不能直接读入输出。

## 对比与扩展

| 维度 | `struct` | `class` |
|---|---|---|
| 默认访问权限 | `public` | `private` |
| 默认继承 | `public` | `private` |
| OI 使用频率 | 高 | 低 |

扩展：

- **聚合初始化与 pair**：简单二元组用 `pair`、需要运算符重载的用 `struct`，殊途同归。
- **位域**：`struct Flags { unsigned int a : 1, b : 2, c : 3; };` 各占 1、2、3 位，用于省内存的位打包。
- **POD 类型**（Plain Old Data）：与 C 兼容、可直接 `memcpy` 的结构体，做二进制序列化时有用。$AKB398$, '实用工具', array['结构体', 'struct', 'class', '运算符重载', '构造函数', '位域'], 'col-hub-gram', null, 'knowledge'),
('Xesir', 'col-gram-type-overview--xesir', '变量与函数类型大全 · Xesir', $AKB399$## 算法原理

C++ 是一门**静态类型**语言：每个变量、每个表达式的类型在编译期就确定了，类型决定了它能存什么、占多少字节、能做哪些运算。这一篇把常见的内置类型和扩展类型整理成一张总表，顺手把容易踩的类型转换坑一起讲了。

看类型抓住两件事就行：**位宽**（决定取值范围）和**符号性**（决定正负怎么表示）。搞不清这两个，溢出和符号混用就会轮番来问候你。

## 逐行代码解析

### 整型家族

| 类型 | 说明 | 大小（常见） | 实用场景 |
|------|------|-------------|---------|
| `bool` | 布尔型变量 | 1B | 条件判断 ~~居然不是1bit~~ |
| `char` | 单字符 ASCLL 编码 | 1B | ~~我也是整型没想到吧~~ |
| `short` | 有符号 16 位整数 | 2B | 极致压内存时用 |
| `int` | 有符号 32 位整数 | 4B | 通用整数 |
| `unsigned int` | 无符号 32 位整数 | 4B | 位运算，非负计数 |
| `long long` | 有符号 64 位整数 | 8B | 大整数（$10^{18}$） |
| `unsigned long long` | 无符号 64 位整数 | 8B | 位掩码，哈希，自然溢出模值 |
| `__int128` | 128 位有符号整数 | 16B | 乘法中间结果防溢出，特大数处理 |
| `unsigned __int128` | 128 位无符号整数 | 16B | 同上，无符号版本 |

- `char` 本质是 1 字节整数，所以 `'a' + 1` 是合法的，别被它字面的样子骗了。~~它自己都没想到~~
- `long long` 约 $9\times10^{18}$，两个 $10^9$ 相乘就爆了，这类乘法中间结果记得上 `__int128`。

### 浮点型家族

| 类型 | 说明 | 大小 | 实用场景 |
|------|------|------|---------|
| `float` | 单精度浮点 | 4B | 一般不用（精度低） |
| `double` | 双精度浮点 | 8B | 浮点数默认选择 |
| `long double` | 扩展精度 | 12/16B | 高精度浮点运算（小心常数） |

- 默认选 `double` 就对了；`float` 精度太丢人，`long double` 运算慢，用之前得想清代价。

### 修饰符家族

| 类型 | 说明 | 实用场景 |
|--------|------|---------|
| `const` | 不可修改 | 函数参数只读、全局常量 |
| `constexpr` | 编译期常量 | 数组大小、模板参数、编译期计算 |
| `static` | 静态存储期 | 局部变量保留值、全局变量隐藏 |
| `extern` | 外部链接 | 跨文件共享全局变量 |
| `inline` | 内联展开 | 头文件中的短函数、减少调用开销 |
| `volatile` | 防优化 | 嵌入式/多线程（OI 中极少用） |

- `constexpr` 是「编译期就能算出来的常量」，可以当数组大小、模板参数，比 `#define` 安全。
- `static` 放进函数里能让局部变量「记住」上次的值，少写全局变量。

### 复合类型家族

| 类型 | 说明 | 实用场景 |
|---------|------|---------|
| `T*` | 指针 | 动态数组、链表、传参修改 |
| `T&` | 左值引用 | 传参避免拷贝、修改原变量 |
| `T&&` | 右值引用 | 移动语义（OI 中较少） |
| `T[]` | 数组 | 静态/动态数组 |
| `pair<T1,T2>` | 二元组 | 返回两个值、存边 |
| `tuple<T1,T2,...>` | 多元组（C++11） | 返回多个值（结构化绑定拆） |
| `function<T>` | 可调用对象包装 | 存 lambda、回调、递归 |
| `decltype(expr)` | 推导表达式类型 | 声明同类型变量 |

- 传大对象（`vector`、`string`）时用 `const T&`，避免整份拷贝。

### 函数修饰家族

| 类型 | 说明 | 实用场景 |
|---------|------|---------|
| `void` | 无返回值 | 无返回值的函数 |
| `auto` 返回 | 返回类型推导 | 模板函数、lambda |
| `->` 尾置返回 | 指定返回类型 | 返回值依赖参数类型时 |
| `noexcept` | 不抛异常 | 优化（OI 中极少） |
| `override` | 显式重写 | 继承（OI 中极少） |

- 尾置返回 `auto f(...) -> T` 用于返回类型依赖参数的模板函数。

### 类型转换

- `(type)expr`（C 风格）→ 不推荐，不安全。
- `static_cast<type>(expr)` → 常用，编译期转换。
- `dynamic_cast<type>(expr)` → 多态向下转换（OI 中极少）。
- `reinterpret_cast<type>(expr)` → 位模式重解释（慎用）。
- `const_cast<type>(expr)` → 去 `const`（慎用）。
- 一句话：能用 `static_cast` 就用它，`reinterpret_cast` / `const_cast` 属于「知道自己踩雷还偏要踩」的情况。

### 位宽类型与 size_t

- **位宽类型（C++11）**：`#include <cstdint>` 后用 `int32_t`、`int64_t`、`uint64_t`，保证固定大小。
- **`size_t`**：`sizeof` 的返回值类型，无符号整数，遍历时和 `int` 比较可能产生符号警告：

```cpp
for (int i = 0; i < (int)vec.size(); ++i)   // 显式转型，规避 size_t 与 int 比较的符号警告
```

## 复杂度分析

类型本身不产生算法复杂度，但**位宽决定了常数**：

- `bool` / `char` / `short` / `int` 的运算通常一条 CPU 指令搞定；`long long` 在 32 位平台上可能要拆成两条。
- `__int128` 是编译器软件模拟的，乘除远比 64 位慢，只能在中间结果防溢出时「用一次就下车」。
- 浮点运算里 `double` 是硬件级，`long double` 在部分平台是软件实现，慢一个量级。

选类型时「够用就行」：能 `int` 不 `long long`，能 `long long` 不 `__int128`。

## 适用场景

- 开数组、算范围时按位宽选类型：先估上界再挑 `int` / `long long` / `__int128`。
- 多值返回用 `pair` / `tuple`，存边、存点用它很顺手。
- 需要固定位宽（跨平台、位运算）时上 `int64_t` 这类位宽类型。
- 传参避免拷贝用 `const T&`，要修改原值用 `T&`。

## 常见陷阱与注意事项

1. **溢出**：`int` 约 $2\times10^9$，`a*b` 里两个 `int` 相乘会先按 `int` 算再赋值，中间就爆了；乘法前先转 `long long` 或 `__int128`。
2. **符号混用**：`unsigned int a=5; int b=-1; if (a>b)` 里 `b` 会被转成无符号的巨大正数，条件为假——`unsigned` 和 `signed` 别混着比。
3. **浮点比较**：别写 `a == b`，用 `fabs(a-b) < eps`（`eps` 取 $10^{-9}$ 这类）。
4. **`size_t` 与 `int` 比较**：`size_t` 是无符号的，和负数或 `int` 比可能触发警告甚至逻辑反转，必要时显式转型。
5. **`char` 的符号性**：`char` 是否有符号由实现决定，当整数用时统一写 `signed char` / `unsigned char` 更稳。
6. **`long double` 的 printf**：得用 `%Lf`，用错格式符结果直接乱掉。

## 对比与扩展

| 需求 | 推荐类型 | 备注 |
|---|---|---|
| 通用整数 | `int` | 够用就别加长 |
| 大整数 | `long long` | 约 $9\times10^{18}$ |
| 乘法中间结果 | `__int128` | 防溢出，慢 |
| 浮点 | `double` | 默认 |
| 高精度浮点 | `long double` | 慢，慎用 |
| 固定位宽 | `int64_t` 等 | 需 `<cstdint>` |

扩展：

- **位运算配合无符号**：`unsigned` 的自然溢出在哈希、模 $2^{64}$ 场景下反而是特性。
- **`__int128` 的输入输出**：没有现成支持，通常先读字符串再手写转换，或配合快读扩展。
- **类型转换与 static_cast**：固定用 C++ 风格转换，比 C 风格更安全、也更好定位问题。$AKB399$, '实用工具', array['类型系统', '整型', '浮点', '类型转换', 'constexpr', '位宽类型'], 'col-hub-gram', null, 'knowledge'),
